refreshingDeferred?.reject(error)\n      throw error\n    } finally {\n      this.refreshingDeferred = null\n      this._debug(debugName, 'end')\n    }\n  }\n\n  private async _notifyAllSubscribers(\n    event: AuthChangeEvent,\n    session: Session | null,\n    broadcast = true\n  ) {\n    const debugName = `#_notifyAllSubscribers(${event})`\n    this._debug(debugName, 'begin', session, `broadcast = ${broadcast}`)\n\n    try {\n      if (this.broadcastChannel && broadcast) {\n        this.broadcastChannel.postMessage({ event, session })\n      }\n\n      const errors: any[] = []\n      const promises = Array.from(this.stateChangeEmitters.values()).map(async (x) => {\n        try {\n          await x.callback(event, session)\n        } catch (e: any) {\n          errors.push(e)\n        }\n      })\n\n      await Promise.all(promises)\n\n      if (errors.length > 0) {\n        for (let i = 0; i < errors.length; i += 1) {\n          console.error(errors[i])\n        }\n\n        throw errors[0]\n      }\n    } finally {\n      this._debug(debugName, 'end')\n    }\n  }\n\n  /**\n   * set currentSession and currentUser\n   * process to _startAutoRefreshToken if possible\n   */\n  private async _saveSession(session: Session) {\n    this._debug('#_saveSession()', session)\n    // _saveSession is always called whenever a new session has been acquired\n    // so we can safely suppress the warning returned by future getSession calls\n    this.suppressGetSessionWarning = true\n    await removeItemAsync(this.storage, `${this.storageKey}-code-verifier`)\n    // Create a shallow copy to work with, to avoid mutating the original session object if it's used elsewhere\n    const sessionToProcess = { ...session }\n\n    const userIsProxy =\n      sessionToProcess.user && (sessionToProcess.user as any).__isUserNotAvailableProxy === true\n    if (this.userStorage) {\n      if (!userIsProxy && sessionToProcess.user) {\n        // If it's a real user object, save it to userStorage.\n        await setItemAsync(this.userStorage, this.storageKey + '-user', {\n          user: sessionToProcess.user,\n        })\n      } else if (userIsProxy) {\n        // If it's the proxy, it means user was not found in userStorage.\n        // We should ensure no stale user data for this key exists in userStorage if we were to save null,\n        // or simply not save the proxy. For now, we don't save the proxy here.\n        // If there's a need to clear userStorage if user becomes proxy, that logic would go here.\n      }\n\n      // Prepare the main session data for primary storage: remove the user property before cloning\n      // This is important because the original session.user might be the proxy\n      const mainSessionData: Omit<Session, 'user'> & { user?: User } = { ...sessionToProcess }\n      delete mainSessionData.user // Remove user (real or proxy) before cloning for main storage\n\n      const clonedMainSessionData = deepClone(mainSessionData)\n      await setItemAsync(this.storage, this.storageKey, clonedMainSessionData)\n    } else {\n      // No userStorage is configured.\n      // In this case, session.user should ideally not be a proxy.\n      // If it were, structuredClone would fail. This implies an issue elsewhere if user is a proxy here\n      const clonedSession = deepClone(sessionToProcess) // sessionToProcess still has its original user property\n      await setItemAsync(this.storage, this.storageKey, clonedSession)\n    }\n  }\n\n  private async _removeSession() {\n    this._debug('#_removeSession()')\n\n    this.suppressGetSessionWarning = false\n\n    await removeItemAsync(this.storage, this.storageKey)\n    await removeItemAsync(this.storage, this.storageKey + '-code-verifier')\n    await removeItemAsync(this.storage, this.storageKey + '-user')\n\n    if (this.userStorage) {\n      await removeItemAsync(this.userStorage, this.storageKey + '-user')\n    }\n\n    await this._notifyAllSubscribers('SIGNED_OUT', null)\n  }\n\n  /**\n   * Removes any registered visibilitychange callback.\n   *\n   * {@see #startAutoRefresh}\n   * {@see #stopAutoRefresh}\n   */\n  private _removeVisibilityChangedCallback() {\n    this._debug('#_removeVisibilityChangedCallback()')\n\n    const callback = this.visibilityChangedCallback\n    this.visibilityChangedCallback = null\n\n    try {\n      if (callback && isBrowser() && window?.removeEventListener) {\n        window.removeEventListener('visibilitychange', callback)\n      }\n    } catch (e) {\n      console.error('removing visibilitychange callback failed', e)\n    }\n  }\n\n  /**\n   * This is the private implementation of {@link #startAutoRefresh}. Use this\n   * within the library.\n   */\n  private async _startAutoRefresh() {\n    await this._stopAutoRefresh()\n\n    this._debug('#_startAutoRefresh()')\n\n    const ticker = setInterval(() => this._autoRefreshTokenTick(), AUTO_REFRESH_TICK_DURATION_MS)\n    this.autoRefreshTicker = ticker\n\n    if (ticker && typeof ticker === 'object' && typeof ticker.unref === 'function') {\n      // ticker is a NodeJS Timeout object that has an `unref` method\n      // https://nodejs.org/api/timers.html#timeoutunref\n      // When auto refresh is used in NodeJS (like for testing) the\n      // `setInterval` is preventing the process from being marked as\n      // finished and tests run endlessly. This can be prevented by calling\n      // `unref()` on the returned object.\n      ticker.unref()\n      // @ts-expect-error TS has no context of Deno\n    } else if (typeof Deno !== 'undefined' && typeof Deno.unrefTimer === 'function') {\n      // similar like for NodeJS, but with the Deno API\n      // https://deno.land/api@latest?unstable&s=Deno.unrefTimer\n      // @ts-expect-error TS has no context of Deno\n      Deno.unrefTimer(ticker)\n    }\n\n    // run the tick immediately, but in the next pass of the event loop so that\n    // #_initialize can be allowed to complete without recursively waiting on\n    // itself\n    const timeout = setTimeout(async () => {\n      await this.initializePromise\n      await this._autoRefreshTokenTick()\n    }, 0)\n    this.autoRefreshTickTimeout = timeout\n\n    if (timeout && typeof timeout === 'object' && typeof timeout.unref === 'function') {\n      timeout.unref()\n      // @ts-expect-error TS has no context of Deno\n    } else if (typeof Deno !== 'undefined' && typeof Deno.unrefTimer === 'function') {\n      // @ts-expect-error TS has no context of Deno\n      Deno.unrefTimer(timeout)\n    }\n  }\n\n  /**\n   * This is the private implementation of {@link #stopAutoRefresh}. Use this\n   * within the library.\n   */\n  private async _stopAutoRefresh() {\n    this._debug('#_stopAutoRefresh()')\n\n    const ticker = this.autoRefreshTicker\n    this.autoRefreshTicker = null\n\n    if (ticker) {\n      clearInterval(ticker)\n    }\n\n    const timeout = this.autoRefreshTickTimeout\n    this.autoRefreshTickTimeout = null\n\n    if (timeout) {\n      clearTimeout(timeout)\n    }\n  }\n\n  /**\n   * Starts an auto-refresh process in the background. The session is checked\n   * every few seconds. Close to the time of expiration a process is started to\n   * refresh the session. If refreshing fails it will be retried for as long as\n   * necessary.\n   *\n   * If you set the {@link GoTrueClientOptions#autoRefreshToken} you don't need\n   * to call this function, it will be called for you.\n   *\n   * On browsers the refresh process works only when the tab/window is in the\n   * foreground to conserve resources as well as prevent race conditions and\n   * flooding auth with requests. If you call this method any managed\n   * visibility change callback will be removed and you must manage visibility\n   * changes on your own.\n   *\n   * On non-browser platforms the refresh process works *continuously* in the\n   * background, which may not be desirable. You should hook into your\n   * platform's foreground indication mechanism and call these methods\n   * appropriately to conserve resources.\n   *\n   * {@see #stopAutoRefresh}\n   */\n  async startAutoRefresh() {\n    this._removeVisibilityChangedCallback()\n    await this._startAutoRefresh()\n  }\n\n  /**\n   * Stops an active auto refresh process running in the background (if any).\n   *\n   * If you call this method any managed visibility change callback will be\n   * removed and you must manage visibility changes on your own.\n   *\n   * See {@link #startAutoRefresh} for more details.\n   */\n  async stopAutoRefresh() {\n    this._removeVisibilityChangedCallback()\n    await this._stopAutoRefresh()\n  }\n\n  /**\n   * Runs the auto refresh token tick.\n   */\n  private async _autoRefreshTokenTick() {\n    this._debug('#_autoRefreshTokenTick()', 'begin')\n\n    try {\n      await this._acquireLock(0, async () => {\n        try {\n          const now = Date.now()\n\n          try {\n            return await this._useSession(async (result) => {\n              const {\n                data: { session },\n              } = result\n\n              if (!session || !session.refresh_token || !session.expires_at) {\n                this._debug('#_autoRefreshTokenTick()', 'no session')\n                return\n              }\n\n              // session will expire in this many ticks (or has already expired if <= 0)\n              const expiresInTicks = Math.floor(\n                (session.expires_at * 1000 - now) / AUTO_REFRESH_TICK_DURATION_MS\n              )\n\n              this._debug(\n                '#_autoRefreshTokenTick()',\n                `access token expires in ${expiresInTicks} ticks, a tick lasts ${AUTO_REFRESH_TICK_DURATION_MS}ms, refresh threshold is ${AUTO_REFRESH_TICK_THRESHOLD} ticks`\n              )\n\n              if (expiresInTicks <= AUTO_REFRESH_TICK_THRESHOLD) {\n                await this._callRefreshToken(session.refresh_token)\n              }\n            })\n          } catch (e: any) {\n            console.error(\n              'Auto refresh tick failed with error. This is likely a transient error.',\n              e\n            )\n          }\n        } finally {\n          this._debug('#_autoRefreshTokenTick()', 'end')\n        }\n      })\n    } catch (e: any) {\n      if (e.isAcquireTimeout || e instanceof LockAcquireTimeoutError) {\n        this._debug('auto refresh token tick lock not available')\n      } else {\n        throw e\n      }\n    }\n  }\n\n  /**\n   * Registers callbacks on the browser / platform, which in-turn run\n   * algorithms when the browser window/tab are in foreground. On non-browser\n   * platforms it assumes always foreground.\n   */\n  private async _handleVisibilityChange() {\n    this._debug('#_handleVisibilityChange()')\n\n    if (!isBrowser() || !window?.addEventListener) {\n      if (this.autoRefreshToken) {\n        // in non-browser environments the refresh token ticker runs always\n        this.startAutoRefresh()\n      }\n\n      return false\n    }\n\n    try {\n      this.visibilityChangedCallback = async () => {\n        try {\n          await this._onVisibilityChanged(false)\n        } catch (error) {\n          this._debug('#visibilityChangedCallback', 'error', error)\n        }\n      }\n\n      window?.addEventListener('visibilitychange', this.visibilityChangedCallback)\n\n      // now immediately call the visbility changed callback to setup with the\n      // current visbility state\n      await this._onVisibilityChanged(true) // initial call\n    } catch (error) {\n      console.error('_handleVisibilityChange', error)\n    }\n  }\n\n  /**\n   * Callback registered with `window.addEventListener('visibilitychange')`.\n   */\n  private async _onVisibilityChanged(calledFromInitialize: boolean) {\n    const methodName = `#_onVisibilityChanged(${calledFromInitialize})`\n    this._debug(methodName, 'visibilityState', document.visibilityState)\n\n    if (document.visibilityState === 'visible') {\n      if (this.autoRefreshToken) {\n        // in browser environments the refresh token ticker runs only on focused tabs\n        // which prevents race conditions\n        this._startAutoRefresh()\n      }\n\n      if (!calledFromInitialize) {\n        // called when the visibility has changed, i.e. the browser\n        // transitioned from hidden -> visible so we need to see if the session\n        // should be recovered immediately... but to do that we need to acquire\n        // the lock first asynchronously\n        await this.initializePromise\n\n        await this._acquireLock(this.lockAcquireTimeout, async () => {\n          if (document.visibilityState !== 'visible') {\n            this._debug(\n              methodName,\n              'acquired the lock to recover the session, but the browser visibilityState is no longer visible, aborting'\n            )\n\n            // visibility has changed while waiting for the lock, abort\n            return\n          }\n\n          // recover the session\n          await this._recoverAndRefresh()\n        })\n      }\n    } else if (document.visibilityState === 'hidden') {\n      if (this.autoRefreshToken) {\n        this._stopAutoRefresh()\n      }\n    }\n  }\n\n  /**\n   * Generates the relevant login URL for a third-party provider.\n   * @param options.redirectTo A URL or mobile address to send the user to after they are confirmed.\n   * @param options.scopes A space-separated list of scopes granted to the OAuth application.\n   * @param options.queryParams An object of key-value pairs containing query parameters granted to the OAuth application.\n   */\n  private async _getUrlForProvider(\n    url: string,\n    provider: Provider,\n    options: {\n      redirectTo?: string\n      scopes?: string\n      queryParams?: { [key: string]: string }\n      skipBrowserRedirect?: boolean\n    }\n  ) {\n    const urlParams: string[] = [`provider=${encodeURIComponent(provider)}`]\n    if (options?.redirectTo) {\n      urlParams.push(`redirect_to=${encodeURIComponent(options.redirectTo)}`)\n    }\n    if (options?.scopes) {\n      urlParams.push(`scopes=${encodeURIComponent(options.scopes)}`)\n    }\n    if (this.flowType === 'pkce') {\n      const [codeChallenge, codeChallengeMethod] = await getCodeChallengeAndMethod(\n        this.storage,\n        this.storageKey\n      )\n\n      const flowParams = new URLSearchParams({\n        code_challenge: `${encodeURIComponent(codeChallenge)}`,\n        code_challenge_method: `${encodeURIComponent(codeChallengeMethod)}`,\n      })\n      urlParams.push(flowParams.toString())\n    }\n    if (options?.queryParams) {\n      const query = new URLSearchParams(options.queryParams)\n      urlParams.push(query.toString())\n    }\n    if (options?.skipBrowserRedirect) {\n      urlParams.push(`skip_http_redirect=${options.skipBrowserRedirect}`)\n    }\n\n    return `${url}?${urlParams.join('&')}`\n  }\n\n  private async _unenroll(params: MFAUnenrollParams): Promise<AuthMFAUnenrollResponse> {\n    try {\n      return await this._useSession(async (result) => {\n        const { data: sessionData, error: sessionError } = result\n        if (sessionError) {\n          return this._returnResult({ data: null, error: sessionError })\n        }\n\n        return await _request(this.fetch, 'DELETE', `${this.url}/factors/${params.factorId}`, {\n          headers: this.headers,\n          jwt: sessionData?.session?.access_token,\n        })\n      })\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n      throw error\n    }\n  }\n\n  /**\n   * {@see GoTrueMFAApi#enroll}\n   */\n  private async _enroll(params: MFAEnrollTOTPParams): Promise<AuthMFAEnrollTOTPResponse>\n  private async _enroll(params: MFAEnrollPhoneParams): Promise<AuthMFAEnrollPhoneResponse>\n  private async _enroll(params: MFAEnrollWebauthnParams): Promise<AuthMFAEnrollWebauthnResponse>\n  private async _enroll(params: MFAEnrollParams): Promise<AuthMFAEnrollResponse> {\n    try {\n      return await this._useSession(async (result) => {\n        const { data: sessionData, error: sessionError } = result\n        if (sessionError) {\n          return this._returnResult({ data: null, error: sessionError })\n        }\n\n        const body = {\n          friendly_name: params.friendlyName,\n          factor_type: params.factorType,\n          ...(params.factorType === 'phone'\n            ? { phone: params.phone }\n            : params.factorType === 'totp'\n              ? { issuer: params.issuer }\n              : {}),\n        }\n\n        const { data, error } = (await _request(this.fetch, 'POST', `${this.url}/factors`, {\n          body,\n          headers: this.headers,\n          jwt: sessionData?.session?.access_token,\n        })) as AuthMFAEnrollResponse\n        if (error) {\n          return this._returnResult({ data: null, error })\n        }\n\n        if (params.factorType === 'totp' && data.type === 'totp' && data?.totp?.qr_code) {\n          data.totp.qr_code = `data:image/svg+xml;utf-8,${data.totp.qr_code}`\n        }\n\n        return this._returnResult({ data, error: null })\n      })\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n      throw error\n    }\n  }\n\n  /**\n   * {@see GoTrueMFAApi#verify}\n   */\n  private async _verify(params: MFAVerifyTOTPParams): Promise<AuthMFAVerifyResponse>\n  private async _verify(params: MFAVerifyPhoneParams): Promise<AuthMFAVerifyResponse>\n  private async _verify<T extends 'create' | 'request'>(\n    params: MFAVerifyWebauthnParams<T>\n  ): Promise<AuthMFAVerifyResponse>\n  private async _verify(params: MFAVerifyParams): Promise<AuthMFAVerifyResponse> {\n    return this._acquireLock(this.lockAcquireTimeout, async () => {\n      try {\n        return await this._useSession(async (result) => {\n          const { data: sessionData, error: sessionError } = result\n          if (sessionError) {\n            return this._returnResult({ data: null, error: sessionError })\n          }\n\n          const body: StrictOmit<\n            | Exclude<MFAVerifyParams, MFAVerifyWebauthnParams>\n            /** Exclude out the webauthn params from here because we're going to need to serialize them in the response */\n            | Prettify<\n                StrictOmit<MFAVerifyWebauthnParams, 'webauthn'> & {\n                  webauthn: Prettify<\n                    StrictOmit<MFAVerifyWebauthnParamFields['webauthn'], 'credential_response'> & {\n                      credential_response: PublicKeyCredentialJSON\n                    }\n                  >\n                }\n              >,\n            /*  Exclude challengeId because the backend expects snake_case, and exclude factorId since it's passed in the path params */\n            'challengeId' | 'factorId'\n          > & {\n            challenge_id: string\n          } = {\n            challenge_id: params.challengeId,\n            ...('webauthn' in params\n              ? {\n                  webauthn: {\n                    ...params.webauthn,\n                    credential_response:\n                      params.webauthn.type === 'create'\n                        ? serializeCredentialCreationResponse(\n                            params.webauthn.credential_response as RegistrationCredential\n                          )\n                        : serializeCredentialRequestResponse(\n                            params.webauthn.credential_response as AuthenticationCredential\n                          ),\n                  },\n                }\n              : { code: params.code }),\n          }\n\n          const { data, error } = await _request(\n            this.fetch,\n            'POST',\n            `${this.url}/factors/${params.factorId}/verify`,\n            {\n              body,\n              headers: this.headers,\n              jwt: sessionData?.session?.access_token,\n            }\n          )\n          if (error) {\n            return this._returnResult({ data: null, error })\n          }\n\n          await this._saveSession({\n            expires_at: Math.round(Date.now() / 1000) + data.expires_in,\n            ...data,\n          })\n          await this._notifyAllSubscribers('MFA_CHALLENGE_VERIFIED', data)\n\n          return this._returnResult({ data, error })\n        })\n      } catch (error) {\n        if (isAuthError(error)) {\n          return this._returnResult({ data: null, error })\n        }\n        throw error\n      }\n    })\n  }\n\n  /**\n   * {@see GoTrueMFAApi#challenge}\n   */\n  private async _challenge(\n    params: MFAChallengeTOTPParams\n  ): Promise<Prettify<AuthMFAChallengeTOTPResponse>>\n  private async _challenge(\n    params: MFAChallengePhoneParams\n  ): Promise<Prettify<AuthMFAChallengePhoneResponse>>\n  private async _challenge(\n    params: MFAChallengeWebauthnParams\n  ): Promise<Prettify<AuthMFAChallengeWebauthnResponse>>\n  private async _challenge(params: MFAChallengeParams): Promise<AuthMFAChallengeResponse> {\n    return this._acquireLock(this.lockAcquireTimeout, async () => {\n      try {\n        return await this._useSession(async (result) => {\n          const { data: sessionData, error: sessionError } = result\n          if (sessionError) {\n            return this._returnResult({ data: null, error: sessionError })\n          }\n\n          const response = (await _request(\n            this.fetch,\n            'POST',\n            `${this.url}/factors/${params.factorId}/challenge`,\n            {\n              body: params,\n              headers: this.headers,\n              jwt: sessionData?.session?.access_token,\n            }\n          )) as\n            | Exclude<AuthMFAChallengeResponse, AuthMFAChallengeWebauthnResponse>\n            /** The server will send `serialized` data, so we assert the serialized response */\n            | AuthMFAChallengeWebauthnServerResponse\n\n          if (response.error) {\n            return response\n          }\n\n          const { data } = response\n\n          if (data.type !== 'webauthn') {\n            return { data, error: null }\n          }\n\n          switch (data.webauthn.type) {\n            case 'create':\n              return {\n                data: {\n                  ...data,\n                  webauthn: {\n                    ...data.webauthn,\n                    credential_options: {\n                      ...data.webauthn.credential_options,\n                      publicKey: deserializeCredentialCreationOptions(\n                        data.webauthn.credential_options.publicKey\n                      ),\n                    },\n                  },\n                },\n                error: null,\n              }\n            case 'request':\n              return {\n                data: {\n                  ...data,\n                  webauthn: {\n                    ...data.webauthn,\n                    credential_options: {\n                      ...data.webauthn.credential_options,\n                      publicKey: deserializeCredentialRequestOptions(\n                        data.webauthn.credential_options.publicKey\n                      ),\n                    },\n                  },\n                },\n                error: null,\n              }\n          }\n        })\n      } catch (error) {\n        if (isAuthError(error)) {\n          return this._returnResult({ data: null, error })\n        }\n        throw error\n      }\n    })\n  }\n\n  /**\n   * {@see GoTrueMFAApi#challengeAndVerify}\n   */\n  private async _challengeAndVerify(\n    params: MFAChallengeAndVerifyParams\n  ): Promise<AuthMFAVerifyResponse> {\n    // both _challenge and _verify independently acquire the lock, so no need\n    // to acquire it here\n\n    const { data: challengeData, error: challengeError } = await this._challenge({\n      factorId: params.factorId,\n    })\n    if (challengeError) {\n      return this._returnResult({ data: null, error: challengeError })\n    }\n\n    return await this._verify({\n      factorId: params.factorId,\n      challengeId: challengeData.id,\n      code: params.code,\n    })\n  }\n\n  /**\n   * {@see GoTrueMFAApi#listFactors}\n   */\n  private async _listFactors(): Promise<AuthMFAListFactorsResponse> {\n    // use #getUser instead of #_getUser as the former acquires a lock\n    const {\n      data: { user },\n      error: userError,\n    } = await this.getUser()\n    if (userError) {\n      return { data: null, error: userError }\n    }\n\n    const data: AuthMFAListFactorsResponse['data'] = {\n      all: [],\n      phone: [],\n      totp: [],\n      webauthn: [],\n    }\n\n    // loop over the factors ONCE\n    for (const factor of user?.factors ?? []) {\n      data.all.push(factor)\n      if (factor.status === 'verified') {\n        ;(data[factor.factor_type] as (typeof factor)[]).push(factor)\n      }\n    }\n\n    return {\n      data,\n      error: null,\n    }\n  }\n\n  /**\n   * {@see GoTrueMFAApi#getAuthenticatorAssuranceLevel}\n   */\n  private async _getAuthenticatorAssuranceLevel(\n    jwt?: string\n  ): Promise<AuthMFAGetAuthenticatorAssuranceLevelResponse> {\n    if (jwt) {\n      try {\n        const { payload } = decodeJWT(jwt)\n\n        let currentLevel: AuthenticatorAssuranceLevels | null = null\n        if (payload.aal) {\n          currentLevel = payload.aal\n        }\n\n        let nextLevel: AuthenticatorAssuranceLevels | null = currentLevel\n\n        const {\n          data: { user },\n          error: userError,\n        } = await this.getUser(jwt)\n\n        if (userError) {\n          return this._returnResult({ data: null, error: userError })\n        }\n\n        const verifiedFactors =\n          user?.factors?.filter((factor: Factor) => factor.status === 'verified') ?? []\n\n        if (verifiedFactors.length > 0) {\n          nextLevel = 'aal2'\n        }\n\n        const currentAuthenticationMethods = payload.amr || []\n\n        return { data: { currentLevel, nextLevel, currentAuthenticationMethods }, error: null }\n      } catch (error) {\n        if (isAuthError(error)) {\n          return this._returnResult({ data: null, error })\n        }\n        throw error\n      }\n    }\n\n    const {\n      data: { session },\n      error: sessionError,\n    } = await this.getSession()\n\n    if (sessionError) {\n      return this._returnResult({ data: null, error: sessionError })\n    }\n    if (!session) {\n      return {\n        data: { currentLevel: null, nextLevel: null, currentAuthenticationMethods: [] },\n        error: null,\n      }\n    }\n\n    const { payload } = decodeJWT(session.access_token)\n\n    let currentLevel: AuthenticatorAssuranceLevels | null = null\n\n    if (payload.aal) {\n      currentLevel = payload.aal\n    }\n\n    let nextLevel: AuthenticatorAssuranceLevels | null = currentLevel\n\n    const verifiedFactors =\n      session.user.factors?.filter((factor: Factor) => factor.status === 'verified') ?? []\n\n    if (verifiedFactors.length > 0) {\n      nextLevel = 'aal2'\n    }\n\n    const currentAuthenticationMethods = payload.amr || []\n\n    return { data: { currentLevel, nextLevel, currentAuthenticationMethods }, error: null }\n  }\n\n  /**\n   * Retrieves details about an OAuth authorization request.\n   * Only relevant when the OAuth 2.1 server is enabled in Supabase Auth.\n   *\n   * Returns authorization details including client info, scopes, and user information.\n   * If the response includes only a redirect_url field, it means consent was already given - the caller\n   * should handle the redirect manually if needed.\n   */\n  private async _getAuthorizationDetails(\n    authorizationId: string\n  ): Promise<AuthOAuthAuthorizationDetailsResponse> {\n    try {\n      return await this._useSession(async (result) => {\n        const {\n          data: { session },\n          error: sessionError,\n        } = result\n\n        if (sessionError) {\n          return this._returnResult({ data: null, error: sessionError })\n        }\n\n        if (!session) {\n          return this._returnResult({ data: null, error: new AuthSessionMissingError() })\n        }\n\n        return await _request(\n          this.fetch,\n          'GET',\n          `${this.url}/oauth/authorizations/${authorizationId}`,\n          {\n            headers: this.headers,\n            jwt: session.access_token,\n            xform: (data: any) => ({ data, error: null }),\n          }\n        )\n      })\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n\n      throw error\n    }\n  }\n\n  /**\n   * Approves an OAuth authorization request.\n   * Only relevant when the OAuth 2.1 server is enabled in Supabase Auth.\n   */\n  private async _approveAuthorization(\n    authorizationId: string,\n    options?: { skipBrowserRedirect?: boolean }\n  ): Promise<AuthOAuthConsentResponse> {\n    try {\n      return await this._useSession(async (result) => {\n        const {\n          data: { session },\n          error: sessionError,\n        } = result\n\n        if (sessionError) {\n          return this._returnResult({ data: null, error: sessionError })\n        }\n\n        if (!session) {\n          return this._returnResult({ data: null, error: new AuthSessionMissingError() })\n        }\n\n        const response = await _request(\n          this.fetch,\n          'POST',\n          `${this.url}/oauth/authorizations/${authorizationId}/consent`,\n          {\n            headers: this.headers,\n            jwt: session.access_token,\n            body: { action: 'approve' },\n            xform: (data: any) => ({ data, error: null }),\n          }\n        )\n\n        if (response.data && response.data.redirect_url) {\n          // Automatically redirect in browser unless skipBrowserRedirect is true\n          if (isBrowser() && !options?.skipBrowserRedirect) {\n            window.location.assign(response.data.redirect_url)\n          }\n        }\n\n        return response\n      })\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n\n      throw error\n    }\n  }\n\n  /**\n   * Denies an OAuth authorization request.\n   * Only relevant when the OAuth 2.1 server is enabled in Supabase Auth.\n   */\n  private async _denyAuthorization(\n    authorizationId: string,\n    options?: { skipBrowserRedirect?: boolean }\n  ): Promise<AuthOAuthConsentResponse> {\n    try {\n      return await this._useSession(async (result) => {\n        const {\n          data: { session },\n          error: sessionError,\n        } = result\n\n        if (sessionError) {\n          return this._returnResult({ data: null, error: sessionError })\n        }\n\n        if (!session) {\n          return this._returnResult({ data: null, error: new AuthSessionMissingError() })\n        }\n\n        const response = await _request(\n          this.fetch,\n          'POST',\n          `${this.url}/oauth/authorizations/${authorizationId}/consent`,\n          {\n            headers: this.headers,\n            jwt: session.access_token,\n            body: { action: 'deny' },\n            xform: (data: any) => ({ data, error: null }),\n          }\n        )\n\n        if (response.data && response.data.redirect_url) {\n          // Automatically redirect in browser unless skipBrowserRedirect is true\n          if (isBrowser() && !options?.skipBrowserRedirect) {\n            window.location.assign(response.data.redirect_url)\n          }\n        }\n\n        return response\n      })\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n\n      throw error\n    }\n  }\n\n  /**\n   * Lists all OAuth grants that the authenticated user has authorized.\n   * Only relevant when the OAuth 2.1 server is enabled in Supabase Auth.\n   */\n  private async _listOAuthGrants(): Promise<AuthOAuthGrantsResponse> {\n    try {\n      return await this._useSession(async (result) => {\n        const {\n          data: { session },\n          error: sessionError,\n        } = result\n\n        if (sessionError) {\n          return this._returnResult({ data: null, error: sessionError })\n        }\n\n        if (!session) {\n          return this._returnResult({ data: null, error: new AuthSessionMissingError() })\n        }\n\n        return await _request(this.fetch, 'GET', `${this.url}/user/oauth/grants`, {\n          headers: this.headers,\n          jwt: session.access_token,\n          xform: (data: any) => ({ data, error: null }),\n        })\n      })\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n\n      throw error\n    }\n  }\n\n  /**\n   * Revokes a user's OAuth grant for a specific client.\n   * Only relevant when the OAuth 2.1 server is enabled in Supabase Auth.\n   */\n  private async _revokeOAuthGrant(options: {\n    clientId: string\n  }): Promise<AuthOAuthRevokeGrantResponse> {\n    try {\n      return await this._useSession(async (result) => {\n        const {\n          data: { session },\n          error: sessionError,\n        } = result\n\n        if (sessionError) {\n          return this._returnResult({ data: null, error: sessionError })\n        }\n\n        if (!session) {\n          return this._returnResult({ data: null, error: new AuthSessionMissingError() })\n        }\n\n        await _request(this.fetch, 'DELETE', `${this.url}/user/oauth/grants`, {\n          headers: this.headers,\n          jwt: session.access_token,\n          query: { client_id: options.clientId },\n          noResolveJson: true,\n        })\n        return { data: {}, error: null }\n      })\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n\n      throw error\n    }\n  }\n\n  private async fetchJwk(kid: string, jwks: { keys: JWK[] } = { keys: [] }): Promise<JWK | null> {\n    // try fetching from the supplied jwks\n    let jwk = jwks.keys.find((key) => key.kid === kid)\n    if (jwk) {\n      return jwk\n    }\n\n    const now = Date.now()\n\n    // try fetching from cache\n    jwk = this.jwks.keys.find((key) => key.kid === kid)\n\n    // jwk exists and jwks isn't stale\n    if (jwk && this.jwks_cached_at + JWKS_TTL > now) {\n      return jwk\n    }\n    // jwk isn't cached in memory so we need to fetch it from the well-known endpoint\n    const { data, error } = await _request(this.fetch, 'GET', `${this.url}/.well-known/jwks.json`, {\n      headers: this.headers,\n    })\n    if (error) {\n      throw error\n    }\n    if (!data.keys || data.keys.length === 0) {\n      return null\n    }\n\n    this.jwks = data\n    this.jwks_cached_at = now\n\n    // Find the signing key\n    jwk = data.keys.find((key: any) => key.kid === kid)\n    if (!jwk) {\n      return null\n    }\n    return jwk\n  }\n\n  /**\n   * Extracts the JWT claims present in the access token by first verifying the\n   * JWT against the server's JSON Web Key Set endpoint\n   * `/.well-known/jwks.json` which is often cached, resulting in significantly\n   * faster responses. Prefer this method over {@link #getUser} which always\n   * sends a request to the Auth server for each JWT.\n   *\n   * If the project is not using an asymmetric JWT signing key (like ECC or\n   * RSA) it always sends a request to the Auth server (similar to {@link\n   * #getUser}) to verify the JWT.\n   *\n   * @param jwt An optional specific JWT you wish to verify, not the one you\n   *            can obtain from {@link #getSession}.\n   * @param options Various additional options that allow you to customize the\n   *                behavior of this method.\n   */\n  async getClaims(\n    jwt?: string,\n    options: {\n      /**\n       * @deprecated Please use options.jwks instead.\n       */\n      keys?: JWK[]\n\n      /** If set to `true` the `exp` claim will not be validated against the current time. */\n      allowExpired?: boolean\n\n      /** If set, this JSON Web Key Set is going to have precedence over the cached value available on the server. */\n      jwks?: { keys: JWK[] }\n    } = {}\n  ): Promise<\n    | {\n        data: { claims: JwtPayload; header: JwtHeader; signature: Uint8Array }\n        error: null\n      }\n    | { data: null; error: AuthError }\n    | { data: null; error: null }\n  > {\n    try {\n      let token = jwt\n      if (!token) {\n        const { data, error } = await this.getSession()\n        if (error || !data.session) {\n          return this._returnResult({ data: null, error })\n        }\n        token = data.session.access_token\n      }\n\n      const {\n        header,\n        payload,\n        signature,\n        raw: { header: rawHeader, payload: rawPayload },\n      } = decodeJWT(token)\n\n      if (!options?.allowExpired) {\n        // Reject expired JWTs should only happen if jwt argument was passed\n        validateExp(payload.exp)\n      }\n\n      const signingKey =\n        !header.alg ||\n        header.alg.startsWith('HS') ||\n        !header.kid ||\n        !('crypto' in globalThis && 'subtle' in globalThis.crypto)\n          ? null\n          : await this.fetchJwk(header.kid, options?.keys ? { keys: options.keys } : options?.jwks)\n\n      // If symmetric algorithm or WebCrypto API is unavailable, fallback to getUser()\n      if (!signingKey) {\n        const { error } = await this.getUser(token)\n        if (error) {\n          throw error\n        }\n        // getUser succeeds so the claims in the JWT can be trusted\n        return {\n          data: {\n            claims: payload,\n            header,\n            signature,\n          },\n          error: null,\n        }\n      }\n\n      const algorithm = getAlgorithm(header.alg)\n\n      // Convert JWK to CryptoKey\n      const publicKey = await crypto.subtle.importKey('jwk', signingKey, algorithm, true, [\n        'verify',\n      ])\n\n      // Verify the signature\n      const isValid = await crypto.subtle.verify(\n        algorithm,\n        publicKey,\n        signature,\n        stringToUint8Array(`${rawHeader}.${rawPayload}`)\n      )\n\n      if (!isValid) {\n        throw new AuthInvalidJwtError('Invalid JWT signature')\n      }\n\n      // If verification succeeds, decode and return claims\n      return {\n        data: {\n          claims: payload,\n          header,\n          signature,\n        },\n        error: null,\n      }\n    } catch (error) {\n      if (isAuthError(error)) {\n        return this._returnResult({ data: null, error })\n      }\n      throw error\n    }\n  }\n}\n","import GoTrueAdminApi from './GoTrueAdminApi'\n\nconst AuthAdminApi = GoTrueAdminApi\n\nexport default AuthAdminApi\n","import GoTrueClient from './GoTrueClient'\n\nconst AuthClient = GoTrueClient\n\nexport default AuthClient\n","// constants.ts\nimport { RealtimeClientOptions } from '@supabase/realtime-js'\nimport { SupabaseAuthClientOptions } from './types'\nimport { version } from './version'\n\nlet JS_ENV = ''\n// @ts-ignore\nif (typeof Deno !== 'undefined') {\n  JS_ENV = 'deno'\n} else if (typeof document !== 'undefined') {\n  JS_ENV = 'web'\n} else if (typeof navigator !== 'undefined' && navigator.product === 'ReactNative') {\n  JS_ENV = 'react-native'\n} else {\n  JS_ENV = 'node'\n}\n\nexport const DEFAULT_HEADERS = { 'X-Client-Info': `supabase-js-${JS_ENV}/${version}` }\n\nexport const DEFAULT_GLOBAL_OPTIONS = {\n  headers: DEFAULT_HEADERS,\n}\n\nexport const DEFAULT_DB_OPTIONS = {\n  schema: 'public',\n}\n\nexport const DEFAULT_AUTH_OPTIONS: SupabaseAuthClientOptions = {\n  autoRefreshToken: true,\n  persistSession: true,\n  detectSessionInUrl: true,\n  flowType: 'implicit',\n}\n\nexport const DEFAULT_REALTIME_OPTIONS: RealtimeClientOptions = {}\n","type Fetch = typeof fetch\n\nexport const resolveFetch = (customFetch?: Fetch): Fetch => {\n  if (customFetch) {\n    return (...args: Parameters<Fetch>) => customFetch(...args)\n  }\n  return (...args: Parameters<Fetch>) => fetch(...args)\n}\n\nexport const resolveHeadersConstructor = () => {\n  return Headers\n}\n\nexport const fetchWithAuth = (\n  supabaseKey: string,\n  getAccessToken: () => Promise<string | null>,\n  customFetch?: Fetch\n): Fetch => {\n  const fetch = resolveFetch(customFetch)\n  const HeadersConstructor = resolveHeadersConstructor()\n\n  return async (input, init) => {\n    const accessToken = (await getAccessToken()) ?? supabaseKey\n    let headers = new HeadersConstructor(init?.headers)\n\n    if (!headers.has('apikey')) {\n      headers.set('apikey', supabaseKey)\n    }\n\n    if (!headers.has('Authorization')) {\n      headers.set('Authorization', `Bearer ${accessToken}`)\n    }\n\n    return fetch(input, { ...init, headers })\n  }\n}\n","import { AuthClient } from '@supabase/auth-js'\nimport { SupabaseAuthClientOptions } from './types'\n\nexport class SupabaseAuthClient extends AuthClient {\n  constructor(options: SupabaseAuthClientOptions) {\n    super(options)\n  }\n}\n","import type { AuthChangeEvent } from '@supabase/auth-js'\nimport { FunctionsClient } from '@supabase/functions-js'\nimport {\n  PostgrestClient,\n  type PostgrestFilterBuilder,\n  type PostgrestQueryBuilder,\n} from '@supabase/postgrest-js'\nimport {\n  type RealtimeChannel,\n  type RealtimeChannelOptions,\n  RealtimeClient,\n  type RealtimeClientOptions,\n} from '@supabase/realtime-js'\nimport { StorageClient as SupabaseStorageClient } from '@supabase/storage-js'\nimport {\n  DEFAULT_AUTH_OPTIONS,\n  DEFAULT_DB_OPTIONS,\n  DEFAULT_GLOBAL_OPTIONS,\n  DEFAULT_REALTIME_OPTIONS,\n} from './lib/constants'\nimport { fetchWithAuth } from './lib/fetch'\nimport { applySettingDefaults, validateSupabaseUrl } from './lib/helpers'\nimport { SupabaseAuthClient } from './lib/SupabaseAuthClient'\nimport type {\n  Fetch,\n  GenericSchema,\n  SupabaseAuthClientOptions,\n  SupabaseClientOptions,\n} from './lib/types'\nimport { GetRpcFunctionFilterBuilderByArgs } from './lib/rest/types/common/rpc'\n\n/**\n * Supabase Client.\n *\n * An isomorphic Javascript client for interacting with Postgres.\n */\nexport default class SupabaseClient<\n  Database = any,\n  // The second type parameter is also used for specifying db_schema, so we\n  // support both cases.\n  // TODO: Allow setting db_schema from ClientOptions.\n  SchemaNameOrClientOptions extends\n    | (string & keyof Omit<Database, '__InternalSupabase'>)\n    | { PostgrestVersion: string } = 'public' extends keyof Omit<Database, '__InternalSupabase'>\n    ? 'public'\n    : string & keyof Omit<Database, '__InternalSupabase'>,\n  SchemaName extends string &\n    keyof Omit<Database, '__InternalSupabase'> = SchemaNameOrClientOptions extends string &\n    keyof Omit<Database, '__InternalSupabase'>\n    ? SchemaNameOrClientOptions\n    : 'public' extends keyof Omit<Database, '__InternalSupabase'>\n      ? 'public'\n      : string & keyof Omit<Omit<Database, '__InternalSupabase'>, '__InternalSupabase'>,\n  Schema extends Omit<Database, '__InternalSupabase'>[SchemaName] extends GenericSchema\n    ? Omit<Database, '__InternalSupabase'>[SchemaName]\n    : never = Omit<Database, '__InternalSupabase'>[SchemaName] extends GenericSchema\n    ? Omit<Database, '__InternalSupabase'>[SchemaName]\n    : never,\n  ClientOptions extends { PostgrestVersion: string } = SchemaNameOrClientOptions extends string &\n    keyof Omit<Database, '__InternalSupabase'>\n    ? // If the version isn't explicitly set, look for it in the __InternalSupabase object to infer the right version\n      Database extends { __InternalSupabase: { PostgrestVersion: string } }\n      ? Database['__InternalSupabase']\n      : // otherwise default to 12\n        { PostgrestVersion: '12' }\n    : SchemaNameOrClientOptions extends { PostgrestVersion: string }\n      ? SchemaNameOrClientOptions\n      : never,\n> {\n  /**\n   * Supabase Auth allows you to create and manage user sessions for access to data that is secured by access policies.\n   */\n  auth: SupabaseAuthClient\n  realtime: RealtimeClient\n  /**\n   * Supabase Storage allows you to manage user-generated content, such as photos or videos.\n   */\n  storage: SupabaseStorageClient\n\n  protected realtimeUrl: URL\n  protected authUrl: URL\n  protected storageUrl: URL\n  protected functionsUrl: URL\n  protected rest: PostgrestClient<Database, ClientOptions, SchemaName>\n  protected storageKey: string\n  protected fetch?: Fetch\n  protected changedAccessToken?: string\n  protected accessToken?: () => Promise<string | null>\n\n  protected headers: Record<string, string>\n\n  /**\n   * Create a new client for use in the browser.\n   *\n   * @category Initializing\n   *\n   * @param supabaseUrl The unique Supabase URL which is supplied when you create a new project in your project dashboard.\n   * @param supabaseKey The unique Supabase Key which is supplied when you create a new project in your project dashboard.\n   * @param options.db.schema You can switch in between schemas. The schema needs to be on the list of exposed schemas inside Supabase.\n   * @param options.auth.autoRefreshToken Set to \"true\" if you want to automatically refresh the token before expiring.\n   * @param options.auth.persistSession Set to \"true\" if you want to automatically save the user session into local storage.\n   * @param options.auth.detectSessionInUrl Set to \"true\" if you want to automatically detects OAuth grants in the URL and signs in the user.\n   * @param options.realtime Options passed along to realtime-js constructor.\n   * @param options.storage Options passed along to the storage-js constructor.\n   * @param options.global.fetch A custom fetch implementation.\n   * @param options.global.headers Any additional headers to send with each network request.\n   *\n   * @example Creating a client\n   * ```js\n   * import { createClient } from '@supabase/supabase-js'\n   *\n   * // Create a single supabase client for interacting with your database\n   * const supabase = createClient('https://xyzcompany.supabase.co', 'publishable-or-anon-key')\n   * ```\n   *\n   * @example With a custom domain\n   * ```js\n   * import { createClient } from '@supabase/supabase-js'\n   *\n   * // Use a custom domain as the supabase URL\n   * const supabase = createClient('https://my-custom-domain.com', 'publishable-or-anon-key')\n   * ```\n   *\n   * @example With additional parameters\n   * ```js\n   * import { createClient } from '@supabase/supabase-js'\n   *\n   * const options = {\n   *   db: {\n   *     schema: 'public',\n   *   },\n   *   auth: {\n   *     autoRefreshToken: true,\n   *     persistSession: true,\n   *     detectSessionInUrl: true\n   *   },\n   *   global: {\n   *     headers: { 'x-my-custom-header': 'my-app-name' },\n   *   },\n   * }\n   * const supabase = createClient(\"https://xyzcompany.supabase.co\", \"publishable-or-anon-key\", options)\n   * ```\n   *\n   * @exampleDescription With custom schemas\n   * By default the API server points to the `public` schema. You can enable other database schemas within the Dashboard.\n   * Go to [Settings > API > Exposed schemas](/dashboard/project/_/settings/api) and add the schema which you want to expose to the API.\n   *\n   * Note: each client connection can only access a single schema, so the code above can access the `other_schema` schema but cannot access the `public` schema.\n   *\n   * @example With custom schemas\n   * ```js\n   * import { createClient } from '@supabase/supabase-js'\n   *\n   * const supabase = createClient('https://xyzcompany.supabase.co', 'publishable-or-anon-key', {\n   *   // Provide a custom schema. Defaults to \"public\".\n   *   db: { schema: 'other_schema' }\n   * })\n   * ```\n   *\n   * @exampleDescription Custom fetch implementation\n   * `supabase-js` uses the [`cross-fetch`](https://www.npmjs.com/package/cross-fetch) library to make HTTP requests,\n   * but an alternative `fetch` implementation can be provided as an option.\n   * This is most useful in environments where `cross-fetch` is not compatible (for instance Cloudflare Workers).\n   *\n   * @example Custom fetch implementation\n   * ```js\n   * import { createClient } from '@supabase/supabase-js'\n   *\n   * const supabase = createClient('https://xyzcompany.supabase.co', 'publishable-or-anon-key', {\n   *   global: { fetch: fetch.bind(globalThis) }\n   * })\n   * ```\n   *\n   * @exampleDescription React Native options with AsyncStorage\n   * For React Native we recommend using `AsyncStorage` as the storage implementation for Supabase Auth.\n   *\n   * @example React Native options with AsyncStorage\n   * ```js\n   * import 'react-native-url-polyfill/auto'\n   * import { createClient } from '@supabase/supabase-js'\n   * import AsyncStorage from \"@react-native-async-storage/async-storage\";\n   *\n   * const supabase = createClient(\"https://xyzcompany.supabase.co\", \"publishable-or-anon-key\", {\n   *   auth: {\n   *     storage: AsyncStorage,\n   *     autoRefreshToken: true,\n   *     persistSession: true,\n   *     detectSessionInUrl: false,\n   *   },\n   * });\n   * ```\n   *\n   * @exampleDescription React Native options with Expo SecureStore\n   * If you wish to encrypt the user's session information, you can use `aes-js` and store the encryption key in Expo SecureStore.\n   * The `aes-js` library, a reputable JavaScript-only implementation of the AES encryption algorithm in CTR mode.\n   * A new 256-bit encryption key is generated using the `react-native-get-random-values` library.\n   * This key is stored inside Expo's SecureStore, while the value is encrypted and placed inside AsyncStorage.\n   *\n   * Please make sure that:\n   * - You keep the `expo-secure-store`, `aes-js` and `react-native-get-random-values` libraries up-to-date.\n   * - Choose the correct [`SecureStoreOptions`](https://docs.expo.dev/versions/latest/sdk/securestore/#securestoreoptions) for your app's needs.\n   *   E.g. [`SecureStore.WHEN_UNLOCKED`](https://docs.expo.dev/versions/latest/sdk/securestore/#securestorewhen_unlocked) regulates when the data can be accessed.\n   * - Carefully consider optimizations or other modifications to the above example, as those can lead to introducing subtle security vulnerabilities.\n   *\n   * @example React Native options with Expo SecureStore\n   * ```ts\n   * import 'react-native-url-polyfill/auto'\n   * import { createClient } from '@supabase/supabase-js'\n   * import AsyncStorage from '@react-native-async-storage/async-storage';\n   * import * as SecureStore from 'expo-secure-store';\n   * import * as aesjs from 'aes-js';\n   * import 'react-native-get-random-values';\n   *\n   * // As Expo's SecureStore does not support values larger than 2048\n   * // bytes, an AES-256 key is generated and stored in SecureStore, while\n   * // it is used to encrypt/decrypt values stored in AsyncStorage.\n   * class LargeSecureStore {\n   *   private async _encrypt(key: string, value: string) {\n   *     const encryptionKey = crypto.getRandomValues(new Uint8Array(256 / 8));\n   *\n   *     const cipher = new aesjs.ModeOfOperation.ctr(encryptionKey, new aesjs.Counter(1));\n   *     const encryptedBytes = cipher.encrypt(aesjs.utils.utf8.toBytes(value));\n   *\n   *     await SecureStore.setItemAsync(key, aesjs.utils.hex.fromBytes(encryptionKey));\n   *\n   *     return aesjs.utils.hex.fromBytes(encryptedBytes);\n   *   }\n   *\n   *   private async _decrypt(key: string, value: string) {\n   *     const encryptionKeyHex = await SecureStore.getItemAsync(key);\n   *     if (!encryptionKeyHex) {\n   *       return encryptionKeyHex;\n   *     }\n   *\n   *     const cipher = new aesjs.ModeOfOperation.ctr(aesjs.utils.hex.toBytes(encryptionKeyHex), new aesjs.Counter(1));\n   *     const decryptedBytes = cipher.decrypt(aesjs.utils.hex.toBytes(value));\n   *\n   *     return aesjs.utils.utf8.fromBytes(decryptedBytes);\n   *   }\n   *\n   *   async getItem(key: string) {\n   *     const encrypted = await AsyncStorage.getItem(key);\n   *     if (!encrypted) { return encrypted; }\n   *\n   *     return await this._decrypt(key, encrypted);\n   *   }\n   *\n   *   async removeItem(key: string) {\n   *     await AsyncStorage.removeItem(key);\n   *     await SecureStore.deleteItemAsync(key);\n   *   }\n   *\n   *   async setItem(key: string, value: string) {\n   *     const encrypted = await this._encrypt(key, value);\n   *\n   *     await AsyncStorage.setItem(key, encrypted);\n   *   }\n   * }\n   *\n   * const supabase = createClient(\"https://xyzcompany.supabase.co\", \"publishable-or-anon-key\", {\n   *   auth: {\n   *     storage: new LargeSecureStore(),\n   *     autoRefreshToken: true,\n   *     persistSession: true,\n   *     detectSessionInUrl: false,\n   *   },\n   * });\n   * ```\n   *\n   * @example With a database query\n   * ```ts\n   * import { createClient } from '@supabase/supabase-js'\n   *\n   * const supabase = createClient('https://xyzcompany.supabase.co', 'public-anon-key')\n   *\n   * const { data } = await supabase.from('profiles').select('*')\n   * ```\n   */\n  constructor(\n    protected supabaseUrl: string,\n    protected supabaseKey: string,\n    options?: SupabaseClientOptions<SchemaName>\n  ) {\n    const baseUrl = validateSupabaseUrl(supabaseUrl)\n    if (!supabaseKey) throw new Error('supabaseKey is required.')\n\n    this.realtimeUrl = new URL('realtime/v1', baseUrl)\n    this.realtimeUrl.protocol = this.realtimeUrl.protocol.replace('http', 'ws')\n    this.authUrl = new URL('auth/v1', baseUrl)\n    this.storageUrl = new URL('storage/v1', baseUrl)\n    this.functionsUrl = new URL('functions/v1', baseUrl)\n\n    // default storage key uses the supabase project ref as a namespace\n    const defaultStorageKey = `sb-${baseUrl.hostname.split('.')[0]}-auth-token`\n    const DEFAULTS = {\n      db: DEFAULT_DB_OPTIONS,\n      realtime: DEFAULT_REALTIME_OPTIONS,\n      auth: { ...DEFAULT_AUTH_OPTIONS, storageKey: defaultStorageKey },\n      global: DEFAULT_GLOBAL_OPTIONS,\n    }\n\n    const settings = applySettingDefaults(options ?? {}, DEFAULTS)\n\n    this.storageKey = settings.auth.storageKey ?? ''\n    this.headers = settings.global.headers ?? {}\n\n    if (!settings.accessToken) {\n      this.auth = this._initSupabaseAuthClient(\n        settings.auth ?? {},\n        this.headers,\n        settings.global.fetch\n      )\n    } else {\n      this.accessToken = settings.accessToken\n\n      this.auth = new Proxy<SupabaseAuthClient>({} as any, {\n        get: (_, prop) => {\n          throw new Error(\n            `@supabase/supabase-js: Supabase Client is configured with the accessToken option, accessing supabase.auth.${String(\n              prop\n            )} is not possible`\n          )\n        },\n      })\n    }\n\n    this.fetch = fetchWithAuth(supabaseKey, this._getAccessToken.bind(this), settings.global.fetch)\n    this.realtime = this._initRealtimeClient({\n      headers: this.headers,\n      accessToken: this._getAccessToken.bind(this),\n      ...settings.realtime,\n    })\n    if (this.accessToken) {\n      // Start auth immediately to avoid race condition with channel subscriptions\n      // Wrap Promise to avoid Firefox extension cross-context Promise access errors\n      Promise.resolve(this.accessToken())\n        .then((token) => this.realtime.setAuth(token))\n        .catch((e) => console.warn('Failed to set initial Realtime auth token:', e))\n    }\n\n    this.rest = new PostgrestClient(new URL('rest/v1', baseUrl).href, {\n      headers: this.headers,\n      schema: settings.db.schema,\n      fetch: this.fetch,\n      timeout: settings.db.timeout,\n      urlLengthLimit: settings.db.urlLengthLimit,\n    })\n\n    this.storage = new SupabaseStorageClient(\n      this.storageUrl.href,\n      this.headers,\n      this.fetch,\n      options?.storage\n    )\n\n    if (!settings.accessToken) {\n      this._listenForAuthEvents()\n    }\n  }\n\n  /**\n   * Supabase Functions allows you to deploy and invoke edge functions.\n   */\n  get functions(): FunctionsClient {\n    return new FunctionsClient(this.functionsUrl.href, {\n      headers: this.headers,\n      customFetch: this.fetch,\n    })\n  }\n\n  // NOTE: signatures must be kept in sync with PostgrestClient.from\n  from<\n    TableName extends string & keyof Schema['Tables'],\n    Table extends Schema['Tables'][TableName],\n  >(relation: TableName): PostgrestQueryBuilder<ClientOptions, Schema, Table, TableName>\n  from<ViewName extends string & keyof Schema['Views'], View extends Schema['Views'][ViewName]>(\n    relation: ViewName\n  ): PostgrestQueryBuilder<ClientOptions, Schema, View, ViewName>\n  /**\n   * Perform a query on a table or a view.\n   *\n   * @param relation - The table or view name to query\n   */\n  from(relation: string): PostgrestQueryBuilder<ClientOptions, Schema, any> {\n    return this.rest.from(relation)\n  }\n\n  // NOTE: signatures must be kept in sync with PostgrestClient.schema\n  /**\n   * Select a schema to query or perform an function (rpc) call.\n   *\n   * The schema needs to be on the list of exposed schemas inside Supabase.\n   *\n   * @param schema - The schema to query\n   */\n  schema<DynamicSchema extends string & keyof Omit<Database, '__InternalSupabase'>>(\n    schema: DynamicSchema\n  ): PostgrestClient<\n    Database,\n    ClientOptions,\n    DynamicSchema,\n    Database[DynamicSchema] extends GenericSchema ? Database[DynamicSchema] : any\n  > {\n    return this.rest.schema<DynamicSchema>(schema)\n  }\n\n  // NOTE: signatures must be kept in sync with PostgrestClient.rpc\n  /**\n   * Perform a function call.\n   *\n   * @param fn - The function name to call\n   * @param args - The arguments to pass to the function call\n   * @param options - Named parameters\n   * @param options.head - When set to `true`, `data` will not be returned.\n   * Useful if you only need the count.\n   * @param options.get - When set to `true`, the function will be called with\n   * read-only access mode.\n   * @param options.count - Count algorithm to use to count rows returned by the\n   * function. Only applicable for [set-returning\n   * functions](https://www.postgresql.org/docs/current/functions-srf.html).\n   *\n   * `\"exact\"`: Exact but slow count algorithm. Performs a `COUNT(*)` under the\n   * hood.\n   *\n   * `\"planned\"`: Approximated but fast count algorithm. Uses the Postgres\n   * statistics under the hood.\n   *\n   * `\"estimated\"`: Uses exact count for low numbers and planned count for high\n   * numbers.\n   */\n  rpc<\n    FnName extends string & keyof Schema['Functions'],\n    Args extends Schema['Functions'][FnName]['Args'] = never,\n    FilterBuilder extends GetRpcFunctionFilterBuilderByArgs<\n      Schema,\n      FnName,\n      Args\n    > = GetRpcFunctionFilterBuilderByArgs<Schema, FnName, Args>,\n  >(\n    fn: FnName,\n    args: Args = {} as Args,\n    options: {\n      head?: boolean\n      get?: boolean\n      count?: 'exact' | 'planned' | 'estimated'\n    } = {\n      head: false,\n      get: false,\n      count: undefined,\n    }\n  ): PostgrestFilterBuilder<\n    ClientOptions,\n    Schema,\n    FilterBuilder['Row'],\n    FilterBuilder['Result'],\n    FilterBuilder['RelationName'],\n    FilterBuilder['Relationships'],\n    'RPC'\n  > {\n    return this.rest.rpc(fn, args, options) as unknown as PostgrestFilterBuilder<\n      ClientOptions,\n      Schema,\n      FilterBuilder['Row'],\n      FilterBuilder['Result'],\n      FilterBuilder['RelationName'],\n      FilterBuilder['Relationships'],\n      'RPC'\n    >\n  }\n\n  /**\n   * Creates a Realtime channel with Broadcast, Presence, and Postgres Changes.\n   *\n   * @param {string} name - The name of the Realtime channel.\n   * @param {Object} opts - The options to pass to the Realtime channel.\n   *\n   */\n  channel(name: string, opts: RealtimeChannelOptions = { config: {} }): RealtimeChannel {\n    return this.realtime.channel(name, opts)\n  }\n\n  /**\n   * Returns all Realtime channels.\n   */\n  getChannels(): RealtimeChannel[] {\n    return this.realtime.getChannels()\n  }\n\n  /**\n   * Unsubscribes and removes Realtime channel from Realtime client.\n   *\n   * @param {RealtimeChannel} channel - The name of the Realtime channel.\n   *\n   */\n  removeChannel(channel: RealtimeChannel): Promise<'ok' | 'timed out' | 'error'> {\n    return this.realtime.removeChannel(channel)\n  }\n\n  /**\n   * Unsubscribes and removes all Realtime channels from Realtime client.\n   */\n  removeAllChannels(): Promise<('ok' | 'timed out' | 'error')[]> {\n    return this.realtime.removeAllChannels()\n  }\n\n  private async _getAccessToken() {\n    if (this.accessToken) {\n      return await this.accessToken()\n    }\n\n    const { data } = await this.auth.getSession()\n\n    return data.session?.access_token ?? this.supabaseKey\n  }\n\n  private _initSupabaseAuthClient(\n    {\n      autoRefreshToken,\n      persistSession,\n      detectSessionInUrl,\n      storage,\n      userStorage,\n      storageKey,\n      flowType,\n      lock,\n      debug,\n      throwOnError,\n    }: SupabaseAuthClientOptions,\n    headers?: Record<string, string>,\n    fetch?: Fetch\n  ) {\n    const authHeaders = {\n      Authorization: `Bearer ${this.supabaseKey}`,\n      apikey: `${this.supabaseKey}`,\n    }\n    return new SupabaseAuthClient({\n      url: this.authUrl.href,\n      headers: { ...authHeaders, ...headers },\n      storageKey: storageKey,\n      autoRefreshToken,\n      persistSession,\n      detectSessionInUrl,\n      storage,\n      userStorage,\n      flowType,\n      lock,\n      debug,\n      throwOnError,\n      fetch,\n      // auth checks if there is a custom authorizaiton header using this flag\n      // so it knows whether to return an error when getUser is called with no session\n      hasCustomAuthorizationHeader: Object.keys(this.headers).some(\n        (key) => key.toLowerCase() === 'authorization'\n      ),\n    })\n  }\n\n  private _initRealtimeClient(options: RealtimeClientOptions) {\n    return new RealtimeClient(this.realtimeUrl.href, {\n      ...options,\n      params: { ...{ apikey: this.supabaseKey }, ...options?.params },\n    })\n  }\n\n  private _listenForAuthEvents() {\n    const data = this.auth.onAuthStateChange((event, session) => {\n      this._handleTokenChanged(event, 'CLIENT', session?.access_token)\n    })\n    return data\n  }\n\n  private _handleTokenChanged(\n    event: AuthChangeEvent,\n    source: 'CLIENT' | 'STORAGE',\n    token?: string\n  ) {\n    if (\n      (event === 'TOKEN_REFRESHED' || event === 'SIGNED_IN') &&\n      this.changedAccessToken !== token\n    ) {\n      this.changedAccessToken = token\n      this.realtime.setAuth(token)\n    } else if (event === 'SIGNED_OUT') {\n      this.realtime.setAuth()\n      if (source == 'STORAGE') this.auth.signOut()\n      this.changedAccessToken = undefined\n    }\n  }\n}\n","// helpers.ts\nimport { SupabaseClientOptions } from './types'\n\nexport function uuid() {\n  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {\n    var r = (Math.random() * 16) | 0,\n      v = c == 'x' ? r : (r & 0x3) | 0x8\n    return v.toString(16)\n  })\n}\n\nexport function ensureTrailingSlash(url: string): string {\n  return url.endsWith('/') ? url : url + '/'\n}\n\nexport const isBrowser = () => typeof window !== 'undefined'\n\nexport function applySettingDefaults<\n  Database = any,\n  SchemaName extends string & keyof Database = 'public' extends keyof Database\n    ? 'public'\n    : string & keyof Database,\n>(\n  options: SupabaseClientOptions<SchemaName>,\n  defaults: SupabaseClientOptions<any>\n): Required<SupabaseClientOptions<SchemaName>> {\n  const {\n    db: dbOptions,\n    auth: authOptions,\n    realtime: realtimeOptions,\n    global: globalOptions,\n  } = options\n  const {\n    db: DEFAULT_DB_OPTIONS,\n    auth: DEFAULT_AUTH_OPTIONS,\n    realtime: DEFAULT_REALTIME_OPTIONS,\n    global: DEFAULT_GLOBAL_OPTIONS,\n  } = defaults\n\n  const result: Required<SupabaseClientOptions<SchemaName>> = {\n    db: {\n      ...DEFAULT_DB_OPTIONS,\n      ...dbOptions,\n    },\n    auth: {\n      ...DEFAULT_AUTH_OPTIONS,\n      ...authOptions,\n    },\n    realtime: {\n      ...DEFAULT_REALTIME_OPTIONS,\n      ...realtimeOptions,\n    },\n    storage: {},\n    global: {\n      ...DEFAULT_GLOBAL_OPTIONS,\n      ...globalOptions,\n      headers: {\n        ...(DEFAULT_GLOBAL_OPTIONS?.headers ?? {}),\n        ...(globalOptions?.headers ?? {}),\n      },\n    },\n    accessToken: async () => '',\n  }\n\n  if (options.accessToken) {\n    result.accessToken = options.accessToken\n  } else {\n    // hack around Required<>\n    delete (result as any).accessToken\n  }\n\n  return result\n}\n\n/**\n * Validates a Supabase client URL\n *\n * @param {string} supabaseUrl - The Supabase client URL string.\n * @returns {URL} - The validated base URL.\n * @throws {Error}\n */\nexport function validateSupabaseUrl(supabaseUrl: string): URL {\n  const trimmedUrl = supabaseUrl?.trim()\n\n  if (!trimmedUrl) {\n    throw new Error('supabaseUrl is required.')\n  }\n\n  if (!trimmedUrl.match(/^https?:\\/\\//i)) {\n    throw new Error('Invalid supabaseUrl: Must be a valid HTTP or HTTPS URL.')\n  }\n\n  try {\n    return new URL(ensureTrailingSlash(trimmedUrl))\n  } catch {\n    throw Error('Invalid supabaseUrl: Provided URL is malformed.')\n  }\n}\n","import SupabaseClient from './SupabaseClient'\nimport type { SupabaseClientOptions } from './lib/types'\n\nexport * from '@supabase/auth-js'\nexport type { User as AuthUser, Session as AuthSession } from '@supabase/auth-js'\nexport type {\n  PostgrestResponse,\n  PostgrestSingleResponse,\n  PostgrestMaybeSingleResponse,\n} from '@supabase/postgrest-js'\nexport { PostgrestError } from '@supabase/postgrest-js'\nexport type { FunctionInvokeOptions } from '@supabase/functions-js'\nexport {\n  FunctionsHttpError,\n  FunctionsFetchError,\n  FunctionsRelayError,\n  FunctionsError,\n  FunctionRegion,\n} from '@supabase/functions-js'\nexport * from '@supabase/realtime-js'\nexport { default as SupabaseClient } from './SupabaseClient'\nexport type {\n  SupabaseClientOptions,\n  QueryResult,\n  QueryData,\n  QueryError,\n  DatabaseWithoutInternals,\n} from './lib/types'\n\n/**\n * Creates a new Supabase Client.\n *\n * @example\n * ```ts\n * import { createClient } from '@supabase/supabase-js'\n *\n * const supabase = createClient('https://xyzcompany.supabase.co', 'public-anon-key')\n * const { data, error } = await supabase.from('profiles').select('*')\n * ```\n */\nexport const createClient = <\n  Database = any,\n  SchemaNameOrClientOptions extends\n    | (string & keyof Omit<Database, '__InternalSupabase'>)\n    | { PostgrestVersion: string } = 'public' extends keyof Omit<Database, '__InternalSupabase'>\n    ? 'public'\n    : string & keyof Omit<Database, '__InternalSupabase'>,\n  SchemaName extends string &\n    keyof Omit<Database, '__InternalSupabase'> = SchemaNameOrClientOptions extends string &\n    keyof Omit<Database, '__InternalSupabase'>\n    ? SchemaNameOrClientOptions\n    : 'public' extends keyof Omit<Database, '__InternalSupabase'>\n      ? 'public'\n      : string & keyof Omit<Omit<Database, '__InternalSupabase'>, '__InternalSupabase'>,\n>(\n  supabaseUrl: string,\n  supabaseKey: string,\n  options?: SupabaseClientOptions<SchemaName>\n): SupabaseClient<Database, SchemaNameOrClientOptions, SchemaName> => {\n  return new SupabaseClient<Database, SchemaNameOrClientOptions, SchemaName>(\n    supabaseUrl,\n    supabaseKey,\n    options\n  )\n}\n\n// Check for Node.js <= 18 deprecation\nfunction shouldShowDeprecationWarning(): boolean {\n  // Skip in browser environments\n  if (typeof window !== 'undefined') {\n    return false\n  }\n\n  // Skip if process is not available (e.g., Edge Runtime)\n  // Use dynamic property access to avoid Next.js Edge Runtime static analysis warnings\n  const _process = (globalThis as any)['process']\n  if (!_process) {\n    return false\n  }\n\n  const processVersion = _process['version']\n  if (processVersion === undefined || processVersion === null) {\n    return false\n  }\n\n  const versionMatch = processVersion.match(/^v(\\d+)\\./)\n  if (!versionMatch) {\n    return false\n  }\n\n  const majorVersion = parseInt(versionMatch[1], 10)\n  return majorVersion <= 18\n}\n\nif (shouldShowDeprecationWarning()) {\n  console.warn(\n    `‚ö†Ô∏è  Node.js 18 and below are deprecated and will no longer be supported in future versions of @supabase/supabase-js. ` +\n      `Please upgrade to Node.js 20 or later. ` +\n      `For more information, visit: https://github.com/orgs/supabase/discussions/37217`\n  )\n}\n","import { createClient } from '@supabase/supabase-js';\n\nconst supabaseUrl = process.env.REACT_APP_SUPABASE_URL || 'https://ejemplo.supabase.co';\nconst supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY || 'clave-anonima';\n\nexport const supabase = createClient(supabaseUrl, supabaseAnonKey);","/**\n * mockClientDB.js\n * Local client database using localStorage.\n * Simulates client registration, login, and profile management.\n * CI is the unique identifier (no duplicates allowed).\n */\n\nconst STORAGE_KEY = 'tbb_clientes';\n\n// ‚îÄ‚îÄ Helpers ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nconst leerClientes = () => {\n    try {\n        return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];\n    } catch {\n        return [];\n    }\n};\n\nconst guardarClientes = (clientes) => {\n    localStorage.setItem(STORAGE_KEY, JSON.stringify(clientes));\n};\n\n// ‚îÄ‚îÄ Age Validation ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\n/**\n * Calculates age from a date string (YYYY-MM-DD).\n * @returns {number} Age in years\n */\nexport const calcularEdad = (fechaNacimiento) => {\n    const hoy = new Date();\n    const nacimiento = new Date(fechaNacimiento);\n    let edad = hoy.getFullYear() - nacimiento.getFullYear();\n    const mesActual = hoy.getMonth();\n    const mesNacimiento = nacimiento.getMonth();\n\n    if (mesActual < mesNacimiento || (mesActual === mesNacimiento && hoy.getDate() < nacimiento.getDate())) {\n        edad--;\n    }\n    return edad;\n};\n\n/**\n * @returns {boolean} true if age >= 18\n */\nexport const esMayorDeEdad = (fechaNacimiento) => {\n    return calcularEdad(fechaNacimiento) >= 18;\n};\n\n// ‚îÄ‚îÄ CRUD ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\n/**\n * Check if a CI is already registered.\n */\nexport const existeCI = (ci) => {\n    const clientes = leerClientes();\n    return clientes.some(c => c.ci === ci);\n};\n\n/**\n * Register a new client. Returns { exito, cliente?, error? }\n */\nexport const registrarCliente = ({\n    nombreCompleto,\n    ci,\n    telefono,\n    email,\n    password,\n    fechaNacimiento,\n    fotoPerfil,       // base64 string or filename\n    ciAnverso,        // base64 string or filename\n    ciReverso,        // base64 string or filename\n}) => {\n    // Validate required fields\n    if (!nombreCompleto || !ci || !password || !fechaNacimiento) {\n        return { exito: false, error: 'Campos obligatorios incompletos.' };\n    }\n\n    // Validate age\n    if (!esMayorDeEdad(fechaNacimiento)) {\n        return { exito: false, error: 'Debe ser mayor de 18 a√±os para registrarse.' };\n    }\n\n    // Check CI uniqueness\n    if (existeCI(ci)) {\n        return { exito: false, error: 'Este n√∫mero de CI ya est√° registrado.' };\n    }\n\n    const clientes = leerClientes();\n    const nuevoCliente = {\n        id: 'cli-' + Date.now() + '-' + Math.random().toString(36).substr(2, 4),\n        nombreCompleto,\n        ci,\n        telefono: telefono || '',\n        email: email || '',\n        password, // In production this would be hashed!\n        fechaNacimiento,\n        fotoPerfil: fotoPerfil || null,\n        ciAnverso: ciAnverso || null,\n        ciReverso: ciReverso || null,\n        rol: 'cliente',\n        creadoEn: new Date().toISOString(),\n    };\n\n    clientes.push(nuevoCliente);\n    guardarClientes(clientes);\n\n    // Return without password for security\n    const { password: _, ...perfilSeguro } = nuevoCliente;\n    return { exito: true, cliente: perfilSeguro };\n};\n\n/**\n * Login client by CI + password. Returns { exito, cliente?, error? }\n */\nexport const loginCliente = (ci, password) => {\n    const clientes = leerClientes();\n    const encontrado = clientes.find(c => c.ci === ci);\n\n    if (!encontrado) {\n        return { exito: false, error: 'CI no encontrado. ¬øYa te registraste?' };\n    }\n\n    if (encontrado.password !== password) {\n        return { exito: false, error: 'Contrase√±a incorrecta.' };\n    }\n\n    const { password: _, ...perfilSeguro } = encontrado;\n    return { exito: true, cliente: perfilSeguro };\n};\n\n/**\n * Get client profile by CI (without password).\n */\nexport const obtenerCliente = (ci) => {\n    const clientes = leerClientes();\n    const encontrado = clientes.find(c => c.ci === ci);\n    if (!encontrado) return null;\n    const { password: _, ...perfilSeguro } = encontrado;\n    return perfilSeguro;\n};\n\nexport default {\n    calcularEdad,\n    esMayorDeEdad,\n    existeCI,\n    registrarCliente,\n    loginCliente,\n    obtenerCliente,\n};\n","import React, { createContext, useContext, useEffect, useState } from 'react';\nimport { supabase } from '../servicios/supabase';\nimport { loginCliente as mockLoginCliente } from '../data/mockClientDB';\n\n// ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n// AuthContext\n// Maneja el estado global de autenticaci√≥n interactuando\n// con Supabase Auth y la tabla 'usuarios' (RBAC).\n// ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nconst AuthContext = createContext();\n\nexport const AuthProvider = ({ children }) => {\n    const [sesion, setSesion] = useState(null);\n    const [perfil, setPerfil] = useState(null); // Data desde la tabla `usuarios` (email, rol, sucursal_id)\n    const [cargandoAuth, setCargandoAuth] = useState(true);\n\n    useEffect(() => {\n        let subscription;\n        \n        const initAuth = async () => {\n            try {\n                // Supabase gestiona por defecto la sesi√≥n en localStorage\n                // Validar si existe la sesion fake\n                if (localStorage.getItem('tbb_fake_admin') === 'true') {\n                    const adminProfileLocal = { id: 'admin-local', email: 'admin@tbb.com', rol: 'admin_sucursal', nombre_completo: 'Admin Supremo' };\n                    setSesion({ user: adminProfileLocal });\n                    setPerfil(adminProfileLocal);\n                    setCargandoAuth(false);\n                    return;\n                }\n\n                // Validar sesion fake de conductor\n                if (localStorage.getItem('tbb_fake_conductor') === 'true') {\n                    const conductorProfile = { id: 'conductor-local', email: 'conductor@tbb.com', rol: 'conductor', nombre_completo: 'Pedro Chofer' };\n                    setSesion({ user: conductorProfile });\n                    setPerfil(conductorProfile);\n                    setCargandoAuth(false);\n                    return;\n                }\n\n                // Validar sesion fake de cliente\n                const clienteGuardado = localStorage.getItem('tbb_fake_cliente');\n                if (clienteGuardado) {\n                    try {\n                        const clientePerfil = JSON.parse(clienteGuardado);\n                        setSesion({ user: clientePerfil });\n                        setPerfil(clientePerfil);\n                        setCargandoAuth(false);\n                        return;\n                    } catch { /* corrupted, continue */ }\n                }\n\n                const { data: { session }, error } = await supabase.auth.getSession();\n                if (error) throw error;\n                \n                await manejarSesion(session);\n                \n                // Suscribirse a cambios (Login/Logout din√°micos)\n                const { data } = supabase.auth.onAuthStateChange(async (_event, sessionObj) => {\n                    await manejarSesion(sessionObj);\n                });\n                \n                subscription = data.subscription;\n            } catch (err) {\n                console.error('Error inicializando AuthContext:', err);\n                setCargandoAuth(false);\n            }\n        };\n\n        initAuth();\n\n        return () => {\n            if (subscription) subscription.unsubscribe();\n        };\n    }, []);\n\n    // Helper para actualizar estado local y cargar del perfil RBAC\n    const manejarSesion = async (nuevaSesion) => {\n        setSesion(nuevaSesion);\n        \n        if (nuevaSesion?.user) {\n            try {\n                // Evitamos un fetch si el perfil ya est√° cargado y coincide el ID\n                const { data, error } = await supabase\n                    .from('usuarios')\n                    .select('id, email, rol, sucursal_id, nombre_completo')\n                    .eq('id', nuevaSesion.user.id)\n                    .maybeSingle();\n                \n                if (error) console.error('Error cargando perfil usuario:', error);\n                \n                if (data) {\n                    setPerfil(data);\n                } else {\n                    // Fallback: Si no hay registro en tabla usuarios, creamos rol base 'cliente' local\n                    // En producci√≥n un Trigger de BD deber√≠a auto-insertar.\n                    setPerfil({ \n                        id: nuevaSesion.user.id, \n                        email: nuevaSesion.user.email, \n                        rol: 'cliente' \n                    });\n                }\n            } catch (err) {\n                console.error('Error en manejarSesion - profile fetch:', err);\n                setPerfil(null);\n            }\n        } else {\n            setPerfil(null);\n        }\n        \n        setCargandoAuth(false);\n    };\n\n    // ‚îÄ‚îÄ Login Staff / Admin ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n    const login = async (email, password) => {\n        try {\n            // BACKDOOR TEMPORAL PARA PRUEBAS (Hardcoded Admin)\n            if (email === 'admin@tbb.com' && password === 'admin123456') {\n                const adminProfileLocal = { id: 'admin-local', email: email, rol: 'admin_sucursal', nombre_completo: 'Admin Supremo' };\n                const mockSession = { user: adminProfileLocal };\n                \n                setSesion(mockSession);\n                setPerfil(adminProfileLocal);\n                \n                // Keep fake session alive in memory/storage\n                localStorage.setItem('tbb_fake_admin', 'true');\n                return { exito: true };\n            }\n\n            // BACKDOOR TEMPORAL: Conductor de prueba\n            if (email === 'conductor@tbb.com' && password === 'conductor123456') {\n                const conductorProfile = { id: 'conductor-local', email: email, rol: 'conductor', nombre_completo: 'Pedro Chofer' };\n                const mockSession = { user: conductorProfile };\n                \n                setSesion(mockSession);\n                setPerfil(conductorProfile);\n                \n                localStorage.setItem('tbb_fake_conductor', 'true');\n                return { exito: true };\n            }\n\n            const { data, error } = await supabase.auth.signInWithPassword({\n                email,\n                password,\n            });\n            if (error) throw error;\n            return { exito: true, user: data.user };\n        } catch (error) {\n            return { exito: false, error: error.message };\n        }\n    };\n\n    // ‚îÄ‚îÄ Logout ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n    const logout = async () => {\n        if (localStorage.getItem('tbb_fake_admin') === 'true') {\n            localStorage.removeItem('tbb_fake_admin');\n            setSesion(null);\n            setPerfil(null);\n            return { exito: true };\n        }\n\n        if (localStorage.getItem('tbb_fake_conductor') === 'true') {\n            localStorage.removeItem('tbb_fake_conductor');\n            setSesion(null);\n            setPerfil(null);\n            return { exito: true };\n        }\n\n        if (localStorage.getItem('tbb_fake_cliente')) {\n            localStorage.removeItem('tbb_fake_cliente');\n            setSesion(null);\n            setPerfil(null);\n            return { exito: true };\n        }\n\n        try {\n            const { error } = await supabase.auth.signOut();\n            if (error) throw error;\n            setSesion(null);\n            setPerfil(null);\n        } catch (error) {\n            console.error('Error durante el logout:', error);\n        }\n    };\n\n    // ‚îÄ‚îÄ Login Cliente (CI + password via mockClientDB) ‚îÄ‚îÄ\n    const loginComoCliente = (ci, password) => {\n        const resultado = mockLoginCliente(ci, password);\n        if (resultado.exito) {\n            const clientePerfil = { ...resultado.cliente, rol: 'cliente' };\n            setSesion({ user: clientePerfil });\n            setPerfil(clientePerfil);\n            localStorage.setItem('tbb_fake_cliente', JSON.stringify(clientePerfil));\n        }\n        return resultado;\n    };\n\n    return (\n        <AuthContext.Provider value={{ sesion, perfil, cargandoAuth, login, loginComoCliente, logout }}>\n            {children}\n        </AuthContext.Provider>\n    );\n};\n\n// Custom hook helper\nexport const useAuth = () => useContext(AuthContext);\n","/**\n * Merges classes into a single string\n *\n * @param {array} classes\n * @returns {string} A string of classes\n */\nexport const mergeClasses = <ClassType = string | undefined | null>(...classes: ClassType[]) =>\n  classes\n    .filter((className, index, array) => {\n      return (\n        Boolean(className) &&\n        (className as string).trim() !== '' &&\n        array.indexOf(className) === index\n      );\n    })\n    .join(' ')\n    .trim();\n","import { CamelToPascal } from '../utility-types';\nimport { toCamelCase } from './toCamelCase';\n\n/**\n * Converts string to pascal case\n *\n * @param {string} string\n * @returns {string} A pascalized string\n */\nexport const toPascalCase = <T extends string>(string: T): CamelToPascal<T> => {\n  const camelCase = toCamelCase(string);\n\n  return (camelCase.charAt(0).toUpperCase() + camelCase.slice(1)) as CamelToPascal<T>;\n};\n","/**\n * Converts string to camel case\n *\n * @param {string} string\n * @returns {string} A camelized string\n */\nexport const toCamelCase = <T extends string>(string: T) =>\n  string.replace(/^([A-Z])|[\\s-_]+(\\w)/g, (match, p1, p2) =>\n    p2 ? p2.toUpperCase() : p1.toLowerCase(),\n  );\n","export default {\n  xmlns: 'http://www.w3.org/2000/svg',\n  width: 24,\n  height: 24,\n  viewBox: '0 0 24 24',\n  fill: 'none',\n  stroke: 'currentColor',\n  strokeWidth: 2,\n  strokeLinecap: 'round',\n  strokeLinejoin: 'round',\n};\n","/**\n * Check if a component has an accessibility prop\n *\n * @param {object} props\n * @returns {boolean} Whether the component has an accessibility prop\n */\nexport const hasA11yProp = (props: Record<string, any>) => {\n  for (const prop in props) {\n    if (prop.startsWith('aria-') || prop === 'role' || prop === 'title') {\n      return true;\n    }\n  }\n\n  return false;\n};\n","'use client';\n\nimport { createContext, createElement, type ReactNode, useContext, useMemo } from 'react';\nimport { LucideProps } from './types';\n\ntype LucideConfig = {\n  size: number;\n  color: string;\n  strokeWidth: number;\n  absoluteStrokeWidth: boolean;\n  className: string;\n};\n\nconst LucideContext = createContext<LucideProps>({});\n\ntype LucideProviderProps = {\n  children: ReactNode;\n} & Partial<LucideConfig>;\n\nexport function LucideProvider({\n  children,\n  size,\n  color,\n  strokeWidth,\n  absoluteStrokeWidth,\n  className,\n}: LucideProviderProps) {\n  const value = useMemo(\n    () => ({\n      size,\n      color,\n      strokeWidth,\n      absoluteStrokeWidth,\n      className,\n    }),\n    [size, color, strokeWidth, absoluteStrokeWidth, className],\n  );\n\n  return createElement(LucideContext.Provider, { value }, children);\n}\n\nexport const useLucideContext = () => useContext(LucideContext);\n","'use client';\n\nimport { createElement, forwardRef } from 'react';\nimport defaultAttributes from './defaultAttributes';\nimport { IconNode, LucideProps } from './types';\nimport { mergeClasses, hasA11yProp } from '@lucide/shared';\nimport { useLucideContext } from './context';\n\ninterface IconComponentProps extends LucideProps {\n  iconNode: IconNode;\n}\n\n/**\n * Lucide icon component\n *\n * @component Icon\n * @param {object} props\n * @param {string} props.color - The color of the icon\n * @param {number} props.size - The size of the icon\n * @param {number} props.strokeWidth - The stroke width of the icon\n * @param {boolean} props.absoluteStrokeWidth - Whether to use absolute stroke width\n * @param {string} props.className - The class name of the icon\n * @param {IconNode} props.children - The children of the icon\n * @param {IconNode} props.iconNode - The icon node of the icon\n *\n * @returns {ForwardRefExoticComponent} LucideIcon\n */\nconst Icon = forwardRef<SVGSVGElement, IconComponentProps>(\n  (\n    { color, size, strokeWidth, absoluteStrokeWidth, className = '', children, iconNode, ...rest },\n    ref,\n  ) => {\n    const {\n      size: contextSize = 24,\n      strokeWidth: contextStrokeWidth = 2,\n      absoluteStrokeWidth: contextAbsoluteStrokeWidth = false,\n      color: contextColor = 'currentColor',\n      className: contextClass = '',\n    } = useLucideContext() ?? {};\n\n    const calculatedStrokeWidth =\n      absoluteStrokeWidth ?? contextAbsoluteStrokeWidth\n        ? (Number(strokeWidth ?? contextStrokeWidth) * 24) / Number(size ?? contextSize)\n        : strokeWidth ?? contextStrokeWidth;\n\n    return createElement(\n      'svg',\n      {\n        ref,\n        ...defaultAttributes,\n        width: size ?? contextSize ?? defaultAttributes.width,\n        height: size ?? contextSize ?? defaultAttributes.height,\n        stroke: color ?? contextColor,\n        strokeWidth: calculatedStrokeWidth,\n        className: mergeClasses('lucide', contextClass, className),\n        ...(!children && !hasA11yProp(rest) && { 'aria-hidden': 'true' }),\n        ...rest,\n      },\n      [\n        ...iconNode.map(([tag, attrs]) => createElement(tag, attrs)),\n        ...(Array.isArray(children) ? children : [children]),\n      ],\n    );\n  },\n);\n\nexport default Icon;\n","import { createElement, forwardRef } from 'react';\nimport { mergeClasses, toKebabCase, toPascalCase } from '@lucide/shared';\nimport { IconNode, LucideProps } from './types';\nimport Icon from './Icon';\n\n/**\n * Create a Lucide icon component\n * @param {string} iconName\n * @param {array} iconNode\n * @returns {ForwardRefExoticComponent} LucideIcon\n */\nconst createLucideIcon = (iconName: string, iconNode: IconNode) => {\n  const Component = forwardRef<SVGSVGElement, LucideProps>(({ className, ...props }, ref) =>\n    createElement(Icon, {\n      ref,\n      iconNode,\n      className: mergeClasses(\n        `lucide-${toKebabCase(toPascalCase(iconName))}`,\n        `lucide-${iconName}`,\n        className,\n      ),\n      ...props,\n    }),\n  );\n\n  Component.displayName = toPascalCase(iconName);\n\n  return Component;\n};\n\nexport default createLucideIcon;\n","/**\n * Converts string to kebab case\n *\n * @param {string} string\n * @returns {string} A kebabized string\n */\nexport const toKebabCase = (string: string) =>\n  string.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M21.801 10A10 10 0 1 1 17 3.335', key: 'yps3ct' }],\n  ['path', { d: 'm9 11 3 3L22 4', key: '1pflzl' }],\n];\n\n/**\n * @component @name CircleCheckBig\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/circle-check-big\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst CircleCheckBig = createLucideIcon('circle-check-big', __iconNode);\n\nexport default CircleCheckBig;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  [\n    'path',\n    {\n      d: 'm21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3',\n      key: 'wmoenq',\n    },\n  ],\n  ['path', { d: 'M12 9v4', key: 'juzpu7' }],\n  ['path', { d: 'M12 17h.01', key: 'p32p05' }],\n];\n\n/**\n * @component @name TriangleAlert\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/triangle-alert\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst TriangleAlert = createLucideIcon('triangle-alert', __iconNode);\n\nexport default TriangleAlert;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['circle', { cx: '12', cy: '12', r: '10', key: '1mglay' }],\n  ['path', { d: 'M12 16v-4', key: '1dtifu' }],\n  ['path', { d: 'M12 8h.01', key: 'e9boi3' }],\n];\n\n/**\n * @component @name Info\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/info\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Info = createLucideIcon('info', __iconNode);\n\nexport default Info;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M18 6 6 18', key: '1bl5f8' }],\n  ['path', { d: 'm6 6 12 12', key: 'd8bk6v' }],\n];\n\n/**\n * @component @name X\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/x\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst X = createLucideIcon('x', __iconNode);\n\nexport default X;\n","import React, { useState, useCallback, useContext, createContext } from 'react';\nimport { CheckCircle, AlertTriangle, Info, X } from 'lucide-react';\n\n/**\n * ToastNotifications ‚Äî Professional toast system replacing browser alerts.\n * Provides a context + hook for global toast access.\n */\n\nconst ToastContext = createContext(null);\n\nexport const useToast = () => {\n    const ctx = useContext(ToastContext);\n    if (!ctx) throw new Error('useToast must be used within ToastProvider');\n    return ctx;\n};\n\nconst TOAST_COLORS = {\n    exito: { bg: 'rgba(16,185,129,0.15)', border: '#065f46', text: '#6ee7b7', icon: <CheckCircle size={18} /> },\n    error: { bg: 'rgba(239,68,68,0.15)', border: '#7f1d1d', text: '#fca5a5', icon: <AlertTriangle size={18} /> },\n    info: { bg: 'rgba(59,130,246,0.15)', border: '#1e3a5f', text: '#93c5fd', icon: <Info size={18} /> },\n    alerta: { bg: 'rgba(245,158,11,0.15)', border: '#78350f', text: '#fcd34d', icon: <AlertTriangle size={18} /> },\n};\n\nexport const ToastProvider = ({ children }) => {\n    const [toasts, setToasts] = useState([]);\n\n    const mostrar = useCallback((mensaje, tipo = 'info', duracion = 4000) => {\n        const id = Date.now() + Math.random();\n        setToasts(prev => [...prev, { id, mensaje, tipo }]);\n        setTimeout(() => {\n            setToasts(prev => prev.filter(t => t.id !== id));\n        }, duracion);\n    }, []);\n\n    const cerrar = (id) => setToasts(prev => prev.filter(t => t.id !== id));\n\n    return (\n        <ToastContext.Provider value={{ mostrar }}>\n            {children}\n\n            {/* Toast Container */}\n            <div style={{\n                position: 'fixed', top: '1rem', right: '1rem', zIndex: 9999,\n                display: 'flex', flexDirection: 'column', gap: '0.5rem',\n                maxWidth: '360px', width: '100%',\n            }}>\n                {toasts.map(t => {\n                    const style = TOAST_COLORS[t.tipo] || TOAST_COLORS.info;\n                    return (\n                        <div key={t.id} style={{\n                            background: style.bg, border: `1px solid ${style.border}`,\n                            borderRadius: '10px', padding: '0.75rem 1rem',\n                            display: 'flex', alignItems: 'center', gap: '0.6rem',\n                            animation: 'slideIn 0.3s ease-out',\n                            backdropFilter: 'blur(12px)',\n                        }}>\n                            <span style={{ color: style.text, flexShrink: 0 }}>{style.icon}</span>\n                            <span style={{ color: style.text, fontSize: '0.85rem', flex: 1 }}>{t.mensaje}</span>\n                            <button onClick={() => cerrar(t.id)} style={{\n                                background: 'transparent', border: 'none', color: style.text,\n                                cursor: 'pointer', padding: '0.2rem', flexShrink: 0, opacity: 0.6,\n                            }}>\n                                <X size={14} />\n                            </button>\n                        </div>\n                    );\n                })}\n            </div>\n\n            <style>{`\n                @keyframes slideIn {\n                    from { transform: translateX(100%); opacity: 0; }\n                    to { transform: translateX(0); opacity: 1; }\n                }\n            `}</style>\n        </ToastContext.Provider>\n    );\n};\n\nexport default ToastProvider;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  [\n    'path',\n    {\n      d: 'M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z',\n      key: 'r04s7s',\n    },\n  ],\n];\n\n/**\n * @component @name Star\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/star\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Star = createLucideIcon('star', __iconNode);\n\nexport default Star;\n","/**\n * mockDiscoveryDB.js\n * Local data store for the Discovery & Feedback features (V4 Branch 2).\n * Manages: Sucursales with ratings, User feedback/reviews, Ranking calculation.\n */\n\nconst STORAGE_KEYS = {\n    FEEDBACK: 'tbb_feedback',\n};\n\n// ‚îÄ‚îÄ Helpers ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nconst leer = (key) => {\n    try {\n        return JSON.parse(localStorage.getItem(key)) || [];\n    } catch { return []; }\n};\n\nconst guardar = (key, data) => {\n    localStorage.setItem(key, JSON.stringify(data));\n};\n\n// ‚îÄ‚îÄ Sucursales Data (enriched for grid) ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const SUCURSALES_MOCK = [\n    {\n        id: 'demo-s1',\n        nombre: 'Trans Copacabana',\n        logoEmoji: 'üöå',\n        colorAccent: '#3b82f6',\n        ranking: 4.5,\n        scores: { bus: 4.5, tripulacion: 4.3, sucursal: 4.7 },\n        amenidades: ['WiFi', 'Bus Cama', 'Ba√±o'],\n        totalViajes: 12,\n    },\n    {\n        id: 'demo-s2',\n        nombre: 'El Dorado',\n        logoEmoji: '‚ú®',\n        colorAccent: '#f59e0b',\n        ranking: 4.0,\n        scores: { bus: 3.8, tripulacion: 4.2, sucursal: 4.0 },\n        amenidades: ['WiFi', 'TV'],\n        totalViajes: 8,\n    },\n    {\n        id: 'demo-s3',\n        nombre: 'Bol√≠var',\n        logoEmoji: 'ü¶Ö',\n        colorAccent: '#10b981',\n        ranking: 4.8,\n        scores: { bus: 4.9, tripulacion: 4.7, sucursal: 4.8 },\n        amenidades: ['WiFi', 'Bus Cama', 'Ba√±o', 'TV', 'Aire Acondicionado'],\n        totalViajes: 15,\n    },\n    {\n        id: 'demo-s4',\n        nombre: 'Todo Turismo',\n        logoEmoji: 'üåé',\n        colorAccent: '#8b5cf6',\n        ranking: 4.3,\n        scores: { bus: 4.1, tripulacion: 4.5, sucursal: 4.3 },\n        amenidades: ['WiFi', 'Ba√±o', 'Aire Acondicionado'],\n        totalViajes: 10,\n    },\n    {\n        id: 'demo-s5',\n        nombre: 'Panamericana',\n        logoEmoji: 'üõ£Ô∏è',\n        colorAccent: '#ef4444',\n        ranking: 3.7,\n        scores: { bus: 3.5, tripulacion: 3.9, sucursal: 3.7 },\n        amenidades: ['WiFi'],\n        totalViajes: 6,\n    },\n    {\n        id: 'demo-s6',\n        nombre: 'Litoral Express',\n        logoEmoji: '‚ö°',\n        colorAccent: '#06b6d4',\n        ranking: 4.1,\n        scores: { bus: 4.0, tripulacion: 4.2, sucursal: 4.1 },\n        amenidades: ['WiFi', 'TV', 'Ba√±o'],\n        totalViajes: 9,\n    },\n];\n\n/**\n * Get all sucursales sorted by ranking (highest first).\n * Recalculates ranking from feedback if available.\n */\nexport const obtenerSucursalesOrdenadas = () => {\n    const sucursales = SUCURSALES_MOCK.map(s => {\n        const feedbackRanking = calcularRankingPromedio(s.id);\n        return {\n            ...s,\n            ranking: feedbackRanking !== null ? feedbackRanking : s.ranking,\n        };\n    });\n    return sucursales.sort((a, b) => b.ranking - a.ranking);\n};\n\n/**\n * Get a single sucursal by ID.\n */\nexport const obtenerSucursalPorId = (id) => {\n    return SUCURSALES_MOCK.find(s => s.id === id) || null;\n};\n\n// ‚îÄ‚îÄ Viajes Mock (expanded for pagination demo) ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const VIAJES_SUCURSAL_MOCK = {\n    'demo-s1': [\n        { id: 'v1-1', origen: 'La Paz', destino: 'Cochabamba', salida: '2026-04-03T06:00:00', precio: 45, duracion_estimada: '7h 30min' },\n        { id: 'v1-2', origen: 'La Paz', destino: 'Santa Cruz', salida: '2026-04-03T20:00:00', precio: 85, duracion_estimada: '12h' },\n        { id: 'v1-3', origen: 'Cochabamba', destino: 'Sucre', salida: '2026-04-03T09:00:00', precio: 35, duracion_estimada: '5h' },\n        { id: 'v1-4', origen: 'La Paz', destino: 'Oruro', salida: '2026-04-03T14:00:00', precio: 25, duracion_estimada: '3h 30min' },\n        { id: 'v1-5', origen: 'La Paz', destino: 'Cochabamba', salida: '2026-04-04T06:00:00', precio: 50, duracion_estimada: '7h' },\n        { id: 'v1-6', origen: 'La Paz', destino: 'Potos√≠', salida: '2026-04-04T19:00:00', precio: 55, duracion_estimada: '9h' },\n        { id: 'v1-7', origen: 'Cochabamba', destino: 'Santa Cruz', salida: '2026-04-05T08:00:00', precio: 60, duracion_estimada: '6h' },\n    ],\n    'demo-s2': [\n        { id: 'v2-1', origen: 'La Paz', destino: 'Cochabamba', salida: '2026-04-03T07:00:00', precio: 40, duracion_estimada: '8h' },\n        { id: 'v2-2', origen: 'La Paz', destino: 'Santa Cruz', salida: '2026-04-03T21:00:00', precio: 80, duracion_estimada: '13h' },\n        { id: 'v2-3', origen: 'Oruro', destino: 'La Paz', salida: '2026-04-04T10:00:00', precio: 20, duracion_estimada: '3h' },\n        { id: 'v2-4', origen: 'La Paz', destino: 'Sucre', salida: '2026-04-04T18:00:00', precio: 65, duracion_estimada: '10h' },\n        { id: 'v2-5', origen: 'Cochabamba', destino: 'La Paz', salida: '2026-04-05T06:30:00', precio: 42, duracion_estimada: '7h 30min' },\n    ],\n    'demo-s3': [\n        { id: 'v3-1', origen: 'La Paz', destino: 'Cochabamba', salida: '2026-04-03T06:30:00', precio: 55, duracion_estimada: '7h' },\n        { id: 'v3-2', origen: 'La Paz', destino: 'Santa Cruz', salida: '2026-04-03T19:00:00', precio: 95, duracion_estimada: '11h' },\n        { id: 'v3-3', origen: 'Cochabamba', destino: 'Sucre', salida: '2026-04-03T10:00:00', precio: 40, duracion_estimada: '5h' },\n        { id: 'v3-4', origen: 'La Paz', destino: 'Oruro', salida: '2026-04-03T15:00:00', precio: 30, duracion_estimada: '3h' },\n        { id: 'v3-5', origen: 'La Paz', destino: 'Cochabamba', salida: '2026-04-04T06:00:00', precio: 55, duracion_estimada: '7h' },\n        { id: 'v3-6', origen: 'Santa Cruz', destino: 'La Paz', salida: '2026-04-04T20:00:00', precio: 90, duracion_estimada: '11h 30min' },\n        { id: 'v3-7', origen: 'La Paz', destino: 'Tarija', salida: '2026-04-05T18:00:00', precio: 100, duracion_estimada: '14h' },\n        { id: 'v3-8', origen: 'Cochabamba', destino: 'Santa Cruz', salida: '2026-04-05T09:00:00', precio: 65, duracion_estimada: '6h' },\n    ],\n};\n\n// Generate fallback for other sucursals\nconst generarViajesGenerico = (sucursalId) => [\n    { id: `${sucursalId}-v1`, origen: 'La Paz', destino: 'Cochabamba', salida: '2026-04-03T08:00:00', precio: 42, duracion_estimada: '7h 30min' },\n    { id: `${sucursalId}-v2`, origen: 'La Paz', destino: 'Santa Cruz', salida: '2026-04-03T20:00:00', precio: 78, duracion_estimada: '12h' },\n    { id: `${sucursalId}-v3`, origen: 'Cochabamba', destino: 'Sucre', salida: '2026-04-04T09:00:00', precio: 32, duracion_estimada: '5h' },\n    { id: `${sucursalId}-v4`, origen: 'La Paz', destino: 'Oruro', salida: '2026-04-04T14:00:00', precio: 22, duracion_estimada: '3h 30min' },\n];\n\nexport const obtenerViajesSucursal = (sucursalId) => {\n    return VIAJES_SUCURSAL_MOCK[sucursalId] || generarViajesGenerico(sucursalId);\n};\n\n// ‚îÄ‚îÄ Feedback System ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nconst AVATARES_GENERICOS = ['üßë', 'üë©', 'üë®', 'üßî', 'üë©‚Äçü¶±', 'üë®‚Äçü¶≥', 'üßë‚Äçü¶∞', 'üë©‚Äçü¶∞'];\n\n/**\n * Submit a feedback/review for a sucursal.\n */\nexport const enviarFeedback = ({ sucursalId, nombreUsuario, mood, labelsSeleccionados, comentario }) => {\n    const feedbacks = leer(STORAGE_KEYS.FEEDBACK);\n    const nuevo = {\n        id: 'fb-' + Date.now(),\n        sucursalId,\n        nombreUsuario: nombreUsuario || 'An√≥nimo',\n        avatarGenerico: AVATARES_GENERICOS[Math.floor(Math.random() * AVATARES_GENERICOS.length)],\n        mood, // 1-5\n        labelsSeleccionados: labelsSeleccionados || [],\n        comentario: comentario || '',\n        fecha: new Date().toISOString(),\n    };\n    feedbacks.push(nuevo);\n    guardar(STORAGE_KEYS.FEEDBACK, feedbacks);\n    return nuevo;\n};\n\n/**\n * Get all feedback for a sucursal.\n */\nexport const obtenerFeedback = (sucursalId) => {\n    const feedbacks = leer(STORAGE_KEYS.FEEDBACK);\n    return feedbacks\n        .filter(f => f.sucursalId === sucursalId)\n        .sort((a, b) => new Date(b.fecha) - new Date(a.fecha));\n};\n\n// ‚îÄ‚îÄ Ranking Calculation ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\n/**\n * Calculate the average ranking of a sucursal based on feedback moods.\n * Returns null if no feedback exists (falls back to default ranking).\n */\nexport const calcularRankingPromedio = (sucursalId) => {\n    const feedbacks = obtenerFeedback(sucursalId);\n    if (feedbacks.length === 0) return null;\n\n    const suma = feedbacks.reduce((acc, f) => acc + f.mood, 0);\n    return Math.round((suma / feedbacks.length) * 10) / 10; // 1 decimal\n};\n\n// ‚îÄ‚îÄ Mood Labels ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const obtenerLabelsPorMood = (mood) => {\n    if (mood <= 2) {\n        return [\n            { emoji: 'üßπ', texto: 'Limpieza' },\n            { emoji: 'üí∫', texto: 'Asientos' },\n            { emoji: '‚è∞', texto: 'Retraso' },\n            { emoji: 'üò§', texto: 'Trato' },\n            { emoji: 'üì∂', texto: 'WiFi' },\n        ];\n    }\n    if (mood === 3) {\n        return [\n            { emoji: 'üòê', texto: 'Aceptable' },\n            { emoji: 'üí∫', texto: 'Asientos' },\n            { emoji: 'üïê', texto: 'Puntualidad' },\n            { emoji: 'üßπ', texto: 'Limpieza' },\n        ];\n    }\n    // mood >= 4\n    return [\n        { emoji: 'ü§ù', texto: 'Buena atenci√≥n' },\n        { emoji: '‚ú®', texto: 'Bus limpio' },\n        { emoji: 'üèÅ', texto: 'Llegada puntual' },\n        { emoji: 'üõãÔ∏è', texto: 'Comodidad' },\n        { emoji: 'üéØ', texto: 'Rapidez' },\n    ];\n};\n\nexport default {\n    SUCURSALES_MOCK,\n    obtenerSucursalesOrdenadas,\n    obtenerSucursalPorId,\n    obtenerViajesSucursal,\n    enviarFeedback,\n    obtenerFeedback,\n    calcularRankingPromedio,\n    obtenerLabelsPorMood,\n};\n","import React, { useEffect, useState } from 'react';\nimport { Link } from 'react-router-dom';\nimport { Star } from 'lucide-react';\nimport { obtenerSucursalesOrdenadas } from '../data/mockDiscoveryDB';\nimport '../estilos/escritorio/principal.css';\nimport '../estilos/movil/responsivo.css';\n\n/**\n * Inicio - Premium grid of bus companies sorted by rating.\n * V4: Minimalist design ‚Äî only logo, name, and star rating.\n * Auto-sorted by ranking (highest first).\n */\nconst Inicio = () => {\n    const [sucursales, setSucursales] = useState([]);\n\n    useEffect(() => {\n        const data = obtenerSucursalesOrdenadas();\n        setSucursales(data);\n    }, []);\n\n    // Render star rating with lucide-react\n    const renderEstrellas = (ranking) => {\n        const stars = [];\n        const num = parseFloat(ranking) || 0;\n        for (let i = 1; i <= 5; i++) {\n            if (i <= Math.floor(num)) {\n                stars.push(<Star key={i} size={16} fill=\"#f59e0b\" color=\"#f59e0b\" strokeWidth={1.5} />);\n            } else if (i === Math.ceil(num) && num % 1 >= 0.3) {\n                stars.push(<Star key={i} size={16} fill=\"#f59e0b\" color=\"#f59e0b\" strokeWidth={1.5} style={{ clipPath: 'inset(0 50% 0 0)' }} />);\n            } else {\n                stars.push(<Star key={i} size={16} fill=\"none\" color=\"#475569\" strokeWidth={1.5} />);\n            }\n        }\n        return stars;\n    };\n\n    return (\n        <div style={{ backgroundColor: '#0f172a', minHeight: '100vh', color: '#f1f5f9', padding: '1.5rem 1rem 3rem' }}>\n            <div style={{ maxWidth: '900px', margin: '0 auto' }}>\n                {/* Hero Header */}\n                <div style={{ textAlign: 'center', marginBottom: '2rem', paddingTop: '1rem' }}>\n                    <h1 style={{ fontSize: '1.8rem', fontWeight: 800, marginBottom: '0.5rem', background: 'linear-gradient(135deg, #3b82f6, #10b981)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>\n                        Terminal de Buses Bolivia\n                    </h1>\n                    <p style={{ color: '#64748b', fontSize: '0.95rem', maxWidth: '400px', margin: '0 auto' }}>\n                        Elige tu empresa de confianza y viaja seguro\n                    </p>\n                </div>\n\n                {/* CTA Search */}\n                <Link to=\"/buscar\" style={{\n                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem',\n                    margin: '0 auto 2rem', padding: '0.85rem 1.5rem', maxWidth: '320px',\n                    background: 'linear-gradient(135deg, #3b82f6, #2563eb)', color: 'white',\n                    borderRadius: '12px', textDecoration: 'none', fontWeight: 600, fontSize: '0.95rem',\n                    boxShadow: '0 4px 14px rgba(59,130,246,0.35)', transition: 'transform 0.2s',\n                }} id=\"btn-ir-buscador\">\n                    üîç Buscar Viajes Disponibles\n                </Link>\n\n                {/* Sucursales Grid */}\n                <div style={{\n                    display: 'grid',\n                    gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))',\n                    gap: '1rem',\n                }}>\n                    {sucursales.map((s, index) => (\n                        <Link key={s.id} to={`/sucursal/${s.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>\n                            <div style={{\n                                background: '#1e293b',\n                                borderRadius: '14px',\n                                padding: '1.5rem',\n                                border: '1px solid #334155',\n                                transition: 'all 0.25s ease',\n                                cursor: 'pointer',\n                                position: 'relative',\n                                overflow: 'hidden',\n                            }}\n                            onMouseEnter={e => { e.currentTarget.style.borderColor = s.colorAccent; e.currentTarget.style.transform = 'translateY(-2px)'; e.currentTarget.style.boxShadow = `0 8px 25px ${s.colorAccent}22`; }}\n                            onMouseLeave={e => { e.currentTarget.style.borderColor = '#334155'; e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = 'none'; }}\n                            >\n                                {/* Ranking badge for top 3 */}\n                                {index < 3 && (\n                                    <div style={{\n                                        position: 'absolute', top: '0.75rem', right: '0.75rem',\n                                        background: index === 0 ? '#f59e0b' : index === 1 ? '#94a3b8' : '#cd7f32',\n                                        color: '#0f172a', fontSize: '0.7rem', fontWeight: 800,\n                                        padding: '0.2rem 0.5rem', borderRadius: '6px',\n                                    }}>\n                                        #{index + 1}\n                                    </div>\n                                )}\n\n                                {/* Logo */}\n                                <div style={{\n                                    width: '56px', height: '56px', borderRadius: '14px',\n                                    background: `${s.colorAccent}15`,\n                                    border: `1px solid ${s.colorAccent}30`,\n                                    display: 'flex', alignItems: 'center', justifyContent: 'center',\n                                    fontSize: '1.8rem', marginBottom: '1rem',\n                                }}>\n                                    {s.logoEmoji}\n                                </div>\n\n                                {/* Name */}\n                                <h3 style={{\n                                    margin: '0 0 0.6rem 0', fontSize: '1.1rem', fontWeight: 700,\n                                    color: '#f1f5f9',\n                                }}>\n                                    {s.nombre}\n                                </h3>\n\n                                {/* Stars */}\n                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.35rem' }}>\n                                    {renderEstrellas(s.ranking)}\n                                    <span style={{ color: '#94a3b8', fontSize: '0.85rem', marginLeft: '0.3rem', fontWeight: 500 }}>\n                                        {s.ranking}\n                                    </span>\n                                </div>\n                            </div>\n                        </Link>\n                    ))}\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default Inicio;","import React from 'react';\n\n/**\n * TarjetaViaje - Componente reutilizable para mostrar un viaje individual.\n * Muestra: sucursal, ranking (estrellas), ruta, hora, precio, duraci√≥n y amenidades.\n * Props:\n *   - viaje: objeto con datos del viaje (sucursal, origen, destino, salida, precio, etc.)\n *   - onSeleccionar: callback al presionar \"Seleccionar\" (futuro m√≥dulo de asientos)\n */\nconst TarjetaViaje = ({ viaje, onSeleccionar }) => {\n\n    // Genera estrellas visuales basadas en el ranking (1-5)\n    const renderEstrellas = (ranking) => {\n        const estrellas = [];\n        const rankingNum = parseFloat(ranking) || 0;\n        const llenas = Math.floor(rankingNum);\n        const tieneMedia = rankingNum % 1 >= 0.5;\n\n        for (let i = 0; i < llenas; i++) {\n            estrellas.push(<span key={`full-${i}`} className=\"estrella llena\">‚òÖ</span>);\n        }\n        if (tieneMedia) {\n            estrellas.push(<span key=\"half\" className=\"estrella media\">‚òÖ</span>);\n        }\n        const vacias = 5 - llenas - (tieneMedia ? 1 : 0);\n        for (let i = 0; i < vacias; i++) {\n            estrellas.push(<span key={`empty-${i}`} className=\"estrella vacia\">‚òÜ</span>);\n        }\n        return estrellas;\n    };\n\n    // Mapeo de colores para cada tipo de amenidad\n    const colorAmenidad = (amenidad) => {\n        const colores = {\n            'WiFi': 'tag-wifi',\n            'Bus Cama': 'tag-cama',\n            'Ba√±o': 'tag-bano',\n            'TV': 'tag-tv',\n            'Aire Acondicionado': 'tag-aire',\n        };\n        return colores[amenidad] || 'tag-default';\n    };\n\n    // Formatear hora de salida a formato legible\n    const formatearHora = (fechaStr) => {\n        try {\n            const fecha = new Date(fechaStr);\n            return fecha.toLocaleTimeString('es-BO', {\n                hour: '2-digit',\n                minute: '2-digit',\n                hour12: true\n            });\n        } catch {\n            return '--:--';\n        }\n    };\n\n    // Formatear fecha completa\n    const formatearFecha = (fechaStr) => {\n        try {\n            const fecha = new Date(fechaStr);\n            return fecha.toLocaleDateString('es-BO', {\n                weekday: 'short',\n                day: 'numeric',\n                month: 'short'\n            });\n        } catch {\n            return '';\n        }\n    };\n\n    return (\n        <div className=\"tarjeta-viaje\" id={`viaje-${viaje.id}`}>\n            {/* Cabecera: Sucursal + Rating */}\n            <div className=\"viaje-cabecera\">\n                <div className=\"viaje-sucursal\">\n                    <h3 className=\"sucursal-nombre\">{viaje.sucursal_nombre}</h3>\n                    <div className=\"viaje-rating\">\n                        {renderEstrellas(viaje.ranking)}\n                        <span className=\"rating-numero\">({viaje.ranking})</span>\n                    </div>\n                </div>\n            </div>\n\n            {/* Ruta: Origen ‚Üí Destino */}\n            <div className=\"viaje-ruta\">\n                <div className=\"ruta-punto origen\">\n                    <span className=\"ruta-icono\">üìç</span>\n                    <span className=\"ruta-ciudad\">{viaje.origen}</span>\n                </div>\n                <div className=\"ruta-linea\">\n                    <span className=\"ruta-flecha\">‚Üí</span>\n                    {viaje.duracion_estimada && (\n                        <span className=\"ruta-duracion\">üïê {viaje.duracion_estimada}</span>\n                    )}\n                </div>\n                <div className=\"ruta-punto destino\">\n                    <span className=\"ruta-icono\">üìç</span>\n                    <span className=\"ruta-ciudad\">{viaje.destino}</span>\n                </div>\n            </div>\n\n            {/* Detalles: Fecha, Hora, Precio */}\n            <div className=\"viaje-detalles\">\n                <div className=\"detalle-item\">\n                    <span className=\"detalle-label\">Salida</span>\n                    <span className=\"detalle-valor\">\n                        {formatearFecha(viaje.salida)} ‚Ä¢ {formatearHora(viaje.salida)}\n                    </span>\n                </div>\n                <div className=\"detalle-item detalle-precio\">\n                    <span className=\"detalle-label\">Precio</span>\n                    <span className=\"detalle-valor precio-valor\">\n                        Bs {parseFloat(viaje.precio || 0).toFixed(2)}\n                    </span>\n                </div>\n            </div>\n\n            {/* Tags de amenidades */}\n            {viaje.amenidades && viaje.amenidades.length > 0 && (\n                <div className=\"viaje-amenidades\">\n                    {viaje.amenidades.map((amenidad, index) => (\n                        <span key={index} className={`amenidad-tag ${colorAmenidad(amenidad)}`}>\n                            {amenidad}\n                        </span>\n                    ))}\n                </div>\n            )}\n\n            {/* Bot√≥n de acci√≥n */}\n            <button\n                className=\"btn-seleccionar\"\n                onClick={() => onSeleccionar && onSeleccionar(viaje)}\n                id={`btn-seleccionar-${viaje.id}`}\n            >\n                Seleccionar\n            </button>\n        </div>\n    );\n};\n\nexport default TarjetaViaje;\n","import React, { useState } from 'react';\n\n/**\n * PanelFiltros - Reusable filter panel component for multi-scope filtering.\n * Supports: Price range (min/max in Bs), Quality (minimum stars 1-5),\n * and Amenities (checkbox toggles for WiFi, Bus Cama, Ba√±o, TV, Aire Acondicionado).\n *\n * Props:\n *   - filtros: current filter state object\n *   - onFiltrosChange: callback(newFiltros) when filters are modified\n *   - modoSucursal: boolean - if true, hides scope label (used inside branch view)\n *   - onBuscar: callback to trigger search with current filters\n */\n\nconst AMENIDADES_DISPONIBLES = [\n    { id: 'WiFi', label: 'WiFi', icono: 'üì∂' },\n    { id: 'Bus Cama', label: 'Bus Cama', icono: 'üõèÔ∏è' },\n    { id: 'Ba√±o', label: 'Ba√±o', icono: 'üöø' },\n    { id: 'TV', label: 'TV', icono: 'üì∫' },\n    { id: 'Aire Acondicionado', label: 'Aire Acondicionado', icono: '‚ùÑÔ∏è' },\n];\n\nconst PanelFiltros = ({ filtros, onFiltrosChange, modoSucursal = false, onBuscar }) => {\n    const [expandido, setExpandido] = useState(false);\n\n    // Update a single filter field\n    const actualizarFiltro = (campo, valor) => {\n        onFiltrosChange({ ...filtros, [campo]: valor });\n    };\n\n    // Toggle an amenity in the selected amenities array\n    const toggleAmenidad = (amenidadId) => {\n        const actuales = filtros.amenidades || [];\n        const nuevas = actuales.includes(amenidadId)\n            ? actuales.filter(a => a !== amenidadId)\n            : [...actuales, amenidadId];\n        actualizarFiltro('amenidades', nuevas);\n    };\n\n    // Reset all filters to default values\n    const limpiarFiltros = () => {\n        onFiltrosChange({\n            precioMin: '',\n            precioMax: '',\n            calidadMinima: 0,\n            amenidades: [],\n        });\n    };\n\n    // Render interactive star rating selector (1-5)\n    const renderEstrellasFiltro = () => {\n        const estrellas = [];\n        for (let i = 1; i <= 5; i++) {\n            estrellas.push(\n                <button\n                    key={i}\n                    type=\"button\"\n                    className={`estrella-filtro ${i <= filtros.calidadMinima ? 'activa' : ''}`}\n                    onClick={() => actualizarFiltro('calidadMinima', i === filtros.calidadMinima ? 0 : i)}\n                    aria-label={`M√≠nimo ${i} estrellas`}\n                    id={`filtro-estrella-${i}`}\n                >\n                    {i <= filtros.calidadMinima ? '‚òÖ' : '‚òÜ'}\n                </button>\n            );\n        }\n        return estrellas;\n    };\n\n    // Check if any filter is active (for visual feedback)\n    const tienesFiltrosActivos = () => {\n        return (\n            filtros.precioMin !== '' ||\n            filtros.precioMax !== '' ||\n            filtros.calidadMinima > 0 ||\n            (filtros.amenidades && filtros.amenidades.length > 0)\n        );\n    };\n\n    return (\n        <div className={`panel-filtros ${expandido ? 'expandido' : ''}`} id=\"panel-filtros-avanzados\">\n            {/* Toggle button for mobile collapse/expand */}\n            <button\n                className=\"filtros-toggle\"\n                onClick={() => setExpandido(!expandido)}\n                id=\"btn-toggle-filtros\"\n                type=\"button\"\n            >\n                <span className=\"filtros-toggle-icono\">‚öôÔ∏è</span>\n                <span>Filtros Avanzados</span>\n                {tienesFiltrosActivos() && <span className=\"filtros-badge\">‚óè</span>}\n                <span className={`filtros-flecha ${expandido ? 'abierta' : ''}`}>‚ñº</span>\n            </button>\n\n            {/* Scope indicator */}\n            {!modoSucursal && (\n                <div className=\"filtros-scope\">\n                    <span className=\"scope-icono\">üåê</span>\n                    <span>Buscando en todas las sucursales</span>\n                </div>\n            )}\n            {modoSucursal && (\n                <div className=\"filtros-scope filtros-scope-sucursal\">\n                    <span className=\"scope-icono\">üè¢</span>\n                    <span>Filtros de esta sucursal</span>\n                </div>\n            )}\n\n            <div className=\"filtros-contenido\">\n                {/* Price range filter */}\n                <div className=\"filtro-seccion\">\n                    <label className=\"filtro-seccion-label\">Rango de Precio (Bs)</label>\n                    <div className=\"filtro-rango-precio\">\n                        <input\n                            type=\"number\"\n                            className=\"filtro-input filtro-precio\"\n                            placeholder=\"M√≠n\"\n                            value={filtros.precioMin}\n                            onChange={(e) => actualizarFiltro('precioMin', e.target.value)}\n                            min=\"0\"\n                            id=\"filtro-precio-min\"\n                        />\n                        <span className=\"filtro-rango-separador\">‚Äî</span>\n                        <input\n                            type=\"number\"\n                            className=\"filtro-input filtro-precio\"\n                            placeholder=\"M√°x\"\n                            value={filtros.precioMax}\n                            onChange={(e) => actualizarFiltro('precioMax', e.target.value)}\n                            min=\"0\"\n                            id=\"filtro-precio-max\"\n                        />\n                    </div>\n                </div>\n\n                {/* Quality (stars) filter */}\n                <div className=\"filtro-seccion\">\n                    <label className=\"filtro-seccion-label\">Calidad M√≠nima</label>\n                    <div className=\"filtro-estrellas\">\n                        {renderEstrellasFiltro()}\n                        {filtros.calidadMinima > 0 && (\n                            <span className=\"filtro-estrellas-texto\">\n                                {filtros.calidadMinima}+ estrellas\n                            </span>\n                        )}\n                    </div>\n                </div>\n\n                {/* Amenities filter */}\n                <div className=\"filtro-seccion\">\n                    <label className=\"filtro-seccion-label\">Caracter√≠sticas del Bus</label>\n                    <div className=\"filtro-amenidades-grid\">\n                        {AMENIDADES_DISPONIBLES.map(amenidad => (\n                            <button\n                                key={amenidad.id}\n                                type=\"button\"\n                                className={`filtro-amenidad-btn ${\n                                    (filtros.amenidades || []).includes(amenidad.id) ? 'seleccionada' : ''\n                                }`}\n                                onClick={() => toggleAmenidad(amenidad.id)}\n                                id={`filtro-amenidad-${amenidad.id.replace(/\\s+/g, '-').toLowerCase()}`}\n                            >\n                                <span className=\"amenidad-btn-icono\">{amenidad.icono}</span>\n                                <span className=\"amenidad-btn-label\">{amenidad.label}</span>\n                            </button>\n                        ))}\n                    </div>\n                </div>\n\n                {/* Action buttons */}\n                <div className=\"filtros-acciones\">\n                    {tienesFiltrosActivos() && (\n                        <button\n                            type=\"button\"\n                            className=\"btn-limpiar-filtros\"\n                            onClick={limpiarFiltros}\n                            id=\"btn-limpiar-filtros\"\n                        >\n                            ‚úï Limpiar filtros\n                        </button>\n                    )}\n                    {onBuscar && (\n                        <button\n                            type=\"button\"\n                            className=\"btn-aplicar-filtros\"\n                            onClick={onBuscar}\n                            id=\"btn-aplicar-filtros\"\n                        >\n                            Aplicar Filtros\n                        </button>\n                    )}\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default PanelFiltros;\n","import React, { useState, useEffect } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { supabase } from '../servicios/supabase';\nimport { useAuth } from '../contextos/AuthContext';\nimport TarjetaViaje from '../componentes/TarjetaViaje';\nimport PanelFiltros from '../componentes/PanelFiltros';\nimport '../estilos/escritorio/buscador.css';\nimport '../estilos/escritorio/filtros.css';\nimport '../estilos/movil/buscador-responsivo.css';\nimport '../estilos/movil/filtros-responsivo.css';\n\n/**\n * Predefined Bolivian cities for origin/destination selectors.\n * Sorted alphabetically for easy lookup.\n */\nconst CIUDADES_BOLIVIA = [\n    'Cobija',\n    'Cochabamba',\n    'La Paz',\n    'Oruro',\n    'Potos√≠',\n    'Santa Cruz',\n    'Sucre',\n    'Tarija',\n    'Trinidad',\n];\n\n/**\n * Demo data for visualizing the design without a Supabase connection.\n * NOTE: Remove when connected to the real database.\n */\nconst DATOS_DEMO = [\n    {\n        id: 'demo-1',\n        sucursal_nombre: 'Trans Copacabana',\n        ranking: 4.5,\n        origen: 'La Paz',\n        destino: 'Cochabamba',\n        salida: '2026-03-23T08:00:00',\n        precio: 45.00,\n        duracion_estimada: '7h 30min',\n        amenidades: ['WiFi', 'Bus Cama', 'Ba√±o'],\n    },\n    {\n        id: 'demo-2',\n        sucursal_nombre: 'El Dorado',\n        ranking: 4.0,\n        origen: 'La Paz',\n        destino: 'Cochabamba',\n        salida: '2026-03-23T10:30:00',\n        precio: 35.00,\n        duracion_estimada: '8h 00min',\n        amenidades: ['WiFi', 'TV'],\n    },\n    {\n        id: 'demo-3',\n        sucursal_nombre: 'Bol√≠var',\n        ranking: 4.8,\n        origen: 'La Paz',\n        destino: 'Cochabamba',\n        salida: '2026-03-23T21:00:00',\n        precio: 65.00,\n        duracion_estimada: '7h 00min',\n        amenidades: ['WiFi', 'Bus Cama', 'Ba√±o', 'TV', 'Aire Acondicionado'],\n    },\n    {\n        id: 'demo-4',\n        sucursal_nombre: 'Trans Copacabana',\n        ranking: 4.5,\n        origen: 'La Paz',\n        destino: 'Cochabamba',\n        salida: '2026-03-23T23:30:00',\n        precio: 50.00,\n        duracion_estimada: '7h 15min',\n        amenidades: ['WiFi', 'Ba√±o', 'Aire Acondicionado'],\n    },\n];\n\n/**\n * BuscadorViajes - Global trip search page with advanced multi-scope filtering.\n * Queries all branches (sucursales) with dynamic filters:\n * - Origin/Destination/Date (basic)\n * - Price range, quality stars, amenities (advanced via PanelFiltros)\n * Uses react-router-dom useNavigate for the back button.\n */\nconst BuscadorViajes = () => {\n    const navigate = useNavigate();\n\n    // Basic search filters\n    const [origen, setOrigen] = useState('');\n    const [destino, setDestino] = useState('');\n    const [fecha, setFecha] = useState('');\n\n    // Advanced filter state managed by PanelFiltros\n    const [filtrosAvanzados, setFiltrosAvanzados] = useState({\n        precioMin: '',\n        precioMax: '',\n        calidadMinima: 0,\n        amenidades: [],\n    });\n\n    // Results state\n    const [resultados, setResultados] = useState([]);\n    const [cargando, setCargando] = useState(false);\n    const [buscado, setBuscado] = useState(false);\n\n    /**\n     * Executes trip search against Supabase with all active filters.\n     * Builds query dynamically: basic filters (origin, destination, date)\n     * plus advanced filters (price range, star rating, amenities).\n     * Falls back to filtered demo data if Supabase is unavailable.\n     */\n    const buscarViajes = async () => {\n        if (!origen || !destino) return;\n\n        setCargando(true);\n        setBuscado(true);\n\n        try {\n            // Build Supabase query with implicit JOINs\n            let query = supabase\n                .from('viajes')\n                .select(`\n                    id,\n                    origen,\n                    destino,\n                    salida,\n                    precio,\n                    duracion_estimada,\n                    estado,\n                    buses!inner (\n                        id,\n                        capacidad,\n                        sucursales!inner (\n                            nombre,\n                            ranking,\n                            amenidades\n                        )\n                    )\n                `)\n                .eq('origen', origen)\n                .eq('destino', destino)\n                .eq('estado', 'programado')\n                .order('salida', { ascending: true });\n\n            // Optional date filter\n            if (fecha) {\n                const fechaInicio = `${fecha}T00:00:00`;\n                const fechaFin = `${fecha}T23:59:59`;\n                query = query.gte('salida', fechaInicio).lte('salida', fechaFin);\n            }\n\n            // Advanced filter: price range\n            if (filtrosAvanzados.precioMin !== '') {\n                query = query.gte('precio', parseFloat(filtrosAvanzados.precioMin));\n            }\n            if (filtrosAvanzados.precioMax !== '') {\n                query = query.lte('precio', parseFloat(filtrosAvanzados.precioMax));\n            }\n\n            const { data, error } = await query;\n\n            if (error) {\n                console.warn('Error consultando Supabase, cargando datos demo:', error.message);\n                cargarDatosDemo();\n                return;\n            }\n\n            if (data && data.length > 0) {\n                // Transform Supabase response to the format expected by TarjetaViaje\n                let viajesTransformados = data.map(v => ({\n                    id: v.id,\n                    sucursal_nombre: v.buses.sucursales.nombre,\n                    ranking: v.buses.sucursales.ranking,\n                    origen: v.origen,\n                    destino: v.destino,\n                    salida: v.salida,\n                    precio: v.precio,\n                    duracion_estimada: v.duracion_estimada,\n                    amenidades: v.buses.sucursales.amenidades || [],\n                }));\n\n                // Client-side filter: minimum star rating\n                if (filtrosAvanzados.calidadMinima > 0) {\n                    viajesTransformados = viajesTransformados.filter(\n                        v => v.ranking >= filtrosAvanzados.calidadMinima\n                    );\n                }\n\n                // Client-side filter: amenities (must have ALL selected amenities)\n                if (filtrosAvanzados.amenidades.length > 0) {\n                    viajesTransformados = viajesTransformados.filter(v =>\n                        filtrosAvanzados.amenidades.every(a =>\n                            v.amenidades.includes(a)\n                        )\n                    );\n                }\n\n                setResultados(viajesTransformados);\n            } else {\n                cargarDatosDemo();\n            }\n        } catch (err) {\n            console.warn('Conexi√≥n a Supabase no disponible, cargando datos demo:', err);\n            cargarDatosDemo();\n        } finally {\n            setCargando(false);\n        }\n    };\n\n    /**\n     * Loads demo data filtered by selected origin, destination, and advanced filters.\n     * Fallback when Supabase is not available.\n     */\n    const cargarDatosDemo = () => {\n        let filtrados = DATOS_DEMO.filter(v =>\n            v.origen.toLowerCase() === origen.toLowerCase() &&\n            v.destino.toLowerCase() === destino.toLowerCase()\n        );\n\n        // Apply advanced filters to demo data as well\n        if (filtrosAvanzados.precioMin !== '') {\n            filtrados = filtrados.filter(v => v.precio >= parseFloat(filtrosAvanzados.precioMin));\n        }\n        if (filtrosAvanzados.precioMax !== '') {\n            filtrados = filtrados.filter(v => v.precio <= parseFloat(filtrosAvanzados.precioMax));\n        }\n        if (filtrosAvanzados.calidadMinima > 0) {\n            filtrados = filtrados.filter(v => v.ranking >= filtrosAvanzados.calidadMinima);\n        }\n        if (filtrosAvanzados.amenidades.length > 0) {\n            filtrados = filtrados.filter(v =>\n                filtrosAvanzados.amenidades.every(a => v.amenidades.includes(a))\n            );\n        }\n\n        setResultados(filtrados.length > 0 ? filtrados : DATOS_DEMO);\n        setCargando(false);\n    };\n\n    /**\n     * Lleva al usuario al Mapa de Asientos para continuar la reserva.\n     */\n    const handleSeleccionar = (viaje) => {\n        navigate('/reserva/' + viaje.id);\n    };\n\n\n\n    // Minimum date: today (don't allow past date search)\n    const fechaMinima = new Date().toISOString().split('T')[0];\n\n    return (\n        <div className=\"contenedor-buscador\">\n            {/* Header with back button */}\n            <div className=\"buscador-header\">\n                <button className=\"btn-volver\" onClick={() => navigate('/')} id=\"btn-volver\">\n                    ‚Üê Volver\n                </button>\n                <h1>Buscar Viajes</h1>\n                <p>Encuentra tu pr√≥ximo destino en Bolivia</p>\n            </div>\n\n            {/* Basic search form */}\n            <div className=\"buscador-filtros\" id=\"filtros-busqueda\">\n                <div className=\"filtro-grupo\">\n                    <label htmlFor=\"select-origen\">Origen</label>\n                    <select\n                        id=\"select-origen\"\n                        value={origen}\n                        onChange={(e) => setOrigen(e.target.value)}\n                        className=\"filtro-select\"\n                    >\n                        <option value=\"\">¬øDe d√≥nde sales?</option>\n                        {CIUDADES_BOLIVIA.map(ciudad => (\n                            <option key={ciudad} value={ciudad}>{ciudad}</option>\n                        ))}\n                    </select>\n                </div>\n\n                <div className=\"filtro-grupo\">\n                    <label htmlFor=\"select-destino\">Destino</label>\n                    <select\n                        id=\"select-destino\"\n                        value={destino}\n                        onChange={(e) => setDestino(e.target.value)}\n                        className=\"filtro-select\"\n                    >\n                        <option value=\"\">¬øA d√≥nde vas?</option>\n                        {CIUDADES_BOLIVIA.filter(c => c !== origen).map(ciudad => (\n                            <option key={ciudad} value={ciudad}>{ciudad}</option>\n                        ))}\n                    </select>\n                </div>\n\n                <div className=\"filtro-grupo\">\n                    <label htmlFor=\"input-fecha\">Fecha de viaje</label>\n                    <input\n                        type=\"date\"\n                        id=\"input-fecha\"\n                        value={fecha}\n                        onChange={(e) => setFecha(e.target.value)}\n                        min={fechaMinima}\n                        className=\"filtro-input\"\n                    />\n                </div>\n\n                <button\n                    className=\"btn-buscar\"\n                    onClick={buscarViajes}\n                    disabled={!origen || !destino || cargando}\n                    id=\"btn-buscar\"\n                >\n                    {cargando ? 'Buscando...' : 'üîç Buscar Viajes'}\n                </button>\n            </div>\n\n            {/* Advanced filter panel (global scope) */}\n            <PanelFiltros\n                filtros={filtrosAvanzados}\n                onFiltrosChange={setFiltrosAvanzados}\n                modoSucursal={false}\n                onBuscar={origen && destino ? buscarViajes : null}\n            />\n\n            {/* Results */}\n            <div className=\"buscador-resultados\" id=\"resultados-viajes\">\n                {cargando && (\n                    <div className=\"estado-carga\">\n                        <div className=\"spinner\"></div>\n                        <p>Buscando los mejores viajes para ti...</p>\n                    </div>\n                )}\n\n                {!cargando && buscado && resultados.length === 0 && (\n                    <div className=\"estado-vacio\">\n                        <span className=\"icono-vacio\">üöå</span>\n                        <h3>No encontramos viajes disponibles</h3>\n                        <p>Intenta con otra fecha, ruta o ajusta los filtros</p>\n                    </div>\n                )}\n\n                {!cargando && resultados.length > 0 && (\n                    <>\n                        <div className=\"resultados-info\">\n                            <p>{resultados.length} viaje{resultados.length !== 1 ? 's' : ''} encontrado{resultados.length !== 1 ? 's' : ''}</p>\n                        </div>\n                        <div className=\"lista-viajes\">\n                            {resultados.map(viaje => (\n                                <TarjetaViaje\n                                    key={viaje.id}\n                                    viaje={viaje}\n                                    onSeleccionar={handleSeleccionar}\n                                />\n                            ))}\n                        </div>\n                    </>\n                )}\n            </div>\n        </div>\n    );\n};\n\nexport default BuscadorViajes;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [['path', { d: 'm15 18-6-6 6-6', key: '1wnfg3' }]];\n\n/**\n * @component @name ChevronLeft\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/chevron-left\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst ChevronLeft = createLucideIcon('chevron-left', __iconNode);\n\nexport default ChevronLeft;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [['path', { d: 'm9 18 6-6-6-6', key: 'mthhwq' }]];\n\n/**\n * @component @name ChevronRight\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/chevron-right\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst ChevronRight = createLucideIcon('chevron-right', __iconNode);\n\nexport default ChevronRight;\n","import React, { useState, useEffect } from 'react';\nimport { useAuth } from '../contextos/AuthContext';\nimport { enviarFeedback, obtenerFeedback, obtenerLabelsPorMood } from '../data/mockDiscoveryDB';\n\n/**\n * FeedbackEmoji ‚Äî Marketplace-style emoji feedback system.\n * 5 mood levels with dynamic labels. Reviews show real name + generic avatar.\n * Props: sucursalId (string)\n */\nconst FeedbackEmoji = ({ sucursalId }) => {\n    const { perfil } = useAuth();\n    const [mood, setMood] = useState(0); // 0 = unselected, 1-5\n    const [labelsSeleccionados, setLabelsSeleccionados] = useState([]);\n    const [enviando, setEnviando] = useState(false);\n    const [enviado, setEnviado] = useState(false);\n    const [reviews, setReviews] = useState([]);\n\n    useEffect(() => {\n        setReviews(obtenerFeedback(sucursalId));\n    }, [sucursalId]);\n\n    const emojis = [\n        { valor: 1, emoji: 'üò°', label: 'Muy mal' },\n        { valor: 2, emoji: 'üòï', label: 'Mal' },\n        { valor: 3, emoji: 'üòê', label: 'Regular' },\n        { valor: 4, emoji: 'üôÇ', label: 'Bien' },\n        { valor: 5, emoji: 'üòÑ', label: 'Excelente' },\n    ];\n\n    const labels = mood > 0 ? obtenerLabelsPorMood(mood) : [];\n\n    const toggleLabel = (texto) => {\n        setLabelsSeleccionados(prev =>\n            prev.includes(texto) ? prev.filter(l => l !== texto) : [...prev, texto]\n        );\n    };\n\n    const handleSubmit = () => {\n        if (mood === 0) return;\n        setEnviando(true);\n\n        setTimeout(() => {\n            const nuevo = enviarFeedback({\n                sucursalId,\n                nombreUsuario: perfil?.nombre_completo || perfil?.nombreCompleto || perfil?.email || 'Viajero',\n                mood,\n                labelsSeleccionados,\n                comentario: '',\n            });\n\n            setReviews(prev => [nuevo, ...prev]);\n            setMood(0);\n            setLabelsSeleccionados([]);\n            setEnviando(false);\n            setEnviado(true);\n            setTimeout(() => setEnviado(false), 3000);\n        }, 400);\n    };\n\n    // Time ago helper\n    const tiempoRelativo = (fecha) => {\n        const diff = Date.now() - new Date(fecha).getTime();\n        const mins = Math.floor(diff / 60000);\n        if (mins < 1) return 'Justo ahora';\n        if (mins < 60) return `Hace ${mins} min`;\n        const hrs = Math.floor(mins / 60);\n        if (hrs < 24) return `Hace ${hrs}h`;\n        const dias = Math.floor(hrs / 24);\n        return `Hace ${dias}d`;\n    };\n\n    return (\n        <div style={{\n            background: '#1e293b', borderRadius: '14px', padding: '1.5rem',\n            border: '1px solid #334155', marginTop: '1.5rem',\n        }}>\n            <h3 style={{ margin: '0 0 0.25rem 0', fontSize: '1.1rem', color: '#f1f5f9' }}>\n                üí¨ Experiencias de Viajeros\n            </h3>\n            <p style={{ color: '#64748b', fontSize: '0.8rem', marginBottom: '1.25rem' }}>\n                ¬øC√≥mo fue tu viaje con esta empresa?\n            </p>\n\n            {/* Emoji Selector */}\n            <div style={{\n                display: 'flex', justifyContent: 'center', gap: '0.5rem', marginBottom: '1rem',\n            }}>\n                {emojis.map(e => (\n                    <button key={e.valor} onClick={() => { setMood(e.valor); setLabelsSeleccionados([]); }}\n                        style={{\n                            width: '52px', height: '52px', borderRadius: '12px',\n                            border: mood === e.valor ? '2px solid #3b82f6' : '1px solid #334155',\n                            background: mood === e.valor ? 'rgba(59,130,246,0.15)' : '#0f172a',\n                            cursor: 'pointer', fontSize: '1.6rem',\n                            display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',\n                            transition: 'all 0.2s', transform: mood === e.valor ? 'scale(1.1)' : 'scale(1)',\n                        }}>\n                        <span>{e.emoji}</span>\n                    </button>\n                ))}\n            </div>\n\n            {/* Selected mood label */}\n            {mood > 0 && (\n                <div style={{ textAlign: 'center', marginBottom: '1rem' }}>\n                    <span style={{\n                        color: mood <= 2 ? '#ef4444' : mood === 3 ? '#f59e0b' : '#10b981',\n                        fontSize: '0.85rem', fontWeight: 600,\n                    }}>\n                        {emojis.find(e => e.valor === mood)?.label}\n                    </span>\n                </div>\n            )}\n\n            {/* Dynamic Labels */}\n            {mood > 0 && labels.length > 0 && (\n                <div style={{ marginBottom: '1rem' }}>\n                    <p style={{ color: '#94a3b8', fontSize: '0.8rem', marginBottom: '0.5rem' }}>\n                        {mood <= 2 ? 'Puntos a mejorar:' : mood === 3 ? 'Aspectos regulares:' : 'Puntos fuertes:'}\n                    </p>\n                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>\n                        {labels.map(l => {\n                            const seleccionado = labelsSeleccionados.includes(l.texto);\n                            return (\n                                <button key={l.texto} onClick={() => toggleLabel(l.texto)}\n                                    style={{\n                                        padding: '0.45rem 0.85rem', borderRadius: '20px',\n                                        border: seleccionado ? '1px solid #3b82f6' : '1px solid #334155',\n                                        background: seleccionado ? 'rgba(59,130,246,0.2)' : '#0f172a',\n                                        color: seleccionado ? '#93c5fd' : '#94a3b8',\n                                        cursor: 'pointer', fontSize: '0.8rem',\n                                        transition: 'all 0.2s',\n                                    }}>\n                                    {l.emoji} {l.texto}\n                                </button>\n                            );\n                        })}\n                    </div>\n                </div>\n            )}\n\n            {/* Submit */}\n            {mood > 0 && labelsSeleccionados.length > 0 && (\n                <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '1.25rem' }}>\n                    <button onClick={handleSubmit} disabled={enviando}\n                        style={{\n                            padding: '0.7rem 2rem', background: '#3b82f6', color: 'white',\n                            border: 'none', borderRadius: '10px', fontWeight: 600, cursor: 'pointer',\n                            fontSize: '0.85rem',\n                        }}>\n                        {enviando ? 'Enviando...' : '‚úÖ Enviar Opini√≥n'}\n                    </button>\n                </div>\n            )}\n\n            {/* Success toast */}\n            {enviado && (\n                <div style={{\n                    background: 'rgba(16,185,129,0.1)', border: '1px solid #065f46',\n                    color: '#6ee7b7', padding: '0.6rem', borderRadius: '8px',\n                    fontSize: '0.85rem', textAlign: 'center', marginBottom: '1rem',\n                }}>\n                    ‚úÖ ¬°Gracias por tu opini√≥n!\n                </div>\n            )}\n\n            {/* Reviews List */}\n            {reviews.length > 0 && (\n                <div style={{ borderTop: '1px solid #334155', paddingTop: '1rem' }}>\n                    <p style={{ color: '#94a3b8', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 600 }}>\n                        {reviews.length} opini√≥n{reviews.length !== 1 ? 'es' : ''}\n                    </p>\n                    {reviews.slice(0, 5).map(r => (\n                        <div key={r.id} style={{\n                            display: 'flex', gap: '0.75rem', marginBottom: '0.75rem',\n                            padding: '0.75rem', background: '#0f172a', borderRadius: '10px',\n                        }}>\n                            {/* Generic avatar */}\n                            <div style={{\n                                width: '36px', height: '36px', borderRadius: '50%',\n                                background: '#1e293b', display: 'flex', alignItems: 'center', justifyContent: 'center',\n                                fontSize: '1.2rem', flexShrink: 0,\n                            }}>\n                                {r.avatarGenerico}\n                            </div>\n                            <div style={{ flex: 1, minWidth: 0 }}>\n                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.25rem' }}>\n                                    <span style={{ color: '#f1f5f9', fontSize: '0.85rem', fontWeight: 600 }}>{r.nombreUsuario}</span>\n                                    <span style={{ color: '#475569', fontSize: '0.7rem' }}>{tiempoRelativo(r.fecha)}</span>\n                                </div>\n                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', marginBottom: '0.3rem' }}>\n                                    <span style={{ fontSize: '1rem' }}>{emojis.find(e => e.valor === r.mood)?.emoji}</span>\n                                    {r.labelsSeleccionados.length > 0 && (\n                                        <span style={{ color: '#64748b', fontSize: '0.75rem' }}>\n                                            {r.labelsSeleccionados.join(' ¬∑ ')}\n                                        </span>\n                                    )}\n                                </div>\n\n                            </div>\n                        </div>\n                    ))}\n                    {reviews.length > 5 && (\n                        <p style={{ color: '#64748b', fontSize: '0.8rem', textAlign: 'center' }}>\n                            +{reviews.length - 5} opiniones m√°s\n                        </p>\n                    )}\n                </div>\n            )}\n        </div>\n    );\n};\n\nexport default FeedbackEmoji;\n","import React, { useState, useEffect } from 'react';\nimport { useParams, useNavigate } from 'react-router-dom';\nimport { Star, ChevronLeft, ChevronRight } from 'lucide-react';\nimport { obtenerSucursalPorId, obtenerViajesSucursal } from '../data/mockDiscoveryDB';\nimport FeedbackEmoji from '../componentes/FeedbackEmoji';\nimport TarjetaViaje from '../componentes/TarjetaViaje';\nimport PanelFiltros from '../componentes/PanelFiltros';\nimport '../estilos/escritorio/buscador.css';\nimport '../estilos/escritorio/filtros.css';\nimport '../estilos/movil/buscador-responsivo.css';\nimport '../estilos/movil/filtros-responsivo.css';\n\nconst VIAJES_POR_PAGINA = 4;\n\n/**\n * SucursalDetalle - V4: Branch detail with paginated trips and emoji feedback.\n * Uses mockDiscoveryDB for data. Pagination with Prev/Next buttons.\n * FeedbackEmoji section in footer for user reviews.\n */\nconst SucursalDetalle = () => {\n    const { id } = useParams();\n    const navigate = useNavigate();\n\n    const [sucursal, setSucursal] = useState(null);\n    const [cargandoSucursal, setCargandoSucursal] = useState(true);\n    const [viajesTotales, setViajesTotales] = useState([]);\n    const [viajesFiltrados, setViajesFiltrados] = useState([]);\n    const [paginaActual, setPaginaActual] = useState(1);\n\n    const [filtrosAvanzados, setFiltrosAvanzados] = useState({\n        precioMin: '',\n        precioMax: '',\n        calidadMinima: 0,\n        amenidades: [],\n    });\n\n    useEffect(() => {\n        cargarDatos();\n    }, [id]);\n\n    const cargarDatos = () => {\n        setCargandoSucursal(true);\n\n        // Load sucursal from mockDiscoveryDB\n        const suc = obtenerSucursalPorId(id);\n        if (suc) {\n            setSucursal(suc);\n        } else {\n            // Fallback for non-demo IDs\n            setSucursal({ id, nombre: 'Sucursal', ranking: 4.0, logoEmoji: 'üöå', colorAccent: '#3b82f6', amenidades: [] });\n        }\n\n        // Load trips\n        const trips = obtenerViajesSucursal(id).map(v => ({\n            ...v,\n            sucursal_nombre: suc?.nombre || 'Sucursal',\n            ranking: suc?.ranking || 4.0,\n            amenidades: suc?.amenidades || [],\n        }));\n        setViajesTotales(trips);\n        setViajesFiltrados(trips);\n        setCargandoSucursal(false);\n    };\n\n    // Apply filters + reset pagination\n    const aplicarFiltros = () => {\n        let filtrados = [...viajesTotales];\n\n        if (filtrosAvanzados.precioMin !== '') {\n            filtrados = filtrados.filter(v => v.precio >= parseFloat(filtrosAvanzados.precioMin));\n        }\n        if (filtrosAvanzados.precioMax !== '') {\n            filtrados = filtrados.filter(v => v.precio <= parseFloat(filtrosAvanzados.precioMax));\n        }\n        if (filtrosAvanzados.amenidades.length > 0) {\n            filtrados = filtrados.filter(v =>\n                filtrosAvanzados.amenidades.every(a => v.amenidades.includes(a))\n            );\n        }\n\n        setViajesFiltrados(filtrados);\n        setPaginaActual(1); // Reset to page 1 on filter change\n    };\n\n    // Pagination logic\n    const totalPaginas = Math.ceil(viajesFiltrados.length / VIAJES_POR_PAGINA);\n    const inicio = (paginaActual - 1) * VIAJES_POR_PAGINA;\n    const viajesPagina = viajesFiltrados.slice(inicio, inicio + VIAJES_POR_PAGINA);\n\n    const handleSeleccionar = (viaje) => {\n        navigate('/reserva/' + viaje.id);\n    };\n\n    // Star rendering with lucide-react\n    const renderEstrellas = (ranking) => {\n        const stars = [];\n        const num = parseFloat(ranking) || 0;\n        for (let i = 1; i <= 5; i++) {\n            if (i <= Math.floor(num)) {\n                stars.push(<Star key={i} size={16} fill=\"#f59e0b\" color=\"#f59e0b\" strokeWidth={1.5} />);\n            } else {\n                stars.push(<Star key={i} size={16} fill=\"none\" color=\"#475569\" strokeWidth={1.5} />);\n            }\n        }\n        return stars;\n    };\n\n    if (cargandoSucursal) {\n        return (\n            <div className=\"contenedor-buscador\">\n                <div className=\"estado-carga\">\n                    <div className=\"spinner\"></div>\n                    <p>Cargando informaci√≥n de la sucursal...</p>\n                </div>\n            </div>\n        );\n    }\n\n    return (\n        <div className=\"contenedor-buscador\">\n            {/* Header */}\n            <div className=\"buscador-header\">\n                <button className=\"btn-volver\" onClick={() => navigate(-1)} id=\"btn-volver-sucursal\">\n                    ‚Üê Volver\n                </button>\n                \n                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '0.5rem' }}>\n                    {sucursal?.logoEmoji && (\n                        <div style={{\n                            width: '48px', height: '48px', borderRadius: '12px',\n                            background: `${sucursal.colorAccent || '#3b82f6'}15`,\n                            border: `1px solid ${sucursal.colorAccent || '#3b82f6'}30`,\n                            display: 'flex', alignItems: 'center', justifyContent: 'center',\n                            fontSize: '1.5rem', flexShrink: 0,\n                        }}>\n                            {sucursal.logoEmoji}\n                        </div>\n                    )}\n                    <div>\n                        <h1 style={{ margin: 0, fontSize: '1.3rem' }}>{sucursal?.nombre || 'Sucursal'}</h1>\n                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', marginTop: '0.3rem' }}>\n                            {renderEstrellas(sucursal?.ranking)}\n                            <span style={{ color: '#94a3b8', fontSize: '0.85rem', marginLeft: '0.3rem' }}>\n                                ({sucursal?.ranking})\n                            </span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            {/* Filters */}\n            <PanelFiltros\n                filtros={filtrosAvanzados}\n                onFiltrosChange={setFiltrosAvanzados}\n                modoSucursal={true}\n                onBuscar={aplicarFiltros}\n            />\n\n            {/* Trip Results with Pagination */}\n            <div className=\"buscador-resultados\" id=\"resultados-sucursal\">\n                {viajesFiltrados.length === 0 ? (\n                    <div className=\"estado-vacio\">\n                        <span className=\"icono-vacio\">üöå</span>\n                        <h3>No hay viajes disponibles</h3>\n                        <p>Ajusta los filtros o vuelve m√°s tarde</p>\n                    </div>\n                ) : (\n                    <>\n                        <div className=\"resultados-info\" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>\n                            <p>\n                                {viajesFiltrados.length} viaje{viajesFiltrados.length !== 1 ? 's' : ''} de {sucursal?.nombre}\n                            </p>\n                            <span style={{ color: '#64748b', fontSize: '0.8rem' }}>\n                                P√°gina {paginaActual} de {totalPaginas}\n                            </span>\n                        </div>\n\n                        <div className=\"lista-viajes\">\n                            {viajesPagina.map(viaje => (\n                                <TarjetaViaje\n                                    key={viaje.id}\n                                    viaje={viaje}\n                                    onSeleccionar={handleSeleccionar}\n                                />\n                            ))}\n                        </div>\n\n                        {/* Pagination Controls */}\n                        {totalPaginas > 1 && (\n                            <div style={{\n                                display: 'flex', justifyContent: 'center', alignItems: 'center',\n                                gap: '1rem', marginTop: '1.5rem', paddingBottom: '0.5rem',\n                            }}>\n                                <button\n                                    onClick={() => setPaginaActual(p => Math.max(1, p - 1))}\n                                    disabled={paginaActual === 1}\n                                    style={{\n                                        display: 'flex', alignItems: 'center', gap: '0.3rem',\n                                        padding: '0.6rem 1.2rem', borderRadius: '10px',\n                                        background: paginaActual === 1 ? '#1e293b' : '#3b82f6',\n                                        color: paginaActual === 1 ? '#475569' : 'white',\n                                        border: '1px solid #334155',\n                                        cursor: paginaActual === 1 ? 'not-allowed' : 'pointer',\n                                        fontWeight: 600, fontSize: '0.85rem',\n                                    }}>\n                                    <ChevronLeft size={16} /> Anterior\n                                </button>\n\n                                {/* Page dots */}\n                                <div style={{ display: 'flex', gap: '0.4rem' }}>\n                                    {Array.from({ length: totalPaginas }, (_, i) => (\n                                        <button key={i} onClick={() => setPaginaActual(i + 1)}\n                                            style={{\n                                                width: '32px', height: '32px', borderRadius: '8px',\n                                                border: 'none', cursor: 'pointer',\n                                                background: paginaActual === i + 1 ? '#3b82f6' : '#1e293b',\n                                                color: paginaActual === i + 1 ? 'white' : '#64748b',\n                                                fontWeight: 600, fontSize: '0.85rem',\n                                            }}>\n                                            {i + 1}\n                                        </button>\n                                    ))}\n                                </div>\n\n                                <button\n                                    onClick={() => setPaginaActual(p => Math.min(totalPaginas, p + 1))}\n                                    disabled={paginaActual === totalPaginas}\n                                    style={{\n                                        display: 'flex', alignItems: 'center', gap: '0.3rem',\n                                        padding: '0.6rem 1.2rem', borderRadius: '10px',\n                                        background: paginaActual === totalPaginas ? '#1e293b' : '#3b82f6',\n                                        color: paginaActual === totalPaginas ? '#475569' : 'white',\n                                        border: '1px solid #334155',\n                                        cursor: paginaActual === totalPaginas ? 'not-allowed' : 'pointer',\n                                        fontWeight: 600, fontSize: '0.85rem',\n                                    }}>\n                                    Siguiente <ChevronRight size={16} />\n                                </button>\n                            </div>\n                        )}\n                    </>\n                )}\n            </div>\n\n            {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê Feedback Section ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n            <FeedbackEmoji sucursalId={id} />\n        </div>\n    );\n};\n\nexport default SucursalDetalle;\n","import React, { useState } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { useAuth } from '../../contextos/AuthContext';\nimport '../../estilos/escritorio/admin.css'; // Reutilizamos estilos form admin\n\nconst LoginAdmin = () => {\n    const [email, setEmail] = useState('');\n    const [password, setPassword] = useState('');\n    const [error, setError] = useState(null);\n    const [loading, setLoading] = useState(false);\n    \n    const { login } = useAuth();\n    const navigate = useNavigate();\n\n    const handleLogin = async (e) => {\n        e.preventDefault();\n        setError(null);\n        setLoading(true);\n\n        const { exito, error: loginError } = await login(email, password);\n        \n        if (exito) {\n            navigate('/admin/dashboard', { replace: true });\n        } else {\n            setError(loginError || 'Credenciales inv√°lidas. Por favor, intente de nuevo.');\n            setLoading(false);\n        }\n    };\n\n    return (\n        <div className=\"pagina-admin\" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' }}>\n            <div className=\"admin-contenido\" style={{ maxWidth: '400px', width: '100%', margin: '0 auto', boxShadow: '0 8px 32px rgba(0,0,0,0.5)' }}>\n                <div style={{ textAlign: 'center', marginBottom: '1.5rem' }}>\n                    <h1 style={{ fontSize: '1.5rem', marginBottom: '0.5rem', color: '#f1f5f9' }}>\n                        Acceso Staff\n                    </h1>\n                    <div className=\"admin-header-sub\" style={{ justifyContent: 'center' }}>\n                        Terminal de Buses Bolivia\n                    </div>\n                </div>\n\n                <form onSubmit={handleLogin} noValidate>\n                    {error && (\n                        <div className=\"admin-feedback error\" style={{ marginBottom: '1rem', padding: '0.75rem', borderRadius: '8px' }}>\n                            {error}\n                        </div>\n                    )}\n\n                    <div className=\"campo-grupo\">\n                        <label className=\"campo-label\">Correo Electr√≥nico</label>\n                        <input\n                            type=\"email\"\n                            className=\"campo-input\"\n                            value={email}\n                            onChange={(e) => setEmail(e.target.value)}\n                            placeholder=\"admin@tbb.com\"\n                            required\n                        />\n                    </div>\n\n                    <div className=\"campo-grupo\">\n                        <label className=\"campo-label\">Contrase√±a</label>\n                        <input\n                            type=\"password\"\n                            className=\"campo-input\"\n                            value={password}\n                            onChange={(e) => setPassword(e.target.value)}\n                            placeholder=\"‚Ä¢‚Ä¢‚Ä¢‚Ä¢‚Ä¢‚Ä¢‚Ä¢‚Ä¢\"\n                            required\n                        />\n                    </div>\n\n                    <button\n                        type=\"submit\"\n                        className=\"btn-admin-guardar\"\n                        style={{ width: '100%', marginTop: '1rem', padding: '0.8rem' }}\n                        disabled={loading || !email || !password}\n                    >\n                        {loading ? 'Verificando...' : 'Iniciar Sesi√≥n'}\n                    </button>\n                </form>\n\n                <div style={{ marginTop: '1.5rem', textAlign: 'center', fontSize: '0.8rem', color: '#64748b' }}>\n                    Solo personal autorizado. <br/>\n                    Si olvid√≥ su contrase√±a, contacte a TI.\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default LoginAdmin;\n","import React, { useState } from 'react';\nimport { useNavigate, Link } from 'react-router-dom';\nimport { useAuth } from '../../contextos/AuthContext';\nimport '../../estilos/escritorio/admin.css';\nimport '../../estilos/movil/admin-responsivo.css';\n\n/**\n * LoginCliente ‚Äî Dedicated client login page.\n * Authenticates via CI + Password against mockClientDB.\n */\nconst LoginCliente = () => {\n    const navigate = useNavigate();\n    const { loginComoCliente } = useAuth();\n\n    const [ci, setCi] = useState('');\n    const [password, setPassword] = useState('');\n    const [error, setError] = useState(null);\n    const [loading, setLoading] = useState(false);\n    const [mostrarPassword, setMostrarPassword] = useState(false);\n\n    const handleSubmit = async (e) => {\n        e.preventDefault();\n        setError(null);\n        setLoading(true);\n\n        const resultado = loginComoCliente(ci, password);\n\n        if (resultado.exito) {\n            navigate('/', { replace: true });\n        } else {\n            setError(resultado.error);\n            setLoading(false);\n        }\n    };\n\n    const inputStyle = {\n        width: '100%', boxSizing: 'border-box',\n        background: '#0f172a', border: '1px solid #334155', color: '#f1f5f9',\n        padding: '0.85rem', borderRadius: '10px', fontSize: '0.95rem',\n    };\n\n    return (\n        <div style={{ backgroundColor: '#0f172a', minHeight: '100vh', color: '#f1f5f9', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '1rem' }}>\n            <div style={{ width: '100%', maxWidth: '420px' }}>\n                {/* Header */}\n                <div style={{ textAlign: 'center', marginBottom: '2rem' }}>\n                    <div style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>üöå</div>\n                    <h1 style={{ fontSize: '1.4rem', marginBottom: '0.3rem' }}>Bienvenido de vuelta</h1>\n                    <p style={{ color: '#64748b', fontSize: '0.9rem' }}>Ingresa con tu CI para acceder a tu cuenta</p>\n                </div>\n\n                {/* Login Card */}\n                <div style={{\n                    background: '#1e293b', borderRadius: '16px', padding: '2rem',\n                    border: '1px solid #334155', boxShadow: '0 8px 32px rgba(0,0,0,0.4)',\n                }}>\n                    <form onSubmit={handleSubmit}>\n                        {error && (\n                            <div style={{\n                                background: 'rgba(239,68,68,0.1)', color: '#fca5a5',\n                                padding: '0.8rem', borderRadius: '8px',\n                                border: '1px solid #7f1d1d', fontSize: '0.85rem',\n                                marginBottom: '1.25rem',\n                            }}>\n                                ‚ùå {error}\n                            </div>\n                        )}\n\n                        {/* CI Input */}\n                        <div style={{ marginBottom: '1.25rem' }}>\n                            <label style={{ display: 'block', color: '#94a3b8', fontSize: '0.85rem', marginBottom: '0.4rem', fontWeight: 500 }}>\n                                Carnet de Identidad (CI)\n                            </label>\n                            <input type=\"text\" value={ci} onChange={e => setCi(e.target.value)}\n                                placeholder=\"Ej. 1234567\" required style={inputStyle}\n                            />\n                        </div>\n\n                        {/* Password Input */}\n                        <div style={{ marginBottom: '1.5rem' }}>\n                            <label style={{ display: 'block', color: '#94a3b8', fontSize: '0.85rem', marginBottom: '0.4rem', fontWeight: 500 }}>\n                                Contrase√±a\n                            </label>\n                            <div style={{ position: 'relative' }}>\n                                <input type={mostrarPassword ? 'text' : 'password'} value={password}\n                                    onChange={e => setPassword(e.target.value)}\n                                    placeholder=\"Tu contrase√±a\" required\n                                    style={{ ...inputStyle, paddingRight: '3rem' }}\n                                />\n                                <button type=\"button\" onClick={() => setMostrarPassword(!mostrarPassword)}\n                                    style={{\n                                        position: 'absolute', right: '0.5rem', top: '50%', transform: 'translateY(-50%)',\n                                        background: 'transparent', border: 'none', color: '#64748b',\n                                        cursor: 'pointer', fontSize: '1.1rem', padding: '0.5rem',\n                                    }}>\n                                    {mostrarPassword ? 'üôà' : 'üëÅÔ∏è'}\n                                </button>\n                            </div>\n                        </div>\n\n                        {/* Submit */}\n                        <button type=\"submit\" disabled={loading || !ci || !password}\n                            style={{\n                                width: '100%', padding: '0.9rem', border: 'none', borderRadius: '10px',\n                                background: (loading || !ci || !password) ? '#475569' : 'linear-gradient(135deg, #3b82f6, #2563eb)',\n                                color: 'white', fontWeight: 700, fontSize: '1rem',\n                                cursor: (loading || !ci || !password) ? 'not-allowed' : 'pointer',\n                                boxShadow: '0 4px 14px rgba(59,130,246,0.3)',\n                            }}>\n                            {loading ? 'Verificando...' : 'Iniciar Sesi√≥n'}\n                        </button>\n                    </form>\n                </div>\n\n                {/* Footer links */}\n                <div style={{ textAlign: 'center', marginTop: '1.5rem', fontSize: '0.9rem' }}>\n                    <span style={{ color: '#64748b' }}>¬øNo tienes cuenta? </span>\n                    <Link to=\"/registro\" style={{ color: '#60a5fa', textDecoration: 'none', fontWeight: 600 }}>\n                        Reg√≠strate aqu√≠\n                    </Link>\n                </div>\n                <div style={{ textAlign: 'center', marginTop: '0.75rem' }}>\n                    <Link to=\"/login\" style={{ color: '#475569', textDecoration: 'none', fontSize: '0.8rem' }}>\n                        Acceso Staff / Admin ‚Üí\n                    </Link>\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default LoginCliente;\n","import React, { useState, useCallback } from 'react';\nimport { useNavigate, Link } from 'react-router-dom';\nimport { registrarCliente, calcularEdad, esMayorDeEdad, existeCI } from '../../data/mockClientDB';\nimport '../../estilos/escritorio/admin.css';\nimport '../../estilos/movil/admin-responsivo.css';\n\n/**\n * RegistroCliente ‚Äî Client registration form with 18+ age validation,\n * CI document upload (front/back), and profile photo.\n */\nconst RegistroCliente = () => {\n    const navigate = useNavigate();\n\n    // Form fields\n    const [nombre, setNombre] = useState('');\n    const [ci, setCi] = useState('');\n    const [telefono, setTelefono] = useState('');\n    const [email, setEmail] = useState('');\n    const [password, setPassword] = useState('');\n    const [confirmPassword, setConfirmPassword] = useState('');\n    const [fechaNacimiento, setFechaNacimiento] = useState('');\n\n    // File uploads (base64)\n    const [fotoPerfil, setFotoPerfil] = useState(null);\n    const [fotoPerfilPreview, setFotoPerfilPreview] = useState(null);\n    const [ciAnverso, setCiAnverso] = useState(null);\n    const [ciAnversoPreview, setCiAnversoPreview] = useState(null);\n    const [ciReverso, setCiReverso] = useState(null);\n    const [ciReversoPreview, setCiReversoPreview] = useState(null);\n\n    // Validation states\n    const [ciValido, setCiValido] = useState(null); // null = unchecked, true, false\n    const [edadValida, setEdadValida] = useState(null);\n    const [edadCalculada, setEdadCalculada] = useState(null);\n\n    // UI states\n    const [cargando, setCargando] = useState(false);\n    const [toast, setToast] = useState(null); // { tipo: 'exito' | 'error', texto }\n    const [mostrarPassword, setMostrarPassword] = useState(false);\n\n    // Show toast for a few seconds\n    const mostrarToast = useCallback((tipo, texto) => {\n        setToast({ tipo, texto });\n        setTimeout(() => setToast(null), 5000);\n    }, []);\n\n    // Handle file to base64\n    const handleFileToBase64 = (file, setBase64, setPreview) => {\n        if (!file) return;\n        if (file.size > 5 * 1024 * 1024) {\n            mostrarToast('error', 'El archivo es demasiado grande (m√°x. 5MB).');\n            return;\n        }\n        const reader = new FileReader();\n        reader.onload = () => {\n            setBase64(reader.result);\n            setPreview(reader.result);\n        };\n        reader.readAsDataURL(file);\n    };\n\n    // Validate CI uniqueness on blur\n    const handleCiBlur = () => {\n        if (ci.length >= 5) {\n            setCiValido(!existeCI(ci));\n        } else {\n            setCiValido(null);\n        }\n    };\n\n    // Validate age on date change\n    const handleFechaNacimientoChange = (value) => {\n        setFechaNacimiento(value);\n        if (value) {\n            const edad = calcularEdad(value);\n            setEdadCalculada(edad);\n            setEdadValida(esMayorDeEdad(value));\n        } else {\n            setEdadCalculada(null);\n            setEdadValida(null);\n        }\n    };\n\n    // Submit\n    const handleSubmit = (e) => {\n        e.preventDefault();\n\n        // Frontend validations\n        if (!nombre || !ci || !password || !fechaNacimiento) {\n            mostrarToast('error', 'Complete todos los campos obligatorios.');\n            return;\n        }\n        if (password !== confirmPassword) {\n            mostrarToast('error', 'Las contrase√±as no coinciden.');\n            return;\n        }\n        if (password.length < 6) {\n            mostrarToast('error', 'La contrase√±a debe tener al menos 6 caracteres.');\n            return;\n        }\n        if (edadValida === false) {\n            mostrarToast('error', 'Debe ser mayor de 18 a√±os para registrarse.');\n            return;\n        }\n        if (ciValido === false) {\n            mostrarToast('error', 'Este CI ya est√° registrado.');\n            return;\n        }\n\n        setCargando(true);\n\n        // Simulate async (300ms)\n        setTimeout(() => {\n            const resultado = registrarCliente({\n                nombreCompleto: nombre,\n                ci,\n                telefono,\n                email,\n                password,\n                fechaNacimiento,\n                fotoPerfil: fotoPerfil,\n                ciAnverso: ciAnverso,\n                ciReverso: ciReverso,\n            });\n\n            if (resultado.exito) {\n                mostrarToast('exito', '¬°Registro exitoso! Redirigiendo al login...');\n                setTimeout(() => navigate('/login-cliente'), 2000);\n            } else {\n                mostrarToast('error', resultado.error);\n            }\n            setCargando(false);\n        }, 300);\n    };\n\n    // Max date for birth (today)\n    const hoy = new Date().toISOString().split('T')[0];\n\n    // Shared input styles\n    const inputStyle = {\n        width: '100%', boxSizing: 'border-box',\n        background: '#0f172a', border: '1px solid #334155', color: '#f1f5f9',\n        padding: '0.85rem', borderRadius: '10px', fontSize: '0.95rem',\n        transition: 'border-color 0.2s',\n    };\n\n    const labelStyle = {\n        display: 'block', color: '#94a3b8', fontSize: '0.85rem',\n        marginBottom: '0.4rem', fontWeight: 500,\n    };\n\n    return (\n        <div style={{ backgroundColor: '#0f172a', minHeight: '100vh', color: '#f1f5f9' }}>\n            {/* Toast Notification */}\n            {toast && (\n                <div style={{\n                    position: 'fixed', top: '1rem', left: '50%', transform: 'translateX(-50%)',\n                    zIndex: 100, padding: '0.9rem 1.5rem', borderRadius: '10px',\n                    background: toast.tipo === 'exito' ? '#065f46' : '#7f1d1d',\n                    color: toast.tipo === 'exito' ? '#6ee7b7' : '#fca5a5',\n                    border: `1px solid ${toast.tipo === 'exito' ? '#10b981' : '#ef4444'}`,\n                    boxShadow: '0 10px 25px rgba(0,0,0,0.4)',\n                    fontSize: '0.9rem', fontWeight: 500, maxWidth: '90%',\n                    animation: 'fadeIn 0.3s ease',\n                }}>\n                    {toast.tipo === 'exito' ? '‚úÖ' : '‚ùå'} {toast.texto}\n                </div>\n            )}\n\n            <div style={{ maxWidth: '560px', margin: '0 auto', padding: '1.5rem 1rem 3rem' }}>\n                \n                {/* Header */}\n                <div style={{ textAlign: 'center', marginBottom: '2rem', paddingTop: '1rem' }}>\n                    <div style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>ü™™</div>\n                    <h1 style={{ fontSize: '1.5rem', marginBottom: '0.3rem', color: '#f1f5f9' }}>Crear tu Cuenta</h1>\n                    <p style={{ color: '#64748b', fontSize: '0.9rem' }}>\n                        Reg√≠strate para reservar tus viajes en l√≠nea\n                    </p>\n                </div>\n\n                <form onSubmit={handleSubmit}>\n                    {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê SECTION: Personal Data ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                    <div style={{\n                        background: '#1e293b', borderRadius: '14px', padding: '1.5rem',\n                        border: '1px solid #334155', marginBottom: '1.25rem',\n                    }}>\n                        <div style={{ fontSize: '0.9rem', fontWeight: 600, color: '#60a5fa', marginBottom: '1.25rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>\n                            <span>üë§</span> Datos Personales\n                        </div>\n\n                        {/* Nombre */}\n                        <div style={{ marginBottom: '1rem' }}>\n                            <label style={labelStyle}>Nombre Completo <span style={{ color: '#ef4444' }}>*</span></label>\n                            <input type=\"text\" value={nombre} onChange={e => setNombre(e.target.value)}\n                                placeholder=\"Ej. Juan Carlos P√©rez Mamani\" required style={inputStyle} />\n                        </div>\n\n                        {/* CI + validation */}\n                        <div style={{ marginBottom: '1rem' }}>\n                            <label style={labelStyle}>Carnet de Identidad (CI) <span style={{ color: '#ef4444' }}>*</span></label>\n                            <input type=\"text\" value={ci}\n                                onChange={e => { setCi(e.target.value); setCiValido(null); }}\n                                onBlur={handleCiBlur}\n                                placeholder=\"Ej. 1234567\" required\n                                style={{\n                                    ...inputStyle,\n                                    borderColor: ciValido === true ? '#10b981' : ciValido === false ? '#ef4444' : '#334155',\n                                }}\n                            />\n                            {ciValido === false && (\n                                <span style={{ color: '#ef4444', fontSize: '0.8rem', marginTop: '0.3rem', display: 'block' }}>\n                                    ‚ùå Este CI ya est√° registrado.\n                                </span>\n                            )}\n                            {ciValido === true && (\n                                <span style={{ color: '#10b981', fontSize: '0.8rem', marginTop: '0.3rem', display: 'block' }}>\n                                    ‚úÖ CI disponible\n                                </span>\n                            )}\n                        </div>\n\n                        {/* Fecha de Nacimiento + Age Validation */}\n                        <div style={{ marginBottom: '1rem' }}>\n                            <label style={labelStyle}>Fecha de Nacimiento <span style={{ color: '#ef4444' }}>*</span></label>\n                            <input type=\"date\" value={fechaNacimiento}\n                                onChange={e => handleFechaNacimientoChange(e.target.value)}\n                                max={hoy} required\n                                style={{\n                                    ...inputStyle,\n                                    borderColor: edadValida === true ? '#10b981' : edadValida === false ? '#ef4444' : '#334155',\n                                }}\n                            />\n                            {edadCalculada !== null && edadValida === true && (\n                                <span style={{ color: '#10b981', fontSize: '0.8rem', marginTop: '0.3rem', display: 'block' }}>\n                                    ‚úÖ Edad: {edadCalculada} a√±os\n                                </span>\n                            )}\n                            {edadValida === false && (\n                                <div style={{\n                                    marginTop: '0.5rem', padding: '0.75rem', borderRadius: '8px',\n                                    background: 'rgba(239, 68, 68, 0.1)', border: '1px solid #7f1d1d',\n                                }}>\n                                    <span style={{ color: '#fca5a5', fontSize: '0.85rem', fontWeight: 500 }}>\n                                        üö´ Lo sentimos, debes ser mayor de 18 a√±os para registrarte en la plataforma.\n                                        {edadCalculada !== null && ` Edad actual: ${edadCalculada} a√±os.`}\n                                    </span>\n                                </div>\n                            )}\n                        </div>\n\n                        {/* Tel√©fono */}\n                        <div style={{ marginBottom: '1rem' }}>\n                            <label style={labelStyle}>Tel√©fono</label>\n                            <input type=\"tel\" value={telefono} onChange={e => setTelefono(e.target.value)}\n                                placeholder=\"Ej. 77012345\" style={inputStyle} />\n                        </div>\n\n                        {/* Email */}\n                        <div>\n                            <label style={labelStyle}>Email <span style={{ color: '#64748b', fontWeight: 400 }}>(opcional)</span></label>\n                            <input type=\"email\" value={email} onChange={e => setEmail(e.target.value)}\n                                placeholder=\"correo@ejemplo.com\" style={inputStyle} />\n                        </div>\n                    </div>\n\n                    {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê SECTION: Security ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                    <div style={{\n                        background: '#1e293b', borderRadius: '14px', padding: '1.5rem',\n                        border: '1px solid #334155', marginBottom: '1.25rem',\n                    }}>\n                        <div style={{ fontSize: '0.9rem', fontWeight: 600, color: '#60a5fa', marginBottom: '1.25rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>\n                            <span>üîí</span> Seguridad\n                        </div>\n\n                        <div style={{ marginBottom: '1rem' }}>\n                            <label style={labelStyle}>Contrase√±a <span style={{ color: '#ef4444' }}>*</span></label>\n                            <div style={{ position: 'relative' }}>\n                                <input type={mostrarPassword ? 'text' : 'password'} value={password}\n                                    onChange={e => setPassword(e.target.value)}\n                                    placeholder=\"M√≠nimo 6 caracteres\" required minLength={6}\n                                    style={{ ...inputStyle, paddingRight: '3rem' }}\n                                />\n                                <button type=\"button\" onClick={() => setMostrarPassword(!mostrarPassword)}\n                                    style={{\n                                        position: 'absolute', right: '0.5rem', top: '50%', transform: 'translateY(-50%)',\n                                        background: 'transparent', border: 'none', color: '#64748b',\n                                        cursor: 'pointer', fontSize: '1.1rem', padding: '0.5rem',\n                                    }}>\n                                    {mostrarPassword ? 'üôà' : 'üëÅÔ∏è'}\n                                </button>\n                            </div>\n                        </div>\n\n                        <div>\n                            <label style={labelStyle}>Confirmar Contrase√±a <span style={{ color: '#ef4444' }}>*</span></label>\n                            <input type=\"password\" value={confirmPassword}\n                                onChange={e => setConfirmPassword(e.target.value)}\n                                placeholder=\"Repite tu contrase√±a\" required\n                                style={{\n                                    ...inputStyle,\n                                    borderColor: confirmPassword && password !== confirmPassword ? '#ef4444'\n                                        : confirmPassword && password === confirmPassword ? '#10b981' : '#334155',\n                                }}\n                            />\n                            {confirmPassword && password !== confirmPassword && (\n                                <span style={{ color: '#ef4444', fontSize: '0.8rem', display: 'block', marginTop: '0.3rem' }}>\n                                    Las contrase√±as no coinciden.\n                                </span>\n                            )}\n                        </div>\n                    </div>\n\n                    {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê SECTION: Profile Photo ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                    <div style={{\n                        background: '#1e293b', borderRadius: '14px', padding: '1.5rem',\n                        border: '1px solid #334155', marginBottom: '1.25rem',\n                    }}>\n                        <div style={{ fontSize: '0.9rem', fontWeight: 600, color: '#60a5fa', marginBottom: '1.25rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>\n                            <span>üì∑</span> Foto de Perfil\n                        </div>\n\n                        <div style={{ display: 'flex', alignItems: 'center', gap: '1.25rem' }}>\n                            <div style={{\n                                width: '90px', height: '90px', borderRadius: '50%',\n                                background: '#0f172a', border: '2px dashed #475569',\n                                overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center',\n                                flexShrink: 0,\n                            }}>\n                                {fotoPerfilPreview ? (\n                                    <img src={fotoPerfilPreview} alt=\"Perfil\" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />\n                                ) : (\n                                    <span style={{ fontSize: '2.2rem', color: '#475569' }}>üë§</span>\n                                )}\n                            </div>\n                            <div>\n                                <label style={{\n                                    display: 'inline-block', padding: '0.6rem 1.2rem', borderRadius: '8px',\n                                    background: 'rgba(59,130,246,0.15)', border: '1px solid #334155',\n                                    color: '#60a5fa', cursor: 'pointer', fontSize: '0.85rem', fontWeight: 500,\n                                }}>\n                                    Seleccionar foto\n                                    <input type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden\n                                        onChange={e => handleFileToBase64(e.target.files[0], setFotoPerfil, setFotoPerfilPreview)}\n                                    />\n                                </label>\n                                <div style={{ color: '#475569', fontSize: '0.75rem', marginTop: '0.4rem' }}>JPG, PNG o WebP. M√°x 5MB.</div>\n                            </div>\n                        </div>\n                    </div>\n\n                    {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê SECTION: CI Documents ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                    <div style={{\n                        background: '#1e293b', borderRadius: '14px', padding: '1.5rem',\n                        border: '1px solid #334155', marginBottom: '1.5rem',\n                    }}>\n                        <div style={{ fontSize: '0.9rem', fontWeight: 600, color: '#60a5fa', marginBottom: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>\n                            <span>ü™™</span> Documentos de Identidad\n                        </div>\n                        <p style={{ color: '#64748b', fontSize: '0.8rem', marginBottom: '1.25rem' }}>\n                            Sube fotograf√≠as claras del anverso y reverso de tu CI. Esto garantiza la seguridad de tu cuenta.\n                        </p>\n\n                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>\n                            {/* CI Anverso */}\n                            <div>\n                                <label style={{ ...labelStyle, textAlign: 'center' }}>CI Anverso</label>\n                                <label style={{\n                                    display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',\n                                    width: '100%', height: '120px', borderRadius: '10px', cursor: 'pointer',\n                                    background: '#0f172a', border: `2px dashed ${ciAnversoPreview ? '#10b981' : '#475569'}`,\n                                    overflow: 'hidden', transition: 'border-color 0.2s',\n                                }}>\n                                    {ciAnversoPreview ? (\n                                        <img src={ciAnversoPreview} alt=\"CI Anverso\" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />\n                                    ) : (\n                                        <>\n                                            <span style={{ fontSize: '1.8rem', color: '#475569' }}>üìÑ</span>\n                                            <span style={{ fontSize: '0.7rem', color: '#475569', marginTop: '0.3rem' }}>Toca para subir</span>\n                                        </>\n                                    )}\n                                    <input type=\"file\" accept=\"image/*\" hidden\n                                        onChange={e => handleFileToBase64(e.target.files[0], setCiAnverso, setCiAnversoPreview)}\n                                    />\n                                </label>\n                            </div>\n\n                            {/* CI Reverso */}\n                            <div>\n                                <label style={{ ...labelStyle, textAlign: 'center' }}>CI Reverso</label>\n                                <label style={{\n                                    display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',\n                                    width: '100%', height: '120px', borderRadius: '10px', cursor: 'pointer',\n                                    background: '#0f172a', border: `2px dashed ${ciReversoPreview ? '#10b981' : '#475569'}`,\n                                    overflow: 'hidden', transition: 'border-color 0.2s',\n                                }}>\n                                    {ciReversoPreview ? (\n                                        <img src={ciReversoPreview} alt=\"CI Reverso\" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />\n                                    ) : (\n                                        <>\n                                            <span style={{ fontSize: '1.8rem', color: '#475569' }}>üìÑ</span>\n                                            <span style={{ fontSize: '0.7rem', color: '#475569', marginTop: '0.3rem' }}>Toca para subir</span>\n                                        </>\n                                    )}\n                                    <input type=\"file\" accept=\"image/*\" hidden\n                                        onChange={e => handleFileToBase64(e.target.files[0], setCiReverso, setCiReversoPreview)}\n                                    />\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n\n                    {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê SUBMIT ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                    <button type=\"submit\" disabled={cargando || edadValida === false || ciValido === false}\n                        style={{\n                            width: '100%', padding: '1rem', border: 'none', borderRadius: '12px',\n                            background: (cargando || edadValida === false || ciValido === false) ? '#475569' : 'linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)',\n                            color: 'white', fontWeight: 700, fontSize: '1rem',\n                            cursor: (cargando || edadValida === false || ciValido === false) ? 'not-allowed' : 'pointer',\n                            boxShadow: '0 4px 14px rgba(59,130,246,0.3)',\n                            transition: 'all 0.2s',\n                        }}>\n                        {cargando ? 'Registrando...' : 'Crear Mi Cuenta'}\n                    </button>\n\n                    {/* Link to login */}\n                    <div style={{ textAlign: 'center', marginTop: '1.5rem', fontSize: '0.9rem', color: '#94a3b8' }}>\n                        ¬øYa tienes cuenta?{' '}\n                        <Link to=\"/login-cliente\" style={{ color: '#60a5fa', textDecoration: 'none', fontWeight: 600 }}>\n                            Inicia Sesi√≥n\n                        </Link>\n                    </div>\n                </form>\n            </div>\n        </div>\n    );\n};\n\nexport default RegistroCliente;\n","import React, { useEffect, useState } from 'react';\nimport { Link, useNavigate } from 'react-router-dom';\nimport { supabase } from '../../servicios/supabase';\nimport { useAuth } from '../../contextos/AuthContext';\nimport '../../estilos/escritorio/admin.css';\nimport '../../estilos/movil/admin-responsivo.css';\n\nconst AdminDashboard = () => {\n    const { perfil, logout } = useAuth();\n    const navigate = useNavigate();\n\n    const [stats, setStats] = useState({ buses: 0, tripulacion: 0 });\n    const [busesRecientes, setBusesRecientes] = useState([]);\n    const [cargando, setCargando] = useState(true);\n\n    useEffect(() => {\n        const fetchDatos = async () => {\n            setCargando(true);\n            try {\n                // Total buses\n                const { count: countBuses } = await supabase\n                    .from('buses')\n                    .select('*', { count: 'exact', head: true });\n\n                // Total tripulaci√≥n\n                const { count: countTripulacion } = await supabase\n                    .from('tripulacion')\n                    .select('*', { count: 'exact', head: true });\n\n                // √öltimos 5 buses con nombre sucursal\n                const { data: listaBuses } = await supabase\n                    .from('buses')\n                    .select(`\n                        id, placa, capacidad, pisos, estado,\n                        sucursales ( nombre )\n                    `)\n                    .order('placa', { ascending: false })\n                    .limit(5);\n\n                setStats({\n                    buses: countBuses || 0,\n                    tripulacion: countTripulacion || 0\n                });\n\n                if (listaBuses) setBusesRecientes(listaBuses);\n\n            } catch (err) {\n                console.error(\"Dashboard Fetch Error:\", err);\n            } finally {\n                setCargando(false);\n            }\n        };\n\n        fetchDatos();\n    }, []);\n\n    const handleLogout = async () => {\n        await logout();\n        navigate('/');\n    };\n\n    return (\n        <div className=\"pagina-admin\" style={{ display: 'flex', minHeight: '100vh', flexDirection: 'column' }}>\n            {/* ‚îÄ‚îÄ HEADER SUPERIOR DEDICADO ‚îÄ‚îÄ */}\n            <header className=\"admin-header\" style={{ position: 'sticky', top: 0, zIndex: 10 }}>\n                <div style={{ flex: 1 }}>\n                    <h1 style={{ margin: 0 }}>Terminal Dashboard</h1>\n                    <div className=\"admin-header-sub\">Gesti√≥n Centralizada</div>\n                </div>\n                \n                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>\n                    <div style={{ textAlign: 'right', display: 'flex', flexDirection: 'column' }}>\n                        <span style={{ fontSize: '0.85rem', color: '#f1f5f9', fontWeight: 600 }}>{perfil?.nombre_completo || perfil?.email}</span>\n                        <span style={{ fontSize: '0.7rem', color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.05em' }}>\n                            {perfil?.rol?.replace('_', ' ')}\n                        </span>\n                    </div>\n                    <button onClick={handleLogout} className=\"btn-volver-admin\" style={{ padding: '0.4rem 0.8rem', background: '#334155' }}>\n                        Salir üö™\n                    </button>\n                </div>\n            </header>\n\n            <div style={{ display: 'flex', flex: 1, backgroundColor: '#0f172a' }}>\n                {/* ‚îÄ‚îÄ SIDEBAR DESKTOP / NAVBAR M√ìVIL ‚îÄ‚îÄ */}\n                <aside className=\"admin-sidebar\" style={{ \n                    width: '240px', \n                    background: '#162032', \n                    borderRight: '1px solid #1e293b', \n                    padding: '1.5rem', \n                    display: 'flex', \n                    flexDirection: 'column', \n                    gap: '0.5rem' \n                }}>\n                    <div className=\"admin-seccion-titulo\" style={{ marginBottom: '1rem', color: '#475569' }}>Acciones R√°pidas</div>\n                    \n                    <Link to=\"/admin/bus/nuevo\" style={{ textDecoration: 'none' }}>\n                        <div className=\"toggle-btn\" style={{ justifyContent: 'flex-start', border: '1px solid #334155' }}>\n                            üöå Registrar Bus\n                        </div>\n                    </Link>\n                    \n                    <Link to=\"/admin/tripulacion/nuevo\" style={{ textDecoration: 'none' }}>\n                        <div className=\"toggle-btn\" style={{ justifyContent: 'flex-start', border: '1px solid #334155' }}>\n                            üßç Registrar Tripulaci√≥n\n                        </div>\n                    </Link>\n                </aside>\n\n                {/* ‚îÄ‚îÄ AREA PRINCIPAL ‚îÄ‚îÄ */}\n                <main style={{ flex: 1, padding: '2rem' }}>\n                    {cargando ? (\n                        <div style={{ color: '#64748b' }}>Cargando resumen...</div>\n                    ) : (\n                        <>\n                            {/* KPI Metrics */}\n                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.5rem', marginBottom: '2rem' }}>\n                                <div className=\"admin-seccion\" style={{ margin: 0, padding: '1.5rem', textAlign: 'center' }}>\n                                    <div style={{ fontSize: '2.5rem', color: '#3b82f6', fontWeight: 700, lineHeight: 1 }}>{stats.buses}</div>\n                                    <div style={{ color: '#94a3b8', fontSize: '0.85rem', marginTop: '0.5rem' }}>Buses Registrados</div>\n                                </div>\n                                <div className=\"admin-seccion\" style={{ margin: 0, padding: '1.5rem', textAlign: 'center' }}>\n                                    <div style={{ fontSize: '2.5rem', color: '#22c55e', fontWeight: 700, lineHeight: 1 }}>{stats.tripulacion}</div>\n                                    <div style={{ color: '#94a3b8', fontSize: '0.85rem', marginTop: '0.5rem' }}>Tripulantes Activos</div>\n                                </div>\n                            </div>\n\n                            {/* Data Table Preview */}\n                            <div className=\"admin-seccion\">\n                                <div className=\"admin-seccion-titulo\">\n                                    <span className=\"seccion-icono\">üìä</span> Flota Reciente\n                                </div>\n                                <div className=\"admin-seccion-cuerpo\" style={{ overflowX: 'auto' }}>\n                                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem', color: '#f1f5f9' }}>\n                                        <thead>\n                                            <tr style={{ borderBottom: '2px solid #1e293b', textAlign: 'left', color: '#64748b' }}>\n                                                <th style={{ padding: '0.8rem 0.5rem' }}>ID Placa</th>\n                                                <th style={{ padding: '0.8rem 0.5rem' }}>Empresa</th>\n                                                <th style={{ padding: '0.8rem 0.5rem' }}>Config</th>\n                                                <th style={{ padding: '0.8rem 0.5rem' }}>Capacidad</th>\n                                                <th style={{ padding: '0.8rem 0.5rem' }}>Estado</th>\n                                            </tr>\n                                        </thead>\n                                        <tbody>\n                                            {busesRecientes.length === 0 ? (\n                                                <tr><td colSpan=\"5\" style={{ padding: '1rem', textAlign: 'center', color: '#64748b' }}>No hay buses registrados.</td></tr>\n                                            ) : (\n                                                busesRecientes.map(bus => (\n                                                    <tr key={bus.id} style={{ borderBottom: '1px solid #1e293b' }}>\n                                                        <td style={{ padding: '0.8rem 0.5rem', fontWeight: 600 }}>{bus.placa}</td>\n                                                        <td style={{ padding: '0.8rem 0.5rem' }}>{bus.sucursales?.nombre || 'Independiente'}</td>\n                                                        <td style={{ padding: '0.8rem 0.5rem' }}>{bus.pisos} Piso{bus.pisos>1?'s':''}</td>\n                                                        <td style={{ padding: '0.8rem 0.5rem' }}>{bus.capacidad} Asientos</td>\n                                                        <td style={{ padding: '0.8rem 0.5rem' }}>\n                                                            <span style={{ \n                                                                background: bus.estado === 'disponible' ? '#064e3b' : '#7f1d1d',\n                                                                color: bus.estado === 'disponible' ? '#34d399' : '#fca5a5',\n                                                                padding: '0.2rem 0.5rem',\n                                                                borderRadius: '4px',\n                                                                fontSize: '0.75rem',\n                                                                textTransform: 'uppercase'\n                                                            }}>\n                                                                {bus.estado}\n                                                            </span>\n                                                        </td>\n                                                    </tr>\n                                                ))\n                                            )}\n                                        </tbody>\n                                    </table>\n                                </div>\n                            </div>\n                        </>\n                    )}\n                </main>\n            </div>\n            \n            {/* CSS Patch Inline for Mobile Sidebar hiding behavior if needed */}\n            <style>{`\n                @media (max-width: 768px) {\n                    .admin-sidebar {\n                        width: 100% !important;\n                        border-right: none !important;\n                        border-bottom: 1px solid #1e293b;\n                        padding: 1rem !important;\n                        flex-direction: row !important;\n                        flex-wrap: wrap;\n                    }\n                    .admin-sidebar > a { flex: 1; min-width: 140px; }\n                }\n            `}</style>\n        </div>\n    );\n};\n\nexport default AdminDashboard;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  [\n    'path',\n    {\n      d: 'M22 12h-2.48a2 2 0 0 0-1.93 1.46l-2.35 8.36a.25.25 0 0 1-.48 0L9.24 2.18a.25.25 0 0 0-.48 0l-2.35 8.36A2 2 0 0 1 4.49 12H2',\n      key: '169zse',\n    },\n  ],\n];\n\n/**\n * @component @name Activity\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/activity\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Activity = createLucideIcon('activity', __iconNode);\n\nexport default Activity;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M16 7h6v6', key: 'box55l' }],\n  ['path', { d: 'm22 7-8.5 8.5-5-5L2 17', key: '1t1m79' }],\n];\n\n/**\n * @component @name TrendingUp\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/trending-up\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst TrendingUp = createLucideIcon('trending-up', __iconNode);\n\nexport default TrendingUp;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2', key: '1yyitq' }],\n  ['path', { d: 'M16 3.128a4 4 0 0 1 0 7.744', key: '16gr8j' }],\n  ['path', { d: 'M22 21v-2a4 4 0 0 0-3-3.87', key: 'kshegd' }],\n  ['circle', { cx: '9', cy: '7', r: '4', key: 'nufk8' }],\n];\n\n/**\n * @component @name Users\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/users\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Users = createLucideIcon('users', __iconNode);\n\nexport default Users;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  [\n    'path',\n    {\n      d: 'M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0',\n      key: '1r0f0z',\n    },\n  ],\n  ['circle', { cx: '12', cy: '10', r: '3', key: 'ilqhr7' }],\n];\n\n/**\n * @component @name MapPin\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/map-pin\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst MapPin = createLucideIcon('map-pin', __iconNode);\n\nexport default MapPin;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M8 6v6', key: '18i7km' }],\n  ['path', { d: 'M15 6v6', key: '1sg6z9' }],\n  ['path', { d: 'M2 12h19.6', key: 'de5uta' }],\n  [\n    'path',\n    {\n      d: 'M18 18h3s.5-1.7.8-2.8c.1-.4.2-.8.2-1.2 0-.4-.1-.8-.2-1.2l-1.4-5C20.1 6.8 19.1 6 18 6H4a2 2 0 0 0-2 2v10h3',\n      key: '1wwztk',\n    },\n  ],\n  ['circle', { cx: '7', cy: '18', r: '2', key: '19iecd' }],\n  ['path', { d: 'M9 18h5', key: 'lrx6i' }],\n  ['circle', { cx: '16', cy: '18', r: '2', key: '1v4tcr' }],\n];\n\n/**\n * @component @name Bus\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/bus\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Bus = createLucideIcon('bus', __iconNode);\n\nexport default Bus;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M3 3v16a2 2 0 0 0 2 2h16', key: 'c24i48' }],\n  ['path', { d: 'M18 17V9', key: '2bz60n' }],\n  ['path', { d: 'M13 17V5', key: '1frdt8' }],\n  ['path', { d: 'M8 17v-3', key: '17ska0' }],\n];\n\n/**\n * @component @name ChartColumn\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/chart-column\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst ChartColumn = createLucideIcon('chart-column', __iconNode);\n\nexport default ChartColumn;\n","/**\n * mockAnalyticsDB.js\n * Analytics data layer for the Terminal Management Dashboard (V4 Branch 4).\n * Aggregates traffic, revenue, and occupancy data from existing mock stores.\n */\n\n// ‚îÄ‚îÄ Traffic Heatmap Data (departures per hour, 6am-11pm) ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const TRAFICO_POR_HORA = [\n    { hora: '06:00', salidas: 3, llegadas: 1, label: '6 AM' },\n    { hora: '07:00', salidas: 5, llegadas: 2, label: '7 AM' },\n    { hora: '08:00', salidas: 8, llegadas: 3, label: '8 AM' },\n    { hora: '09:00', salidas: 6, llegadas: 4, label: '9 AM' },\n    { hora: '10:00', salidas: 4, llegadas: 5, label: '10 AM' },\n    { hora: '11:00', salidas: 3, llegadas: 3, label: '11 AM' },\n    { hora: '12:00', salidas: 2, llegadas: 2, label: '12 PM' },\n    { hora: '13:00', salidas: 3, llegadas: 2, label: '1 PM' },\n    { hora: '14:00', salidas: 5, llegadas: 3, label: '2 PM' },\n    { hora: '15:00', salidas: 4, llegadas: 4, label: '3 PM' },\n    { hora: '16:00', salidas: 3, llegadas: 5, label: '4 PM' },\n    { hora: '17:00', salidas: 2, llegadas: 4, label: '5 PM' },\n    { hora: '18:00', salidas: 6, llegadas: 6, label: '6 PM' },\n    { hora: '19:00', salidas: 7, llegadas: 5, label: '7 PM' },\n    { hora: '20:00', salidas: 9, llegadas: 3, label: '8 PM' },\n    { hora: '21:00', salidas: 6, llegadas: 2, label: '9 PM' },\n    { hora: '22:00', salidas: 3, llegadas: 1, label: '10 PM' },\n    { hora: '23:00', salidas: 1, llegadas: 0, label: '11 PM' },\n];\n\n// ‚îÄ‚îÄ Revenue by Route ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const INGRESOS_POR_RUTA = [\n    { ruta: 'La Paz ‚Üí Santa Cruz', ingresos: 12450, boletos: 147, ocupacion: 87 },\n    { ruta: 'La Paz ‚Üí Cochabamba', ingresos: 9800, boletos: 218, ocupacion: 92 },\n    { ruta: 'Cochabamba ‚Üí Sucre', ingresos: 5600, boletos: 160, ocupacion: 75 },\n    { ruta: 'La Paz ‚Üí Oruro', ingresos: 4200, boletos: 168, ocupacion: 82 },\n    { ruta: 'La Paz ‚Üí Potos√≠', ingresos: 3850, boletos: 70, ocupacion: 65 },\n    { ruta: 'Cochabamba ‚Üí Santa Cruz', ingresos: 7200, boletos: 120, ocupacion: 78 },\n    { ruta: 'La Paz ‚Üí Tarija', ingresos: 5100, boletos: 51, ocupacion: 58 },\n    { ruta: 'Santa Cruz ‚Üí La Paz', ingresos: 8900, boletos: 105, ocupacion: 84 },\n];\n\n// ‚îÄ‚îÄ KPI Summary ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const obtenerKPIs = () => {\n    const totalIngresos = INGRESOS_POR_RUTA.reduce((acc, r) => acc + r.ingresos, 0);\n    const totalBoletos = INGRESOS_POR_RUTA.reduce((acc, r) => acc + r.boletos, 0);\n    const rutasActivas = INGRESOS_POR_RUTA.length;\n    const ocupacionPromedio = Math.round(INGRESOS_POR_RUTA.reduce((acc, r) => acc + r.ocupacion, 0) / rutasActivas);\n    const totalSalidasDiarias = TRAFICO_POR_HORA.reduce((acc, h) => acc + h.salidas, 0);\n\n    return {\n        ingresosTotales: totalIngresos,\n        totalBoletos,\n        rutasActivas,\n        ocupacionPromedio,\n        busesEnServicio: 12,\n        salidasDiarias: totalSalidasDiarias,\n    };\n};\n\n// ‚îÄ‚îÄ Occupancy Analysis ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const obtenerAnalisisOcupacion = () => {\n    return INGRESOS_POR_RUTA.map(r => ({\n        ruta: r.ruta,\n        ocupacion: r.ocupacion,\n        estado: r.ocupacion >= 85 ? 'alta' : r.ocupacion >= 65 ? 'media' : 'baja',\n        recomendacion: r.ocupacion >= 85\n            ? 'Considerar turno extra'\n            : r.ocupacion < 60\n                ? 'Evaluar reducci√≥n de frecuencia'\n                : 'Frecuencia adecuada',\n    }));\n};\n\n// ‚îÄ‚îÄ Bus Maintenance Tracking ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const BUSES_MANTENIMIENTO = [\n    { id: 'bus-01', placa: 'ABC-1234', km: 145000, ultimoMantenimiento: '2026-02-15', viajesDesde: 82, estado: 'ok' },\n    { id: 'bus-02', placa: 'DEF-5678', km: 198000, ultimoMantenimiento: '2026-01-20', viajesDesde: 134, estado: 'alerta' },\n    { id: 'bus-03', placa: 'GHI-9012', km: 85000, ultimoMantenimiento: '2026-03-10', viajesDesde: 45, estado: 'ok' },\n    { id: 'bus-04', placa: 'JKL-3456', km: 220000, ultimoMantenimiento: '2025-12-05', viajesDesde: 180, estado: 'critico' },\n    { id: 'bus-05', placa: 'MNO-7890', km: 167000, ultimoMantenimiento: '2026-02-28', viajesDesde: 95, estado: 'alerta' },\n];\n\n// ‚îÄ‚îÄ Data for AI Context ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const generarContextoIA = () => {\n    const kpis = obtenerKPIs();\n    const ocupacion = obtenerAnalisisOcupacion();\n    const rutasAlta = ocupacion.filter(r => r.estado === 'alta');\n    const rutasBaja = ocupacion.filter(r => r.estado === 'baja');\n    const busesAlerta = BUSES_MANTENIMIENTO.filter(b => b.estado !== 'ok');\n\n    return {\n        resumen: `Terminal con ${kpis.rutasActivas} rutas activas, ${kpis.busesEnServicio} buses, Bs ${kpis.ingresosTotales.toLocaleString()} ingresos mensuales.`,\n        rutasAltaDemanda: rutasAlta.map(r => r.ruta),\n        rutasBajaDemanda: rutasBaja.map(r => r.ruta),\n        busesRequierenAtencion: busesAlerta,\n        horasPico: TRAFICO_POR_HORA.filter(h => h.salidas >= 7).map(h => h.label),\n        kpis,\n    };\n};\n\nexport default {\n    TRAFICO_POR_HORA,\n    INGRESOS_POR_RUTA,\n    obtenerKPIs,\n    obtenerAnalisisOcupacion,\n    BUSES_MANTENIMIENTO,\n    generarContextoIA,\n};\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M12 8V4H8', key: 'hb8ula' }],\n  ['rect', { width: '16', height: '12', x: '4', y: '8', rx: '2', key: 'enze0r' }],\n  ['path', { d: 'M2 14h2', key: 'vft8re' }],\n  ['path', { d: 'M20 14h2', key: '4cs60a' }],\n  ['path', { d: 'M15 13v2', key: '1xurst' }],\n  ['path', { d: 'M9 13v2', key: 'rq6x2g' }],\n];\n\n/**\n * @component @name Bot\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/bot\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Bot = createLucideIcon('bot', __iconNode);\n\nexport default Bot;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8', key: 'v9h5vc' }],\n  ['path', { d: 'M21 3v5h-5', key: '1q7to0' }],\n  ['path', { d: 'M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16', key: '3uifl3' }],\n  ['path', { d: 'M8 16H3v5', key: '1cv678' }],\n];\n\n/**\n * @component @name RefreshCw\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/refresh-cw\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst RefreshCw = createLucideIcon('refresh-cw', __iconNode);\n\nexport default RefreshCw;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  [\n    'path',\n    {\n      d: 'M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z',\n      key: '1s2grr',\n    },\n  ],\n  ['path', { d: 'M20 2v4', key: '1rf3ol' }],\n  ['path', { d: 'M22 4h-4', key: 'gwowj6' }],\n  ['circle', { cx: '4', cy: '20', r: '2', key: '6kqj1y' }],\n];\n\n/**\n * @component @name Sparkles\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/sparkles\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Sparkles = createLucideIcon('sparkles', __iconNode);\n\nexport default Sparkles;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  [\n    'path',\n    {\n      d: 'M14.536 21.686a.5.5 0 0 0 .937-.024l6.5-19a.496.496 0 0 0-.635-.635l-19 6.5a.5.5 0 0 0-.024.937l7.93 3.18a2 2 0 0 1 1.112 1.11z',\n      key: '1ffxy3',\n    },\n  ],\n  ['path', { d: 'm21.854 2.147-10.94 10.939', key: '12cjpa' }],\n];\n\n/**\n * @component @name Send\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/send\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Send = createLucideIcon('send', __iconNode);\n\nexport default Send;\n","import React, { useState, useRef, useEffect } from 'react';\nimport { Bot, Send, Sparkles, RefreshCw } from 'lucide-react';\nimport { generarContextoIA } from '../data/mockAnalyticsDB';\n\n/**\n * AsistenteIA ‚Äî AI Scheduling & Logistics Consultant.\n * \n * Two modes:\n * 1. Mock Mode (default): Intelligent local responses based on analytics data\n * 2. Gemini Mode: When REACT_APP_GEMINI_API_KEY is set in .env\n * \n * Implements exponential backoff (1s, 2s, 4s, 8s, 16s) for API calls.\n */\n\nconst GEMINI_API_KEY = process.env.REACT_APP_GEMINI_API_KEY || '';\nconst GEMINI_MODEL = 'gemini-2.5-flash-preview-04-17';\nconst MAX_RETRIES = 5;\n\nconst AsistenteIA = () => {\n    const [mensajes, setMensajes] = useState([\n        {\n            rol: 'asistente',\n            texto: '¬°Hola! Soy el Consultor Inteligente del Terminal. Puedo ayudarte con:\\n\\n‚Ä¢ üìä An√°lisis de rutas m√°s rentables\\n‚Ä¢ üöå Turnos extra para feriados\\n‚Ä¢ üîß Alertas de mantenimiento\\n‚Ä¢ üìà Pron√≥sticos de ingresos\\n\\n¬øEn qu√© puedo ayudarte?',\n            timestamp: new Date(),\n        }\n    ]);\n    const [input, setInput] = useState('');\n    const [cargando, setCargando] = useState(false);\n    const [modoIA, setModoIA] = useState(GEMINI_API_KEY ? 'gemini' : 'mock');\n    const chatRef = useRef(null);\n\n    useEffect(() => {\n        if (chatRef.current) {\n            chatRef.current.scrollTop = chatRef.current.scrollHeight;\n        }\n    }, [mensajes]);\n\n    // ‚îÄ‚îÄ Exponential Backoff for Gemini API ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\n    const llamarGeminiConBackoff = async (prompt, intento = 0) => {\n        const delay = Math.pow(2, intento) * 1000; // 1s, 2s, 4s, 8s, 16s\n\n        try {\n            const contexto = generarContextoIA();\n            const systemPrompt = `Eres un consultor experto en log√≠stica de terminales de buses en Bolivia. \nContexto del terminal: ${contexto.resumen}\nRutas de alta demanda: ${contexto.rutasAltaDemanda.join(', ')}\nRutas de baja demanda: ${contexto.rutasBajaDemanda.join(', ')}\nHoras pico: ${contexto.horasPico.join(', ')}\nBuses con alertas: ${contexto.busesRequierenAtencion.map(b => `${b.placa} (${b.estado}, ${b.km}km)`).join(', ')}\nKPIs: ${JSON.stringify(contexto.kpis)}\nResponde en espa√±ol, de forma concisa y profesional. Usa emojis para claridad.`;\n\n            const response = await fetch(\n                `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${GEMINI_API_KEY}`,\n                {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/json' },\n                    body: JSON.stringify({\n                        contents: [{ parts: [{ text: `${systemPrompt}\\n\\nPregunta del gerente: ${prompt}` }] }],\n                        generationConfig: { temperature: 0.7, maxOutputTokens: 500 },\n                    }),\n                }\n            );\n\n            if (response.status === 429 || response.status >= 500) {\n                if (intento < MAX_RETRIES) {\n                    await new Promise(res => setTimeout(res, delay));\n                    return llamarGeminiConBackoff(prompt, intento + 1);\n                }\n                throw new Error('L√≠mite de reintentos alcanzado');\n            }\n\n            const data = await response.json();\n            return data.candidates?.[0]?.content?.parts?.[0]?.text || 'No se pudo generar una respuesta.';\n        } catch (error) {\n            if (intento < MAX_RETRIES) {\n                await new Promise(res => setTimeout(res, delay));\n                return llamarGeminiConBackoff(prompt, intento + 1);\n            }\n            return `‚ö†Ô∏è Error de conexi√≥n con IA. Intenta de nuevo. (${error.message})`;\n        }\n    };\n\n    // ‚îÄ‚îÄ Mock Responses (intelligent local analysis) ‚îÄ‚îÄ\n\n    const generarRespuestaMock = (pregunta) => {\n        const ctx = generarContextoIA();\n        const q = pregunta.toLowerCase();\n\n        if (q.includes('turno') || q.includes('extra') || q.includes('feriado') || q.includes('pico')) {\n            return `üìä **An√°lisis de Turnos Extra:**\\n\\nüî• Las horas pico detectadas son: **${ctx.horasPico.join(', ')}**\\n\\nüöå Rutas que necesitan refuerzo:\\n${ctx.rutasAltaDemanda.map(r => `‚Ä¢ ${r} (demanda alta)`).join('\\n')}\\n\\nüí° **Recomendaci√≥n:** Programar 2-3 buses adicionales entre las 19:00-21:00 en las rutas La Paz ‚Üí Santa Cruz y La Paz ‚Üí Cochabamba. En feriados (Carnaval, Todos Santos) duplicar la frecuencia de salidas.`;\n        }\n\n        if (q.includes('mantenimiento') || q.includes('bus') || q.includes('alerta')) {\n            const alertas = ctx.busesRequierenAtencion;\n            return `üîß **Alertas de Mantenimiento Predictivo:**\\n\\n${alertas.map(b => \n                `‚Ä¢ **${b.placa}** ‚Äî ${b.estado.toUpperCase()}\\n  ${b.km.toLocaleString()} km, ${b.viajesDesde} viajes desde √∫ltimo servicio\\n  ${b.estado === 'critico' ? '‚ö†Ô∏è Requiere atenci√≥n INMEDIATA' : 'üü° Programar servicio esta semana'}`\n            ).join('\\n\\n')}\\n\\nüí° **Recomendaci√≥n:** Retirar ${alertas.filter(b => b.estado === 'critico').length} bus(es) cr√≠ticos de servicio y programar mantenimiento preventivo para los de alerta.`;\n        }\n\n        if (q.includes('ingreso') || q.includes('revenue') || q.includes('ganancia') || q.includes('dinero') || q.includes('plata')) {\n            return `üí∞ **Reporte de Ingresos:**\\n\\nüìà Ingresos mensuales: **Bs ${ctx.kpis.ingresosTotales.toLocaleString()}**\\nüé´ Boletos vendidos: **${ctx.kpis.totalBoletos}**\\nüìä Ocupaci√≥n promedio: **${ctx.kpis.ocupacionPromedio}%**\\n\\nüèÜ Rutas m√°s rentables:\\n${ctx.rutasAltaDemanda.map(r => `‚Ä¢ ${r}`).join('\\n')}\\n\\nüí° **Pron√≥stico:** Con la tendencia actual, se estima un crecimiento del 8-12% para el pr√≥ximo mes, especialmente en rutas interprovinciales.`;\n        }\n\n        if (q.includes('ruta') || q.includes('demanda') || q.includes('ocupaci√≥n') || q.includes('ocupacion')) {\n            return `üìä **An√°lisis de Demanda:**\\n\\nüî• **Alta demanda:**\\n${ctx.rutasAltaDemanda.map(r => `‚Ä¢ ${r}`).join('\\n')}\\n\\nüìâ **Baja demanda:**\\n${ctx.rutasBajaDemanda.map(r => `‚Ä¢ ${r}`).join('\\n')}\\n\\nüí° **Recomendaciones:**\\n1. Aumentar frecuencia en rutas de alta demanda\\n2. Ofertar promociones en rutas de baja demanda\\n3. Considerar precio din√°mico seg√∫n hora del d√≠a`;\n        }\n\n        if (q.includes('pron√≥stico') || q.includes('pronostico') || q.includes('futuro') || q.includes('predic')) {\n            return `üìà **Pron√≥stico Operativo:**\\n\\nüóìÔ∏è **Pr√≥ximo mes:**\\n‚Ä¢ Ingresos estimados: **Bs ${Math.round(ctx.kpis.ingresosTotales * 1.1).toLocaleString()}** (+10%)\\n‚Ä¢ Boletos proyectados: **${Math.round(ctx.kpis.totalBoletos * 1.08)}**\\n‚Ä¢ Rutas a reforzar: ${ctx.rutasAltaDemanda[0]}\\n\\nüîÆ **Temporada alta (Jun-Ago):**\\n‚Ä¢ Se espera aumento del 25-35% en tr√°fico\\n‚Ä¢ Recomendaci√≥n: preparar ${Math.ceil(ctx.kpis.busesEnServicio * 0.3)} buses de reserva\\n‚Ä¢ Contratar tripulaci√≥n temporal para per√≠odo vacacional`;\n        }\n\n        // Default intelligent response\n        return `üìã **Resumen del Terminal:**\\n\\n‚Ä¢ ${ctx.kpis.rutasActivas} rutas activas\\n‚Ä¢ ${ctx.kpis.busesEnServicio} buses en servicio\\n‚Ä¢ ${ctx.kpis.salidasDiarias} salidas diarias\\n‚Ä¢ Bs ${ctx.kpis.ingresosTotales.toLocaleString()} ingresos mensuales\\n‚Ä¢ ${ctx.kpis.ocupacionPromedio}% ocupaci√≥n promedio\\n\\n¬øSobre qu√© aspecto te gustar√≠a profundizar? Puedo analizar:\\n‚Ä¢ üïê Turnos extra y horas pico\\n‚Ä¢ üîß Mantenimiento de flota\\n‚Ä¢ üí∞ Ingresos y rentabilidad\\n‚Ä¢ üìä Demanda por ruta\\n‚Ä¢ üìà Pron√≥sticos operativos`;\n    };\n\n    // ‚îÄ‚îÄ Send Message Handler ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\n    const enviarMensaje = async () => {\n        if (!input.trim() || cargando) return;\n\n        const pregunta = input.trim();\n        setInput('');\n        setMensajes(prev => [...prev, { rol: 'usuario', texto: pregunta, timestamp: new Date() }]);\n        setCargando(true);\n\n        let respuesta;\n        if (modoIA === 'gemini' && GEMINI_API_KEY) {\n            respuesta = await llamarGeminiConBackoff(pregunta);\n        } else {\n            // Simulate thinking delay for realism\n            await new Promise(res => setTimeout(res, 800 + Math.random() * 600));\n            respuesta = generarRespuestaMock(pregunta);\n        }\n\n        setMensajes(prev => [...prev, { rol: 'asistente', texto: respuesta, timestamp: new Date() }]);\n        setCargando(false);\n    };\n\n    const handleKeyDown = (e) => {\n        if (e.key === 'Enter' && !e.shiftKey) {\n            e.preventDefault();\n            enviarMensaje();\n        }\n    };\n\n    // ‚îÄ‚îÄ Quick Actions ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\n    const preguntasRapidas = [\n        { texto: '¬øNecesito turnos extra?', icono: 'üöå' },\n        { texto: '¬øQu√© buses necesitan mantenimiento?', icono: 'üîß' },\n        { texto: 'Pron√≥stico de ingresos', icono: 'üìà' },\n        { texto: 'An√°lisis de ocupaci√≥n', icono: 'üìä' },\n    ];\n\n    return (\n        <div style={{\n            background: '#1e293b', borderRadius: '14px', border: '1px solid #334155',\n            overflow: 'hidden',\n        }}>\n            {/* Header */}\n            <div style={{\n                padding: '1rem 1.25rem', borderBottom: '1px solid #334155',\n                display: 'flex', justifyContent: 'space-between', alignItems: 'center',\n                background: 'linear-gradient(135deg, #1e293b, #0f172a)',\n            }}>\n                <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>\n                    <div style={{\n                        width: '36px', height: '36px', borderRadius: '10px',\n                        background: 'linear-gradient(135deg, #3b82f6, #8b5cf6)',\n                        display: 'flex', alignItems: 'center', justifyContent: 'center',\n                    }}>\n                        <Bot size={20} color=\"white\" />\n                    </div>\n                    <div>\n                        <h3 style={{ margin: 0, fontSize: '0.95rem', color: '#f1f5f9' }}>\n                            Consultor de Terminal\n                        </h3>\n                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>\n                            <span style={{\n                                width: '6px', height: '6px', borderRadius: '50%',\n                                background: modoIA === 'gemini' ? '#10b981' : '#f59e0b',\n                            }} />\n                            <span style={{ color: '#64748b', fontSize: '0.65rem' }}>\n                                {modoIA === 'gemini' ? 'Gemini AI' : 'Modo An√°lisis Local'}\n                            </span>\n                        </div>\n                    </div>\n                </div>\n                <button onClick={() => setModoIA(m => m === 'gemini' && GEMINI_API_KEY ? 'mock' : (GEMINI_API_KEY ? 'gemini' : 'mock'))}\n                    title=\"Cambiar modo\"\n                    style={{\n                        background: 'transparent', border: '1px solid #334155', borderRadius: '8px',\n                        padding: '0.3rem', cursor: 'pointer', color: '#64748b',\n                    }}>\n                    <RefreshCw size={14} />\n                </button>\n            </div>\n\n            {/* Chat Messages */}\n            <div ref={chatRef} style={{\n                height: '320px', overflowY: 'auto', padding: '1rem',\n                display: 'flex', flexDirection: 'column', gap: '0.75rem',\n            }}>\n                {mensajes.map((msg, i) => (\n                    <div key={i} style={{\n                        display: 'flex', justifyContent: msg.rol === 'usuario' ? 'flex-end' : 'flex-start',\n                    }}>\n                        <div style={{\n                            maxWidth: '85%', padding: '0.75rem 1rem', borderRadius: '12px',\n                            background: msg.rol === 'usuario'\n                                ? 'linear-gradient(135deg, #3b82f6, #2563eb)'\n                                : '#0f172a',\n                            color: '#f1f5f9', fontSize: '0.82rem', lineHeight: 1.5,\n                            border: msg.rol === 'asistente' ? '1px solid #1e293b' : 'none',\n                            whiteSpace: 'pre-wrap',\n                        }}>\n                            {msg.texto}\n                        </div>\n                    </div>\n                ))}\n\n                {cargando && (\n                    <div style={{ display: 'flex', gap: '0.4rem', padding: '0.5rem' }}>\n                        {[0, 1, 2].map(i => (\n                            <div key={i} style={{\n                                width: '8px', height: '8px', borderRadius: '50%', background: '#3b82f6',\n                                animation: `pulse 1.2s ease-in-out ${i * 0.2}s infinite`,\n                                opacity: 0.5,\n                            }} />\n                        ))}\n                        <style>{`@keyframes pulse { 0%, 100% { opacity: 0.3; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1.2); } }`}</style>\n                    </div>\n                )}\n            </div>\n\n            {/* Quick Actions */}\n            {mensajes.length <= 2 && (\n                <div style={{\n                    padding: '0 1rem 0.75rem', display: 'flex', gap: '0.4rem',\n                    overflowX: 'auto', flexWrap: 'nowrap',\n                }}>\n                    {preguntasRapidas.map((p, i) => (\n                        <button key={i} onClick={() => { setInput(p.texto); }}\n                            style={{\n                                padding: '0.4rem 0.75rem', borderRadius: '20px',\n                                border: '1px solid #334155', background: '#0f172a',\n                                color: '#94a3b8', cursor: 'pointer', fontSize: '0.72rem',\n                                whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '0.3rem',\n                            }}>\n                            {p.icono} {p.texto}\n                        </button>\n                    ))}\n                </div>\n            )}\n\n            {/* Input */}\n            <div style={{\n                padding: '0.75rem 1rem', borderTop: '1px solid #334155',\n                display: 'flex', gap: '0.5rem', alignItems: 'center',\n            }}>\n                <input\n                    type=\"text\" value={input} onChange={e => setInput(e.target.value)}\n                    onKeyDown={handleKeyDown}\n                    placeholder=\"Pregunta al consultor...\"\n                    disabled={cargando}\n                    style={{\n                        flex: 1, background: '#0f172a', border: '1px solid #334155',\n                        color: '#f1f5f9', padding: '0.7rem 1rem', borderRadius: '10px',\n                        fontSize: '0.85rem', outline: 'none',\n                    }}\n                />\n                <button onClick={enviarMensaje} disabled={cargando || !input.trim()}\n                    style={{\n                        width: '42px', height: '42px', borderRadius: '10px',\n                        background: input.trim() ? 'linear-gradient(135deg, #3b82f6, #8b5cf6)' : '#1e293b',\n                        border: 'none', cursor: input.trim() ? 'pointer' : 'not-allowed',\n                        display: 'flex', alignItems: 'center', justifyContent: 'center',\n                    }}>\n                    {cargando ? <Sparkles size={18} color=\"#f59e0b\" /> : <Send size={18} color=\"white\" />}\n                </button>\n            </div>\n        </div>\n    );\n};\n\nexport default AsistenteIA;\n","import React, { useState, useMemo } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { BarChart3, TrendingUp, Users, Bus, MapPin, AlertTriangle, Activity } from 'lucide-react';\nimport { obtenerKPIs, TRAFICO_POR_HORA, INGRESOS_POR_RUTA, obtenerAnalisisOcupacion, BUSES_MANTENIMIENTO } from '../../data/mockAnalyticsDB';\nimport AsistenteIA from '../../componentes/AsistenteIA';\n\n/**\n * DashboardAnalitico ‚Äî V4: Terminal analytics dashboard.\n * KPI cards, traffic heatmap (SVG), revenue bar chart, occupancy indicators,\n * and AI scheduling assistant.\n */\nconst DashboardAnalitico = () => {\n    const navigate = useNavigate();\n    const kpis = useMemo(() => obtenerKPIs(), []);\n    const ocupacion = useMemo(() => obtenerAnalisisOcupacion(), []);\n    const [tabActiva, setTabActiva] = useState('trafico'); // trafico | ingresos | ocupacion | mantenimiento\n\n    const maxSalidas = Math.max(...TRAFICO_POR_HORA.map(h => h.salidas));\n    const maxIngresos = Math.max(...INGRESOS_POR_RUTA.map(r => r.ingresos));\n\n    // Color intensity for heatmap\n    const heatColor = (value, max) => {\n        const intensity = value / max;\n        if (intensity >= 0.8) return '#ef4444';\n        if (intensity >= 0.6) return '#f59e0b';\n        if (intensity >= 0.3) return '#3b82f6';\n        return '#1e293b';\n    };\n\n    const ocupacionColor = (estado) => {\n        if (estado === 'alta') return '#ef4444';\n        if (estado === 'media') return '#f59e0b';\n        return '#10b981';\n    };\n\n    const mantenimientoColor = (estado) => {\n        if (estado === 'critico') return '#ef4444';\n        if (estado === 'alerta') return '#f59e0b';\n        return '#10b981';\n    };\n\n    return (\n        <div style={{ backgroundColor: '#0f172a', minHeight: '100vh', color: '#f1f5f9', padding: '1.5rem 1rem 3rem' }}>\n            <div style={{ maxWidth: '1000px', margin: '0 auto' }}>\n\n                {/* Header */}\n                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '0.5rem' }}>\n                    <div>\n                        <button onClick={() => navigate(-1)} style={{\n                            background: 'transparent', border: '1px solid #334155', color: '#94a3b8',\n                            padding: '0.4rem 0.8rem', borderRadius: '8px', cursor: 'pointer', fontSize: '0.8rem', marginBottom: '0.5rem',\n                        }}>‚Üê Volver</button>\n                        <h1 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 800, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>\n                            <Activity size={24} color=\"#3b82f6\" />\n                            Panel Anal√≠tico\n                        </h1>\n                        <p style={{ color: '#64748b', fontSize: '0.8rem', margin: '0.25rem 0 0' }}>Inteligencia operativa del terminal</p>\n                    </div>\n                </div>\n\n                {/* KPI Cards */}\n                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: '0.75rem', marginBottom: '1.5rem' }}>\n                    {[\n                        { label: 'Ingresos Mes', value: `Bs ${kpis.ingresosTotales.toLocaleString()}`, icon: <TrendingUp size={18} />, color: '#10b981' },\n                        { label: 'Boletos Vendidos', value: kpis.totalBoletos, icon: <Users size={18} />, color: '#3b82f6' },\n                        { label: 'Rutas Activas', value: kpis.rutasActivas, icon: <MapPin size={18} />, color: '#8b5cf6' },\n                        { label: 'Buses en Servicio', value: kpis.busesEnServicio, icon: <Bus size={18} />, color: '#f59e0b' },\n                        { label: 'Ocupaci√≥n Prom.', value: `${kpis.ocupacionPromedio}%`, icon: <BarChart3 size={18} />, color: '#ef4444' },\n                        { label: 'Salidas/D√≠a', value: kpis.salidasDiarias, icon: <Activity size={18} />, color: '#06b6d4' },\n                    ].map((kpi, i) => (\n                        <div key={i} style={{\n                            background: '#1e293b', borderRadius: '12px', padding: '1rem',\n                            border: '1px solid #334155',\n                        }}>\n                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', marginBottom: '0.5rem' }}>\n                                <span style={{ color: kpi.color }}>{kpi.icon}</span>\n                                <span style={{ color: '#64748b', fontSize: '0.7rem', fontWeight: 500 }}>{kpi.label}</span>\n                            </div>\n                            <div style={{ fontSize: '1.3rem', fontWeight: 700, color: '#f1f5f9' }}>\n                                {kpi.value}\n                            </div>\n                        </div>\n                    ))}\n                </div>\n\n                {/* Tab Navigation */}\n                <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem', overflowX: 'auto', flexWrap: 'nowrap' }}>\n                    {[\n                        { key: 'trafico', label: 'üóìÔ∏è Tr√°fico' },\n                        { key: 'ingresos', label: 'üí∞ Ingresos' },\n                        { key: 'ocupacion', label: 'üìä Ocupaci√≥n' },\n                        { key: 'mantenimiento', label: 'üîß Mantenimiento' },\n                    ].map(tab => (\n                        <button key={tab.key} onClick={() => setTabActiva(tab.key)}\n                            style={{\n                                padding: '0.55rem 1rem', borderRadius: '8px', border: 'none',\n                                background: tabActiva === tab.key ? '#3b82f6' : '#1e293b',\n                                color: tabActiva === tab.key ? 'white' : '#94a3b8',\n                                cursor: 'pointer', fontWeight: 600, fontSize: '0.8rem', whiteSpace: 'nowrap',\n                            }}>\n                            {tab.label}\n                        </button>\n                    ))}\n                </div>\n\n                {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê TAB: TR√ÅFICO HEATMAP ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                {tabActiva === 'trafico' && (\n                    <div style={{ background: '#1e293b', borderRadius: '14px', padding: '1.25rem', border: '1px solid #334155', marginBottom: '1.5rem' }}>\n                        <h3 style={{ margin: '0 0 0.75rem', fontSize: '1rem', color: '#f1f5f9' }}>\n                            Mapa de Calor ‚Äî Actividad del Terminal\n                        </h3>\n                        <div style={{ overflowX: 'auto' }}>\n                            <svg viewBox=\"0 0 720 200\" style={{ width: '100%', minWidth: '500px' }}>\n                                {/* Headers */}\n                                <text x=\"50\" y=\"25\" fill=\"#64748b\" fontSize=\"10\" textAnchor=\"middle\">Salidas</text>\n                                <text x=\"50\" y=\"50\" fill=\"#64748b\" fontSize=\"10\" textAnchor=\"middle\">Llegadas</text>\n\n                                {TRAFICO_POR_HORA.map((h, i) => {\n                                    const x = 90 + i * 34;\n                                    return (\n                                        <g key={h.hora}>\n                                            {/* Departure cell */}\n                                            <rect x={x} y={14} width=\"30\" height=\"18\" rx=\"3\"\n                                                fill={heatColor(h.salidas, maxSalidas)} opacity={0.85} />\n                                            <text x={x + 15} y={27} fill=\"white\" fontSize=\"8\" textAnchor=\"middle\" fontWeight=\"600\">{h.salidas}</text>\n\n                                            {/* Arrival cell */}\n                                            <rect x={x} y={38} width=\"30\" height=\"18\" rx=\"3\"\n                                                fill={heatColor(h.llegadas, maxSalidas)} opacity={0.85} />\n                                            <text x={x + 15} y={51} fill=\"white\" fontSize=\"8\" textAnchor=\"middle\" fontWeight=\"600\">{h.llegadas}</text>\n\n                                            {/* Hour label */}\n                                            <text x={x + 15} y={72} fill=\"#64748b\" fontSize=\"7\" textAnchor=\"middle\"\n                                                transform={`rotate(-45 ${x + 15} 72)`}>\n                                                {h.label}\n                                            </text>\n                                        </g>\n                                    );\n                                })}\n\n                                {/* Bar chart below */}\n                                {TRAFICO_POR_HORA.map((h, i) => {\n                                    const x = 90 + i * 34;\n                                    const barH = (h.salidas / maxSalidas) * 80;\n                                    return (\n                                        <g key={`bar-${h.hora}`}>\n                                            <rect x={x + 2} y={190 - barH} width=\"12\" height={barH} rx=\"2\"\n                                                fill=\"#3b82f6\" opacity={0.7} />\n                                            <rect x={x + 16} y={190 - (h.llegadas / maxSalidas) * 80} width=\"12\"\n                                                height={(h.llegadas / maxSalidas) * 80} rx=\"2\"\n                                                fill=\"#10b981\" opacity={0.7} />\n                                        </g>\n                                    );\n                                })}\n\n                                {/* Legend */}\n                                <rect x={90} y={88} width=\"10\" height=\"10\" rx=\"2\" fill=\"#3b82f6\" />\n                                <text x={104} y={97} fill=\"#94a3b8\" fontSize=\"8\">Salidas</text>\n                                <rect x={150} y={88} width=\"10\" height=\"10\" rx=\"2\" fill=\"#10b981\" />\n                                <text x={164} y={97} fill=\"#94a3b8\" fontSize=\"8\">Llegadas</text>\n                            </svg>\n                        </div>\n                        <p style={{ color: '#64748b', fontSize: '0.75rem', marginTop: '0.5rem' }}>\n                            üî¥ Pico alto &nbsp; üü° Moderado &nbsp; üîµ Normal &nbsp; ‚ö´ Bajo\n                        </p>\n                    </div>\n                )}\n\n                {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê TAB: INGRESOS POR RUTA ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                {tabActiva === 'ingresos' && (\n                    <div style={{ background: '#1e293b', borderRadius: '14px', padding: '1.25rem', border: '1px solid #334155', marginBottom: '1.5rem' }}>\n                        <h3 style={{ margin: '0 0 1rem', fontSize: '1rem', color: '#f1f5f9' }}>\n                            Ingresos por Ruta (Bs)\n                        </h3>\n                        {INGRESOS_POR_RUTA.sort((a, b) => b.ingresos - a.ingresos).map((r, i) => (\n                            <div key={i} style={{ marginBottom: '0.75rem' }}>\n                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.3rem' }}>\n                                    <span style={{ fontSize: '0.8rem', color: '#cbd5e1', fontWeight: 500 }}>{r.ruta}</span>\n                                    <span style={{ fontSize: '0.8rem', color: '#f59e0b', fontWeight: 700 }}>Bs {r.ingresos.toLocaleString()}</span>\n                                </div>\n                                <div style={{ background: '#0f172a', borderRadius: '6px', height: '22px', overflow: 'hidden', position: 'relative' }}>\n                                    <div style={{\n                                        width: `${(r.ingresos / maxIngresos) * 100}%`,\n                                        height: '100%', borderRadius: '6px',\n                                        background: `linear-gradient(90deg, #3b82f6, ${r.ingresos / maxIngresos > 0.7 ? '#10b981' : '#60a5fa'})`,\n                                        transition: 'width 0.6s ease',\n                                    }} />\n                                    <span style={{\n                                        position: 'absolute', right: '8px', top: '50%', transform: 'translateY(-50%)',\n                                        fontSize: '0.65rem', color: '#94a3b8',\n                                    }}>\n                                        {r.boletos} boletos\n                                    </span>\n                                </div>\n                            </div>\n                        ))}\n                    </div>\n                )}\n\n                {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê TAB: OCUPACI√ìN ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                {tabActiva === 'ocupacion' && (\n                    <div style={{ background: '#1e293b', borderRadius: '14px', padding: '1.25rem', border: '1px solid #334155', marginBottom: '1.5rem' }}>\n                        <h3 style={{ margin: '0 0 1rem', fontSize: '1rem', color: '#f1f5f9' }}>\n                            An√°lisis de Ocupaci√≥n por Ruta\n                        </h3>\n                        <div style={{ display: 'grid', gap: '0.6rem' }}>\n                            {ocupacion.map((r, i) => (\n                                <div key={i} style={{\n                                    display: 'flex', alignItems: 'center', gap: '0.75rem',\n                                    background: '#0f172a', padding: '0.85rem', borderRadius: '10px',\n                                    border: `1px solid ${ocupacionColor(r.estado)}20`,\n                                }}>\n                                    {/* Circular gauge */}\n                                    <div style={{ position: 'relative', width: '46px', height: '46px', flexShrink: 0 }}>\n                                        <svg viewBox=\"0 0 36 36\" style={{ width: '100%', transform: 'rotate(-90deg)' }}>\n                                            <circle cx=\"18\" cy=\"18\" r=\"15\" fill=\"none\" stroke=\"#1e293b\" strokeWidth=\"3\" />\n                                            <circle cx=\"18\" cy=\"18\" r=\"15\" fill=\"none\"\n                                                stroke={ocupacionColor(r.estado)}\n                                                strokeWidth=\"3\"\n                                                strokeDasharray={`${r.ocupacion * 0.94} 100`}\n                                                strokeLinecap=\"round\" />\n                                        </svg>\n                                        <span style={{\n                                            position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',\n                                            fontSize: '0.65rem', fontWeight: 700, color: ocupacionColor(r.estado),\n                                        }}>{r.ocupacion}%</span>\n                                    </div>\n\n                                    <div style={{ flex: 1, minWidth: 0 }}>\n                                        <div style={{ fontSize: '0.85rem', fontWeight: 600, color: '#f1f5f9' }}>{r.ruta}</div>\n                                        <div style={{ fontSize: '0.72rem', color: '#64748b', marginTop: '0.15rem' }}>\n                                            {r.recomendacion}\n                                        </div>\n                                    </div>\n\n                                    <span style={{\n                                        padding: '0.2rem 0.6rem', borderRadius: '6px', fontSize: '0.65rem', fontWeight: 600,\n                                        background: `${ocupacionColor(r.estado)}15`, color: ocupacionColor(r.estado),\n                                        border: `1px solid ${ocupacionColor(r.estado)}30`,\n                                    }}>\n                                        {r.estado === 'alta' ? 'üî• Alta' : r.estado === 'media' ? 'üìä Media' : 'üìâ Baja'}\n                                    </span>\n                                </div>\n                            ))}\n                        </div>\n                    </div>\n                )}\n\n                {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê TAB: MANTENIMIENTO ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                {tabActiva === 'mantenimiento' && (\n                    <div style={{ background: '#1e293b', borderRadius: '14px', padding: '1.25rem', border: '1px solid #334155', marginBottom: '1.5rem' }}>\n                        <h3 style={{ margin: '0 0 0.25rem', fontSize: '1rem', color: '#f1f5f9', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>\n                            <AlertTriangle size={18} color=\"#f59e0b\" /> Mantenimiento Predictivo\n                        </h3>\n                        <p style={{ color: '#64748b', fontSize: '0.75rem', marginBottom: '1rem' }}>\n                            Alertas basadas en km recorridos y viajes desde √∫ltimo servicio\n                        </p>\n                        <div style={{ display: 'grid', gap: '0.6rem' }}>\n                            {BUSES_MANTENIMIENTO.sort((a, b) => {\n                                const order = { critico: 0, alerta: 1, ok: 2 };\n                                return order[a.estado] - order[b.estado];\n                            }).map(bus => (\n                                <div key={bus.id} style={{\n                                    display: 'flex', alignItems: 'center', gap: '0.75rem',\n                                    background: '#0f172a', padding: '0.85rem', borderRadius: '10px',\n                                    borderLeft: `3px solid ${mantenimientoColor(bus.estado)}`,\n                                }}>\n                                    <div style={{\n                                        width: '40px', height: '40px', borderRadius: '10px',\n                                        background: `${mantenimientoColor(bus.estado)}15`,\n                                        display: 'flex', alignItems: 'center', justifyContent: 'center',\n                                        fontSize: '1.2rem', flexShrink: 0,\n                                    }}>\n                                        üöå\n                                    </div>\n                                    <div style={{ flex: 1 }}>\n                                        <div style={{ fontWeight: 600, fontSize: '0.9rem', color: '#f1f5f9' }}>{bus.placa}</div>\n                                        <div style={{ fontSize: '0.72rem', color: '#64748b' }}>\n                                            {bus.km.toLocaleString()} km ¬∑ {bus.viajesDesde} viajes desde servicio\n                                        </div>\n                                        <div style={{ fontSize: '0.7rem', color: '#475569' }}>\n                                            √öltimo: {bus.ultimoMantenimiento}\n                                        </div>\n                                    </div>\n                                    <span style={{\n                                        padding: '0.25rem 0.6rem', borderRadius: '6px', fontSize: '0.65rem', fontWeight: 700,\n                                        background: `${mantenimientoColor(bus.estado)}15`,\n                                        color: mantenimientoColor(bus.estado),\n                                        border: `1px solid ${mantenimientoColor(bus.estado)}30`,\n                                        textTransform: 'uppercase',\n                                    }}>\n                                        {bus.estado === 'critico' ? '‚ö†Ô∏è Cr√≠tico' : bus.estado === 'alerta' ? 'üü° Alerta' : '‚úÖ OK'}\n                                    </span>\n                                </div>\n                            ))}\n                        </div>\n                    </div>\n                )}\n\n                {/* ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê AI ASSISTANT ‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê‚ïê */}\n                <AsistenteIA />\n            </div>\n        </div>\n    );\n};\n\nexport default DashboardAnalitico;\n","import React, { useState, useCallback } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { supabase } from '../../servicios/supabase';\nimport '../../estilos/escritorio/admin.css';\nimport '../../estilos/escritorio/mapa-asientos.css';\nimport '../../estilos/movil/admin-responsivo.css';\n\nconst AMENIDADES_DISPONIBLES = [\n    { id: 'WiFi',              icono: 'üì∂' },\n    { id: 'USB',               icono: 'üîå' },\n    { id: 'Aire Acondicionado',icono: '‚ùÑÔ∏è' },\n    { id: 'Bus Cama',          icono: 'üõèÔ∏è' },\n    { id: 'TV',                icono: 'üì∫' },\n    { id: 'Ba√±o',              icono: 'üöø' },\n    { id: 'Calefacci√≥n',       icono: 'üî•' },\n];\n\nconst BusPreviewMini = ({ config }) => {\n    const { pisos, columnas, filasPiso1, filasPiso2, tieneBano } = config;\n    const colsDer = columnas === 4 ? 2 : 1;\n    const colsIzq = 2;\n    const totalSeats = colsIzq + colsDer;\n    const gridCols   = columnas === 4\n        ? '36px 36px 12px 36px 36px 18px'\n        : '36px 36px 12px 36px 18px';\n\n    const renderFila = (piso, fila) => {\n        const asientos = [];\n        for (let c = 1; c <= totalSeats; c++) {\n            const letra  = String.fromCharCode(64 + c);\n            const numero = `${fila}${letra}`;\n            const demo   = ['disponible', 'disponible', 'ocupado', 'pendiente'];\n            const estado = demo[(fila + c) % demo.length];\n            asientos.push(\n                <div\n                    key={`p${piso}-f${fila}-c${c}`}\n                    className={`asiento-btn ${estado}`}\n                    style={{ width: 36, height: 36, marginTop: 6, pointerEvents: 'none', fontSize: '0.5rem', cursor: 'default' }}\n                    title={numero}\n                >\n                    <span className=\"asiento-numero\" style={{ opacity: 1, fontSize: '0.45rem' }}>{numero}</span>\n                </div>\n            );\n            if (c === colsIzq) {\n                asientos.push(\n                    <div key={`pasillo-${piso}-${fila}`} className=\"bus-pasillo-visual\" style={{ width: 12, height: 42, margin: '6px 0 0' }} />\n                );\n            }\n        }\n        asientos.push(\n            <div key={`fn-${piso}-${fila}`} className=\"fila-numero\" style={{ fontSize: '0.55rem', color: '#475569' }}>{fila}</div>\n        );\n        return (\n            <div key={`fila-${piso}-${fila}`} style={{ display: 'grid', gridTemplateColumns: gridCols, gap: 4, alignItems: 'center' }}>\n                {asientos}\n            </div>\n        );\n    };\n\n    return (\n        <div className=\"bus-preview-contenedor\">\n            <div className=\"bus-preview-titulo\">Vista previa del bus</div>\n            <div className=\"bus-cuerpo\" style={{ transform: 'scale(0.85)', transformOrigin: 'top center' }}>\n                <div className=\"bus-frente\" style={{ padding: '4px 8px' }}>\n                    <span className=\"bus-volante\" style={{ fontSize: '1rem' }}>üöå</span>\n                    <span className=\"bus-puerta-etiqueta\" style={{ fontSize: '0.55rem' }}>üö™ Puerta</span>\n                </div>\n                <div className=\"bus-interior\">\n                    <div className=\"bus-piso\">\n                        {pisos === 2 && <div className=\"bus-piso-label\">Piso 1</div>}\n                        {Array.from({ length: filasPiso1 }, (_, i) => renderFila(1, i + 1))}\n                        {tieneBano && (\n                            <div className=\"bus-zona-bano\" style={{ fontSize: '0.65rem' }}>üöø Ba√±o</div>\n                        )}\n                    </div>\n                    {pisos === 2 && filasPiso2 > 0 && (\n                        <>\n                            <hr className=\"bus-separador-piso\" />\n                            <div className=\"bus-piso\">\n                                <div className=\"bus-piso-label\">Piso 2</div>\n                                {Array.from({ length: filasPiso2 }, (_, i) => renderFila(2, i + 1))}\n                            </div>\n                        </>\n                    )}\n                </div>\n                <div className=\"bus-trasera\" />\n            </div>\n            <div style={{ fontSize: '0.68rem', color: '#475569', marginTop: '.4rem' }}>\n                {pisos === 2 ? `2 pisos ¬∑ ` : `1 piso ¬∑ `}\n                {columnas === 4 ? '2+2 cols' : '2+1 cols'} ¬∑ {\n                    (filasPiso1 * totalSeats) + (pisos === 2 ? filasPiso2 * totalSeats : 0)\n                } asientos\n            </div>\n        </div>\n    );\n};\n\nconst RegistroBus = () => {\n    const navigate = useNavigate();\n\n    const [form, setForm] = useState({\n        sucursal_id:  '',\n        placa:        '',\n        pisos:        1,\n        columnas:     4,\n        filas_piso_1: 10,\n        filas_piso_2: 8,\n        tiene_bano:   false,\n        amenidades:   [],\n    });\n\n    const [placaEstado, setPlacaEstado]   = useState(null);\n    const [errores,     setErrores]       = useState({});\n    const [feedback,    setFeedback]      = useState(null);\n    const [guardando,   setGuardando]     = useState(false);\n    const [sucursales,  setSucursales]    = useState([]);\n\n    React.useEffect(() => {\n        const fetchSucursales = async () => {\n            try {\n                const { data } = await supabase\n                    .from('sucursales')\n                    .select('id, nombre')\n                    .order('nombre');\n                if (data) setSucursales(data);\n            } catch (err) {\n                console.error('RegistroBus - fetchSucursales error:', err);\n            }\n        };\n        fetchSucursales();\n    }, []);\n\n    const setField = (campo, valor) => {\n        setForm(prev => ({ ...prev, [campo]: valor }));\n        setErrores(prev => ({ ...prev, [campo]: null }));\n    };\n\n    const toggleAmenidad = (id) => {\n        setForm(prev => ({\n            ...prev,\n            amenidades: prev.amenidades.includes(id)\n                ? prev.amenidades.filter(a => a !== id)\n                : [...prev.amenidades, id],\n        }));\n    };\n\n    const verificarPlaca = async () => {\n        const placa = form.placa.trim().toUpperCase();\n        if (!placa || placa.length < 5) return;\n\n        setPlacaEstado('cargando');\n        try {\n            const { data, error } = await supabase\n                .from('buses')\n                .select('id')\n                .eq('placa', placa)\n                .maybeSingle();\n\n            if (error) throw error;\n            setPlacaEstado(data ? 'duplicado' : 'ok');\n            if (data) {\n                setErrores(prev => ({ ...prev, placa: 'Esta placa ya est√° registrada.' }));\n            }\n        } catch (err) {\n            console.error('RegistroBus - Error verificando placa:', err);\n            setPlacaEstado(null);\n        }\n    };\n\n    const previewConfig = useCallback(() => ({\n        pisos:        form.pisos,\n        columnas:     form.columnas,\n        filasPiso1:   Math.max(1, Math.min(20, Number(form.filas_piso_1) || 10)),\n        filasPiso2:   form.pisos === 2 ? Math.max(1, Math.min(20, Number(form.filas_piso_2) || 8)) : 0,\n        tieneBano:    form.tiene_bano,\n    }), [form]);\n\n    const validar = () => {\n        const errs = {};\n        if (!form.placa.trim())   errs.placa       = 'La placa es obligatoria.';\n        if (placaEstado === 'duplicado') errs.placa = 'Esta placa ya est√° registrada.';\n        if (!form.filas_piso_1 || form.filas_piso_1 < 1) errs.filas_piso_1 = 'M√≠nimo 1 fila.';\n        if (form.pisos === 2 && (!form.filas_piso_2 || form.filas_piso_2 < 1)) {\n            errs.filas_piso_2 = 'M√≠nimo 1 fila en piso 2.';\n        }\n        setErrores(errs);\n        return Object.keys(errs).length === 0;\n    };\n\n    const handleGuardar = async (e) => {\n        e.preventDefault();\n        if (!validar()) return;\n\n        setGuardando(true);\n        setFeedback(null);\n\n        const colsDer  = form.columnas === 4 ? 2 : 1;\n        const capPiso1 = form.filas_piso_1 * (2 + colsDer);\n        const capPiso2 = form.pisos === 2 ? form.filas_piso_2 * (2 + colsDer) : 0;\n\n        try {\n            const { error } = await supabase\n                .from('buses')\n                .insert([{\n                    sucursal_id:  form.sucursal_id || null,\n                    placa:        form.placa.trim().toUpperCase(),\n                    capacidad:    capPiso1 + capPiso2,\n                    pisos:        form.pisos,\n                    columnas:     form.columnas,\n                    filas_piso_1: Number(form.filas_piso_1),\n                    filas_piso_2: form.pisos === 2 ? Number(form.filas_piso_2) : 0,\n                    tiene_bano:   form.tiene_bano,\n                    amenidades:   form.amenidades,\n                    estado:       'disponible',\n                }]);\n\n            if (error) throw error;\n\n            setFeedback({ tipo: 'exito', msg: `‚úÖ Bus ${form.placa.toUpperCase()} registrado. Capacidad: ${capPiso1 + capPiso2} asientos.` });\n            setForm({ sucursal_id: '', placa: '', pisos: 1, columnas: 4, filas_piso_1: 10, filas_piso_2: 8, tiene_bano: false, amenidades: [] });\n            setPlacaEstado(null);\n        } catch (err) {\n            console.error('RegistroBus - Error al guardar:', err);\n            setFeedback({ tipo: 'error', msg: `‚ùå Error al guardar: ${err.message}` });\n        } finally {\n            setGuardando(false);\n        }\n    };\n\n    return (\n        <div className=\"pagina-admin\">\n            <div className=\"admin-banner\">\n                <span className=\"admin-banner-icono\">‚öôÔ∏è</span>\n                Panel Administrativo\n            </div>\n\n            <div className=\"admin-header\">\n                <button className=\"btn-volver-admin\" onClick={() => navigate(-1)} id=\"btn-volver-bus\">‚Üê Volver</button>\n                <div>\n                    <h1>Registrar Bus</h1>\n                    <div className=\"admin-header-sub\">Configura el layout y las caracter√≠sticas del veh√≠culo</div>\n                </div>\n            </div>\n\n            <form className=\"admin-contenido\" onSubmit={handleGuardar} noValidate>\n                {feedback && (\n                    <div className={`admin-feedback ${feedback.tipo}`}>{feedback.msg}</div>\n                )}\n\n                <div className=\"admin-seccion\">\n                    <div className=\"admin-seccion-titulo\">\n                        <span className=\"seccion-icono\">üöå</span> Identificaci√≥n del Bus\n                    </div>\n                    <div className=\"admin-seccion-cuerpo\">\n                        <div className=\"campos-grid-2\">\n                            <div className=\"campo-grupo\">\n                                <label className=\"campo-label\">Placa <span className=\"campo-requerido\">*</span></label>\n                                <input\n                                    type=\"text\"\n                                    className={`campo-input ${errores.placa ? 'error' : placaEstado === 'ok' ? 'ok' : ''}`}\n                                    value={form.placa}\n                                    onChange={e => { setField('placa', e.target.value.toUpperCase()); setPlacaEstado(null); }}\n                                    onBlur={verificarPlaca}\n                                    placeholder=\"Ej: ABC-1234\"\n                                    id=\"input-placa\"\n                                    maxLength={10}\n                                />\n                                {placaEstado === 'cargando' && (\n                                    <div className=\"campo-cargando\"><div className=\"spinner-mini\" /> Verificando placa...</div>\n                                )}\n                                {placaEstado === 'ok' && <div className=\"campo-ok-msg\">‚úì Placa disponible</div>}\n                                {errores.placa && <div className=\"campo-error-msg\">{errores.placa}</div>}\n                            </div>\n\n                            <div className=\"campo-grupo\">\n                                <label className=\"campo-label\">Sucursal (Empresa)</label>\n                                <select\n                                    className=\"campo-select\"\n                                    value={form.sucursal_id}\n                                    onChange={e => setField('sucursal_id', e.target.value)}\n                                    id=\"select-sucursal\"\n                                >\n                                    <option value=\"\">Sin asignar</option>\n                                    {sucursales.map(s => (\n                                        <option key={s.id} value={s.id}>{s.nombre}</option>\n                                    ))}\n                                </select>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div className=\"admin-seccion\">\n                    <div className=\"admin-seccion-titulo\">\n                        <span className=\"seccion-icono\">üìê</span> Layout del Bus\n                    </div>\n                    <div className=\"admin-seccion-cuerpo\">\n                        <div className=\"campo-grupo\">\n                            <label className=\"campo-label\">N√∫mero de Pisos <span className=\"campo-requerido\">*</span></label>\n                            <div className=\"toggle-grupo\">\n                                {[1, 2].map(n => (\n                                    <button\n                                        key={n}\n                                        type=\"button\"\n                                        className={`toggle-btn ${form.pisos === n ? 'activo' : ''}`}\n                                        onClick={() => setField('pisos', n)}\n                                        id={`btn-pisos-${n}`}\n                                    >\n                                        {n === 1 ? 'üöå 1 Piso' : 'üöåüöå 2 Pisos'}\n                                    </button>\n                                ))}\n                            </div>\n                        </div>\n\n                        <div className=\"campo-grupo\">\n                            <label className=\"campo-label\">Configuraci√≥n de Columnas <span className=\"campo-requerido\">*</span></label>\n                            <div className=\"toggle-grupo\">\n                                <button\n                                    type=\"button\"\n                                    className={`toggle-btn ${form.columnas === 4 ? 'activo' : ''}`}\n                                    onClick={() => setField('columnas', 4)}\n                                    id=\"btn-cols-4\"\n                                >\n                                    ü™ëü™ë | ü™ëü™ë ‚Äî 4 cols (2+2)\n                                </button>\n                                <button\n                                    type=\"button\"\n                                    className={`toggle-btn ${form.columnas === 3 ? 'activo' : ''}`}\n                                    onClick={() => setField('columnas', 3)}\n                                    id=\"btn-cols-3\"\n                                >\n                                    ü™ëü™ë | ü™ë ‚Äî 3 cols (2+1)\n                                </button>\n                            </div>\n                        </div>\n\n                        <div className={`campos-grid-${form.pisos === 2 ? '2' : '1'}`}>\n                            <div className=\"campo-grupo\">\n                                <label className=\"campo-label\">\n                                    Filas Piso 1 <span className=\"campo-requerido\">*</span>\n                                </label>\n                                <input\n                                    type=\"number\"\n                                    className={`campo-input ${errores.filas_piso_1 ? 'error' : ''}`}\n                                    value={form.filas_piso_1}\n                                    onChange={e => setField('filas_piso_1', Number(e.target.value))}\n                                    min={1} max={20}\n                                    id=\"input-filas-1\"\n                                />\n                                <div className=\"campo-hint\">\n                                    ‚Üí {form.filas_piso_1 * (form.columnas === 4 ? 4 : 3)} asientos en piso 1\n                                </div>\n                                {errores.filas_piso_1 && <div className=\"campo-error-msg\">{errores.filas_piso_1}</div>}\n                            </div>\n\n                            {form.pisos === 2 && (\n                                <div className=\"campo-grupo\">\n                                    <label className=\"campo-label\">\n                                        Filas Piso 2 <span className=\"campo-requerido\">*</span>\n                                    </label>\n                                    <input\n                                        type=\"number\"\n                                        className={`campo-input ${errores.filas_piso_2 ? 'error' : ''}`}\n                                        value={form.filas_piso_2}\n                                        onChange={e => setField('filas_piso_2', Number(e.target.value))}\n                                        min={1} max={20}\n                                        id=\"input-filas-2\"\n                                    />\n                                    <div className=\"campo-hint\">\n                                        ‚Üí {form.filas_piso_2 * (form.columnas === 4 ? 4 : 3)} asientos en piso 2\n                                    </div>\n                                    {errores.filas_piso_2 && <div className=\"campo-error-msg\">{errores.filas_piso_2}</div>}\n                                </div>\n                            )}\n                        </div>\n\n                        <div className=\"campo-grupo\">\n                            <label className=\"campo-label\">Ba√±o</label>\n                            <div className=\"toggle-grupo\">\n                                <button\n                                    type=\"button\"\n                                    className={`toggle-btn ${form.tiene_bano ? 'activo' : ''}`}\n                                    onClick={() => setField('tiene_bano', true)}\n                                    id=\"btn-bano-si\"\n                                >\n                                    üöø Con Ba√±o\n                                </button>\n                                <button\n                                    type=\"button\"\n                                    className={`toggle-btn ${!form.tiene_bano ? 'activo' : ''}`}\n                                    onClick={() => setField('tiene_bano', false)}\n                                    id=\"btn-bano-no\"\n                                >\n                                    Sin Ba√±o\n                                </button>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n\n                <BusPreviewMini config={previewConfig()} />\n\n                <div className=\"admin-seccion\">\n                    <div className=\"admin-seccion-titulo\">\n                        <span className=\"seccion-icono\">‚ú®</span> Amenidades\n                    </div>\n                    <div className=\"admin-seccion-cuerpo\">\n                        <div className=\"amenidades-grid\">\n                            {AMENIDADES_DISPONIBLES.map(a => (\n                                <button\n                                    key={a.id}\n                                    type=\"button\"\n                                    className={`amenidad-tag ${form.amenidades.includes(a.id) ? 'activo' : ''}`}\n                                    onClick={() => toggleAmenidad(a.id)}\n                                    id={`amenidad-${a.id.replace(/\\s/g, '-')}`}\n                                >\n                                    {a.icono} {a.id}\n                                </button>\n                            ))}\n                        </div>\n                    </div>\n                </div>\n\n                <div className=\"admin-footer\" style={{ borderRadius: '0 0 14px 14px' }}>\n                    <button type=\"button\" className=\"btn-admin-cancelar\" onClick={() => navigate(-1)} disabled={guardando}>\n                        Cancelar\n                    </button>\n                    <button\n                        type=\"submit\"\n                        className=\"btn-admin-guardar\"\n                        disabled={guardando || placaEstado === 'duplicado'}\n                        id=\"btn-guardar-bus\"\n                    >\n                        {guardando ? 'Guardando...' : 'üíæ Guardar Bus'}\n                    </button>\n                </div>\n\n            </form>\n        </div>\n    );\n};\n\nexport default RegistroBus;\n","import React, { useState } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { supabase } from '../../servicios/supabase';\nimport '../../estilos/escritorio/admin.css';\nimport '../../estilos/movil/admin-responsivo.css';\n\nconst RegistroTripulacion = () => {\n    const navigate = useNavigate();\n\n    // Estado del formulario\n    const [formData, setFormData] = useState({\n        ci: '',\n        nombre: '',\n        telefono: '',\n        rol: 'conductor' // conductor | copiloto | ayudante\n    });\n\n    const [archivos, setArchivos] = useState({\n        foto: null,\n        licencia: null\n    });\n    \n    // UI States\n    const [cargando, setCargando] = useState(false);\n    const [ciDuplicado, setCiDuplicado] = useState(false);\n    const [verificandoCi, setVerificandoCi] = useState(false);\n    const [mensaje, setMensaje] = useState(null); // { texto, tipo }\n\n    // Handlers inputs texto\n    const handleChange = (e) => {\n        setFormData({\n            ...formData,\n            [e.target.name]: e.target.value\n        });\n    };\n\n    // Handler Rol Toggle\n    const toggleRol = (nuevoRol) => {\n        setFormData({ ...formData, rol: nuevoRol });\n    };\n\n    // Verificar unicidad de CI al perder el foco (onBlur)\n    const verificarCI = async () => {\n        if (!formData.ci) return;\n        setVerificandoCi(true);\n\n        try {\n            const { data, error } = await supabase\n                .from('tripulacion')\n                .select('id')\n                .eq('ci', formData.ci)\n                .maybeSingle();\n\n            if (data) {\n                setCiDuplicado(true);\n            } else {\n                setCiDuplicado(false);\n            }\n        } catch (error) {\n            console.error('Error comprobando CI:', error);\n        } finally {\n            setVerificandoCi(false);\n        }\n    };\n\n    // Manejar selecci√≥n de archivos para previsualizaci√≥n simulada\n    const handleFileChange = (e, tipo) => {\n        if (e.target.files && e.target.files[0]) {\n            const file = e.target.files[0];\n            setArchivos({ ...archivos, [tipo]: file });\n        }\n    };\n\n    // Generar preview en base64 para visualizar *antes* de subir\n    const getPreviewUrl = (tipo) => {\n        if (archivos[tipo]) {\n            return URL.createObjectURL(archivos[tipo]);\n        }\n        return null;\n    };\n\n    // Subir archivos a Supabase Storage\n    const uploadFile = async (file, path) => {\n        const fileExt = file.name.split('.').pop();\n        const fileName = `${path}-${Math.random()}.${fileExt}`;\n        const filePath = `tripulacion/${fileName}`;\n\n        try {\n            let { error: uploadError } = await supabase.storage\n                .from('tripulacion-fotos') // Requiere que exista el bucket!\n                .upload(filePath, file);\n\n            if (uploadError) throw uploadError;\n\n            // Conseguir URL p√∫blica\n            const { data } = supabase.storage.from('tripulacion-fotos').getPublicUrl(filePath);\n            return data.publicUrl;\n        } catch (error) {\n            console.warn('Fallo Supabase Storage (Probablemente no existe el Bucket). Usaremos URL mock.');\n            return `https://fakeurl.tbb/${filePath}`; // Retorno simulado si falla en dev\n        }\n    };\n\n    // Submit Guardar\n    const handleSubmit = async (e) => {\n        e.preventDefault();\n        \n        if (ciDuplicado) return;\n        if (!formData.ci || !formData.nombre) {\n            setMensaje({ tipo: 'error', texto: 'Por favor complete todos los campos obligatorios.' });\n            return;\n        }\n\n        setCargando(true);\n        setMensaje(null);\n\n        try {\n            // Simulamos o intentamos subir al storage\n            let fotoUrl = null;\n            let licenciaUrl = null;\n\n            if (archivos.foto) {\n                fotoUrl = await uploadFile(archivos.foto, `foto_${formData.ci}`);\n            }\n            if (archivos.licencia) {\n                licenciaUrl = await uploadFile(archivos.licencia, `licencia_${formData.ci}`);\n            }\n\n            // Insert a Supabase DB\n            const { error: dbError } = await supabase\n                .from('tripulacion')\n                .insert([{\n                    ci: formData.ci,\n                    nombre_completo: formData.nombre,\n                    telefono: formData.telefono,\n                    rol: formData.rol,\n                    sucursal_id: null, // Asumimos que se auto-rellena con la sucursal del Admin si lo enlazamos o null\n                    foto_perfil_url: fotoUrl,\n                    foto_licencia_url: licenciaUrl\n                }]);\n\n            if (dbError && dbError.code === '42P01') {\n                throw new Error(\"La tabla 'tripulacion' a√∫n no existe en esta rama de la base de datos.\");\n            } else if (dbError) {\n                throw dbError;\n            }\n\n            setMensaje({ tipo: 'exito', texto: 'Personal de tripulaci√≥n registrado exitosamente.' });\n            \n            // Limpiar form\n            setFormData({ ci: '', nombre: '', telefono: '', rol: 'conductor' });\n            setArchivos({ foto: null, licencia: null });\n            \n        } catch (error) {\n            console.error(error);\n            setMensaje({ tipo: 'error', texto: error.message || 'Error al registrar.' });\n        } finally {\n            setCargando(false);\n        }\n    };\n\n    return (\n        <div className=\"pagina-admin\">\n            <div className=\"admin-banner\">\n                <span className=\"admin-banner-icono\">üõ°Ô∏è</span>\n                Panel Administrativo Seguro\n            </div>\n\n            <div className=\"admin-header\">\n                <button className=\"btn-volver-admin\" onClick={() => navigate('/admin/dashboard')}>\n                    ‚Üê Volver\n                </button>\n                <div>\n                    <h1>Registro de Tripulaci√≥n</h1>\n                    <div className=\"admin-header-sub\">Agregue nuevos conductores y asigne roles.</div>\n                </div>\n            </div>\n\n            <main className=\"admin-contenido\">\n                \n                {mensaje && (\n                    <div className={`admin-feedback ${mensaje.tipo}`}>\n                        {mensaje.texto}\n                    </div>\n                )}\n\n                <form onSubmit={handleSubmit}>\n                    <div className=\"admin-seccion\">\n                        <div className=\"admin-seccion-titulo\">\n                            <span className=\"seccion-icono\">üë§</span>\n                            Datos Personales\n                        </div>\n                        \n                        <div className=\"admin-seccion-cuerpo\">\n                            <div className=\"campos-grid-2\">\n                                {/* CI Input con chequeo onBlur */}\n                                <div className=\"campo-grupo\">\n                                    <label className=\"campo-label\">CI <span className=\"campo-requerido\">*</span></label>\n                                    <input\n                                        type=\"text\"\n                                        name=\"ci\"\n                                        className={`campo-input ${ciDuplicado ? 'error' : formData.ci.length >= 5 && !verificandoCi ? 'ok' : ''}`}\n                                        value={formData.ci}\n                                        onChange={handleChange}\n                                        onBlur={verificarCI}\n                                        required\n                                        placeholder=\"Carnet de Identidad\"\n                                    />\n                                    {verificandoCi && <span className=\"campo-cargando\"><div className=\"spinner-mini\"></div> Verificando...</span>}\n                                    {ciDuplicado && <span className=\"campo-error-msg\">Este CI ya est√° registrado.</span>}\n                                    {!ciDuplicado && formData.ci.length >= 5 && !verificandoCi && <span className=\"campo-ok-msg\">CI Disponible</span>}\n                                </div>\n\n                                {/* Nombre Input */}\n                                <div className=\"campo-grupo\">\n                                    <label className=\"campo-label\">Nombre Completo <span className=\"campo-requerido\">*</span></label>\n                                    <input\n                                        type=\"text\"\n                                        name=\"nombre\"\n                                        className=\"campo-input\"\n                                        value={formData.nombre}\n                                        onChange={handleChange}\n                                        required\n                                        placeholder=\"Ej. Juan P√©rez\"\n                                    />\n                                </div>\n\n                                {/* Tel√©fono Input */}\n                                <div className=\"campo-grupo\">\n                                    <label className=\"campo-label\">Tel√©fono</label>\n                                    <input\n                                        type=\"tel\"\n                                        name=\"telefono\"\n                                        className=\"campo-input\"\n                                        value={formData.telefono}\n                                        onChange={handleChange}\n                                        placeholder=\"Ej. 77012345\"\n                                    />\n                                </div>\n\n                                {/* Rol Toggle */}\n                                <div className=\"campo-grupo\">\n                                    <label className=\"campo-label\">Rol en el Bus <span className=\"campo-requerido\">*</span></label>\n                                    <div className=\"toggle-grupo\">\n                                        <div \n                                            className={`toggle-btn ${formData.rol === 'conductor' ? 'activo' : ''}`}\n                                            onClick={() => toggleRol('conductor')}\n                                        >\n                                            Conductor\n                                        </div>\n                                        <div \n                                            className={`toggle-btn ${formData.rol === 'copiloto' ? 'activo' : ''}`}\n                                            onClick={() => toggleRol('copiloto')}\n                                        >\n                                            Copiloto\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div className=\"admin-seccion\">\n                        <div className=\"admin-seccion-titulo\">\n                            <span className=\"seccion-icono\">üì∑</span>\n                            Documentos y Fotograf√≠a\n                        </div>\n                        \n                        <div className=\"admin-seccion-cuerpo\">\n                            <div className=\"campos-grid-2\">\n                                \n                                {/* Upload Foto */}\n                                <div className=\"campo-grupo\">\n                                    <label className=\"campo-label\">Foto de Perfil</label>\n                                    <div style={{ display: 'flex', gap: '1rem', alignItems: 'center', marginTop: '0.5rem' }}>\n                                        <div style={{ width: '80px', height: '80px', backgroundColor: '#0f172a', border: '1px dashed #475569', borderRadius: '50%', overflow: 'hidden', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>\n                                            {getPreviewUrl('foto') ? (\n                                                <img src={getPreviewUrl('foto')} alt=\"Preview\" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />\n                                            ) : (\n                                                <span style={{ fontSize: '2rem' }}>üë§</span>\n                                            )}\n                                        </div>\n                                        <input\n                                            type=\"file\"\n                                            accept=\"image/png, image/jpeg\"\n                                            onChange={(e) => handleFileChange(e, 'foto')}\n                                            style={{ color: '#94a3b8' }}\n                                        />\n                                    </div>\n                                </div>\n\n                                {/* Upload Licencia */}\n                                <div className=\"campo-grupo\">\n                                    <label className=\"campo-label\">Fotograf√≠a de Licencia de Conducir</label>\n                                    <div style={{ display: 'flex', gap: '1rem', alignItems: 'center', marginTop: '0.5rem' }}>\n                                        <div style={{ width: '120px', height: '75px', backgroundColor: '#0f172a', border: '1px dashed #475569', borderRadius: '8px', overflow: 'hidden', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>\n                                            {getPreviewUrl('licencia') ? (\n                                                <img src={getPreviewUrl('licencia')} alt=\"Preview Licencia\" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />\n                                            ) : (\n                                                <span style={{ fontSize: '1.5rem', color: '#475569' }}>ü™™</span>\n                                            )}\n                                        </div>\n                                        <input\n                                            type=\"file\"\n                                            accept=\"image/png, image/jpeg\"\n                                            onChange={(e) => handleFileChange(e, 'licencia')}\n                                            style={{ color: '#94a3b8' }}\n                                        />\n                                    </div>\n                                </div>\n\n                            </div>\n                        </div>\n                    </div>\n\n                    <div className=\"admin-footer\">\n                        <button type=\"button\" className=\"btn-admin-cancelar\" onClick={() => navigate('/admin/dashboard')}>\n                            Descartar\n                        </button>\n                        <button \n                            type=\"submit\" \n                            className=\"btn-admin-guardar\"\n                            disabled={cargando || ciDuplicado || !formData.ci || !formData.nombre}\n                        >\n                            {cargando ? 'Registrando...' : 'Registrar Personal'}\n                        </button>\n                    </div>\n                </form>\n            </main>\n        </div>\n    );\n};\n\nexport default RegistroTripulacion;\n","import React from 'react';\nimport { Navigate, useLocation } from 'react-router-dom';\nimport { useAuth } from '../contextos/AuthContext';\n\n// ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n// ProtectedRoute ‚Äî Envuelve rutas que requieren Auth\n// Verifica sesi√≥n y opcionalmente el rol del usuario.\n// ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nconst ProtectedRoute = ({ children, rolesPermitidos }) => {\n    const { sesion, perfil, cargandoAuth } = useAuth();\n    const location = useLocation();\n\n    // 1. Mostrar estado de carga mientras Supabase verifica sesi√≥n local\n    if (cargandoAuth) {\n        return (\n            <div style={{ display: 'flex', height: '100vh', alignItems: 'center', justifyContent: 'center', background: '#0f172a', color: '#fff' }}>\n                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>\n                    <div className=\"spinner-mini\" style={{ width: '30px', height: '30px', borderTopColor: '#3b82f6' }} />\n                    Verificando credenciales...\n                </div>\n            </div>\n        );\n    }\n\n    // 2. Redirigir a Login si no hay sesi√≥n\n    if (!sesion) {\n        // Guarda la ruta original para redirigir post-login (si se implementa)\n        return <Navigate to=\"/login\" state={{ from: location }} replace />;\n    }\n\n    // 3. Verificaci√≥n de Rol (RBAC)\n    if (rolesPermitidos && rolesPermitidos.length > 0) {\n        // Aseguramos que el perfil est√© cargado y su rol coincida\n        if (!perfil) return <Navigate to=\"/\" replace />;\n        \n        if (!rolesPermitidos.includes(perfil.rol)) {\n            // Usuario autenticado pero sin permisos para esta ruta\n            return (\n                <div style={{ padding: '2rem', textAlign: 'center', color: '#ef4444', fontFamily: 'sans-serif' }}>\n                    <h2>Acceso Denegado</h2>\n                    <p>No tienes los permisos requeridos ({rolesPermitidos.join(', ')}) para ver esta p√°gina.</p>\n                </div>\n            );\n        }\n    }\n\n    // Usuario v√°lido y autorizado -> Renderizar el componente hijo\n    return children;\n};\n\nexport default ProtectedRoute;\n","/**\n * mockStorage.js\n * Local data store for V3 Transactional features.\n * Uses localStorage as persistence layer. Ready to \"plug-and-play\" into Supabase later.\n * \n * Data structures:\n *  - reservas: Array of reservation objects\n *  - estadoViajes: Map of trip statuses (programado, en_ruta, finalizado)\n *  - asientosPendientes: Array of seats with pending timestamps for timer cleanup\n */\n\nconst STORAGE_KEYS = {\n    RESERVAS: 'tbb_reservas',\n    ESTADO_VIAJES: 'tbb_estado_viajes',\n    ASIENTOS_PENDIENTES: 'tbb_asientos_pendientes',\n    VENTAS: 'tbb_ventas',\n};\n\n// ‚îÄ‚îÄ Helpers ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nconst leer = (key) => {\n    try {\n        const raw = localStorage.getItem(key);\n        return raw ? JSON.parse(raw) : null;\n    } catch {\n        return null;\n    }\n};\n\nconst guardar = (key, data) => {\n    localStorage.setItem(key, JSON.stringify(data));\n};\n\nconst generarId = () => 'res-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6);\n\n// ‚îÄ‚îÄ Reservas ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\n/**\n * Validates that none of the requested seats are already reserved for this trip.\n */\nexport const validarDisponibilidad = (viajeId, asientos) => {\n    const reservas = leer(STORAGE_KEYS.RESERVAS) || [];\n    const asientosOcupados = reservas\n        .filter(r => r.viajeId === viajeId && r.estado === 'confirmada')\n        .flatMap(r => r.asientos);\n    \n    const conflictos = asientos.filter(a => asientosOcupados.includes(a));\n    return { disponible: conflictos.length === 0, conflictos };\n};\n\nexport const crearReserva = ({ viajeId, pasajeroNombre, pasajeroCI, pasajeroTelefono, asientos, busPlaca, origen, destino, precio, fechaSalida }) => {\n    // Double-booking validation\n    const { disponible, conflictos } = validarDisponibilidad(viajeId, asientos);\n    if (!disponible) {\n        return { error: true, mensaje: `Asientos ya reservados: ${conflictos.join(', ')}` };\n    }\n\n    const reservas = leer(STORAGE_KEYS.RESERVAS) || [];\n    \n    const nueva = {\n        id: generarId(),\n        viajeId,\n        pasajeroNombre,\n        pasajeroCI,\n        pasajeroTelefono: pasajeroTelefono || '',\n        asientos,\n        busPlaca: busPlaca || 'ABC-1234',\n        origen: origen || 'La Paz',\n        destino: destino || 'Cochabamba',\n        precio: precio || asientos.length * 45,\n        fechaSalida: fechaSalida || new Date().toISOString(),\n        estado: 'confirmada',\n        creadoEn: new Date().toISOString(),\n    };\n\n    reservas.push(nueva);\n    guardar(STORAGE_KEYS.RESERVAS, reservas);\n\n    // Register sale for analytics\n    registrarVenta(nueva);\n\n    return nueva;\n};\n\n/**\n * Registers a sale record for analytics aggregation (Branch 4 bridge).\n */\nexport const registrarVenta = (reserva) => {\n    const ventas = leer(STORAGE_KEYS.VENTAS) || [];\n    ventas.push({\n        id: 'venta-' + Date.now(),\n        reservaId: reserva.id,\n        ruta: `${reserva.origen} ‚Üí ${reserva.destino}`,\n        monto: reserva.precio,\n        boletos: reserva.asientos.length,\n        fecha: new Date().toISOString(),\n    });\n    guardar(STORAGE_KEYS.VENTAS, ventas);\n};\n\n/**\n * Get all sales (for analytics dashboard).\n */\nexport const obtenerVentas = () => {\n    return leer(STORAGE_KEYS.VENTAS) || [];\n};\n\nexport const obtenerReservas = (viajeId = null) => {\n    const reservas = leer(STORAGE_KEYS.RESERVAS) || [];\n    if (viajeId) return reservas.filter(r => r.viajeId === viajeId);\n    return reservas;\n};\n\nexport const obtenerReservaPorId = (id) => {\n    const reservas = leer(STORAGE_KEYS.RESERVAS) || [];\n    return reservas.find(r => r.id === id) || null;\n};\n\n// ‚îÄ‚îÄ Estado de Viajes (Conductor) ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const obtenerEstadoViaje = (viajeId) => {\n    const estados = leer(STORAGE_KEYS.ESTADO_VIAJES) || {};\n    return estados[viajeId] || 'programado';\n};\n\nexport const actualizarEstadoViaje = (viajeId, nuevoEstado) => {\n    const estados = leer(STORAGE_KEYS.ESTADO_VIAJES) || {};\n    estados[viajeId] = nuevoEstado; // programado | en_ruta | finalizado\n    guardar(STORAGE_KEYS.ESTADO_VIAJES, estados);\n    return nuevoEstado;\n};\n\n// ‚îÄ‚îÄ Asientos Pendientes (Timer) ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ‚îÄ\n\nexport const marcarAsientosPendientes = (viajeId, asientos) => {\n    const pendientes = leer(STORAGE_KEYS.ASIENTOS_PENDIENTES) || [];\n    const ahora = Date.now();\n    \n    asientos.forEach(asiento => {\n        // Remove existing entry for this seat if any\n        const idx = pendientes.findIndex(p => p.viajeId === viajeId && p.asiento === asiento);\n        if (idx !== -1) pendientes.splice(idx, 1);\n        \n        pendientes.push({\n            viajeId,\n            asiento,\n            marcadoEn: ahora,\n            expiraEn: ahora + (15 * 60 * 1000), // 15 minutes\n        });\n    });\n    \n    guardar(STORAGE_KEYS.ASIENTOS_PENDIENTES, pendientes);\n    return pendientes;\n};\n\nexport const obtenerAsientosPendientes = (viajeId = null) => {\n    const pendientes = leer(STORAGE_KEYS.ASIENTOS_PENDIENTES) || [];\n    if (viajeId) return pendientes.filter(p => p.viajeId === viajeId);\n    return pendientes;\n};\n\nexport const liberarAsientosExpirados = () => {\n    const pendientes = leer(STORAGE_KEYS.ASIENTOS_PENDIENTES) || [];\n    const ahora = Date.now();\n    const vigentes = pendientes.filter(p => p.expiraEn > ahora);\n    const expirados = pendientes.filter(p => p.expiraEn <= ahora);\n    \n    guardar(STORAGE_KEYS.ASIENTOS_PENDIENTES, vigentes);\n    return { liberados: expirados, vigentes };\n};\n\n// ‚îÄ‚îÄ Mock de 